const CHAPTERS: VizChapter[] = [{"id":"cpp-ch01","subj":"cpp","title":"C++ 基础语法：类型、变量与引用","summary":"基本类型、变量常量、运算符与表达式；引用与指针的区别；std::string/std::vector 基础；搭建编译环境。","concepts":[{"id":"cpp-ch01/01-types-and-references","file":"01-types-and-references.md","title":"变量、类型与引用","kind":"flow","secs":[{"h":"一、类型决定了什么","s":"","c":null},{"h":"二、初始化的四种写法不是同义词","s":"四种写法对内置类型几乎无差别，对类类型却有实质区别：拷贝初始化要求类型可隐式转换且不允许用 explicit 构造；直接初始化允许；列表初始化禁止窄化转换（int x{3.14} 直接编译失败），因此它是现代 C++ 推荐默认。","c":{"lang":"cpp","code":"int a = 42;        // 拷贝初始化\nint b(42);         // 直接初始化\nint c{42};         // 列表初始化（C++11）\nint d{};           // 值初始化 → 0"}},{"h":"三、引用是别名，不是指针","s":"int& r = a; 让 r 成为 a 的另一个名字。三条硬规则：必须初始化、不可重新绑定、没有空引用。语言层面引用不是对象：它没有地址、不能放进数组、不存在\"引用的引用\"（int&& 是右值引用，另一回事）。","c":{"lang":"cpp","code":"const std::string& s = std::string(\"tmp\") + \"!\";\n// 临时对象生命周期被延长到 s 离开作用域，此处安全\n\nconst std::string& bad() {\n    return std::string(\"tmp\");   // 返回引用，但被绑定的临时对象在此销毁\n}                                // → 悬垂引用，未定义行为"}},{"h":"四、传参怎么选：一张决策表","s":"判据是语义而不是\"快不快\"：按值传递表达\"我拿到一份副本，改它不影响你\"；const T& 表达\"我要看，不复制\"；T& 表达\"我要改你的\"。当语义确定后，性能自然跟着来——反过来按性能选语义，就会写出\"参数是 T& 却从不修改\"这种让…","c":{"lang":"text","code":"参数传递决策表\n\n  内建类型（int/double/指针）      → 按值 T\n  只读的大对象（string/vector/自定义类） → const T&\n  需要修改调用方的对象             → T&\n  需要表达\"可能没有\"               → T* （或 std::optional<T>）\n  需要转移所有权                   → std::unique_ptr<T>（移动）\n  需要共享所有权                   → std::shared_ptr<T>"}},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：验证别名与生命周期","s":"这段程序把本章三个核心事实一次验证完：引用与原变量同地址、const& 延长临时对象寿命（析构发生在作用域末尾而不是语句末尾）、有符号与无符号比较、整除截断。","c":{"lang":"cpp","code":"#include <iostream>\n#include <string>\n\nstruct Probe {\n    std::string tag;\n    explicit Probe(std::string t) : tag(std::move(t)) { std::cout << \"ctor \" << tag << \"\\n\"; }\n    ~Probe() { std::cout << \"dtor \" << tag << \"\\n\"; }\n};\n\n…"}}]},{"id":"cpp-ch01/02-type-deduction-auto","file":"02-type-deduction-auto.md","title":"类型推导与 auto","kind":"flow","secs":[{"h":"一、auto 的推导规则：和模板一模一样","s":"auto 的推导规则刻意与模板参数推导保持一致：把 auto 换成 T，就得到一个函数模板。所以理解 auto 等于理解 template<typename T> void f(T)。","c":{"lang":"cpp","code":"template <typename T>\nvoid relay(T&& v) { sink(std::forward<T>(v)); }   // T&& 在模板中是转发引用"}},{"h":"二、花括号与 auto 的历史坑","s":"auto x{1} 的推导在标准演进中改过一次：C++11/14 中 auto x{1} 被推导为 std::initializer_list<int>，C++17 起改为 int（N3922）。同一行代码在不同标准下类型不同，跨编译器…","c":null},{"h":"三、auto 在工程里的真实收益与代价","s":"","c":null},{"h":"四、范围 for 的三种写法","s":"范围 for 展开后是 auto&& __range = v; auto __begin = begin(__range); ...。注意两点：遍历时不要修改容器结构（push_back 会让迭代器失效，UB）；临时容器也能被遍历，因为…","c":{"lang":"cpp","code":"for (auto x : v)        { /* 拷贝，改 x 不影响 v；大对象慎用 */ }\nfor (auto& x : v)       { /* 引用，可修改 v */ }\nfor (const auto& x : v) { /* 只读引用，无拷贝 —— 遍历的默认选择 */ }"}},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：一张表验完三种推导","s":"typeid(...).name() 的输出是实现相关的修饰名（GCC 会给 i、Ri 这类缩写，c++filt 才能还原可读形式），所以这段程序只用它做\"三种写法是否同类\"的对比，不把它当字符串匹配的判据——这是跨编译器可移植的写法。","c":{"lang":"cpp","code":"#include <cstddef>\n#include <iostream>\n#include <typeinfo>\n#include <vector>\n\nint main() {\n    int a = 1;\n    const int c = 2;\n    int& r = a;\n…"}}]},{"id":"cpp-ch01/03-std-string-vector","file":"03-std-string-vector.md","title":"std::string 与 std::vector 入门","kind":"stack","secs":[{"h":"一、std::string 是什么：带所有权语义的字节容器","s":"std::string 的本质是 std::basic_string<char>：一段连续的 char，加长度，加容量。它不含编码信息——\"字符串\"在 C++ 里就是字节序列，UTF-8 的中文一个字占 3 字节，size() 返回的是…","c":{"lang":"text","code":"std::string 的两种存储形态（libstdc++，64 位）\n\n  短串（≤15 字节）      长串（>15 字节）\n  ┌──────────────┐      ┌──────────────┐\n  │ ptr ────────►│ 指向  │ ptr ─────────┼──► 堆上缓冲\n  │ size         │ 自身  │ size         │\n  │ 内联缓冲 16B │ 缓冲  │ capacity     │\n  └──────────────┘      └──────────────┘\n  无堆分配              1 次分配 + 扩容时搬移"}},{"h":"二、std::vector<T> 是什么：三指针 + 扩容策略","s":"vector 的经典实现是三个指针：begin（首元素）、end（末尾后一位）、capacity_end（容量末尾）。因此 size() 与 capacity() 都是指针相减，O(1)，且 size() 不需要额外字段。","c":{"lang":"cpp","code":"std::vector<int> v;\nv.reserve(1000);            // 一次分配，避免 10 次扩容\nfor (int i = 0; i < 1000; ++i) v.push_back(i);"}},{"h":"三、与 C 风格接口的边界","s":"std::string 与 std::vector 都能和 C API 互操作，但边界上容易出事：","c":{"lang":"cpp","code":"std::string s = \"abc\";\nconst char* p = s.c_str();     // 仅在下一次修改前有效\ns += \"def\";                    // 可能扩容 → p 悬垂"}},{"h":"四、选型：什么时候不用 vector","s":"vector 是默认选择，因为它对缓存最友好：连续内存让预取器有活干，这是它在实测中常常比\"理论上更快\"的链表快一个数量级的原因。","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：观察容量增长与 SSO","s":"这段程序同时验证了三件事：容量按倍数增长（次数是 O(log n)）、reserve 只改容量不改长度、string 直接拼接可用。容量增长的具体倍数由实现决定（libstdc++ 是 2 倍，libc++ 常见 1.5 倍），所以别把…","c":{"lang":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\n\nint main() {\n    std::string name = \"Cpp\";\n    std::string greet = \"Hello \" + name;\n    std::cout << greet << \" len=\" << greet.size() << \"\\n\";\n\n…"}}]},{"id":"cpp-ch01/04-basics-practical-recipes","file":"04-basics-practical-recipes.md","title":"§4 cpp-ch01 实战手记：凯喵带你把 C++ 基础用「炸」","kind":"flow","secs":[{"h":"现场一：引用绑定到临时对象，离开作用域变悬垂","s":"凯喵写 const std::string& s = getTemp(); 以为引用延长了临时对象生命。延长只在「引用直接绑定临时对象」时成立；若函数返回的是引用，临时对象早已销毁，s 悬垂。要安全就按值接。","c":{"lang":"cpp","code":"std::string getTemp();          // 返回对象\nconst std::string& f();         // 返回引用\nconst std::string s1 = getTemp();   // ✅ 拷贝/移动，安全\n// const std::string& s2 = f();   // ❌ 悬垂，f 返回的临时已死"}},{"h":"现场二：auto 退化掉引用和 const，副本悄悄产生","s":"凯喵写 for (auto x : vec) 想改元素，结果原 vector 纹丝不动——auto 按值拷贝。要改元素用 auto&；只读大对象用 const auto&；要移动用 auto&&。auto 不会自动保留引用，必须自己写…","c":{"lang":"cpp","code":"std::vector<int> v = {1,2,3};\nfor (auto x : v) x = 0;        // ❌ 改的是副本\nfor (auto& x : v) x = 0;      // ✅ 改的是原元素\nfor (const auto& x : v) { /* 只读，避免拷贝 */ }"}},{"h":"现场三：有符号与无符号混比，-1 秒变超大正数","s":"凯喵写 int i = -1; if (i < v.size()) ...，结果条件为 false。size() 返回无符号 size_t，-1 被转成极大值 4294967295，比较直接翻转。混用有/无符号是 UB 温床，统一用 s…","c":{"lang":"cpp","code":"std::vector<int> v(5);\n// for (int i = 0; i < v.size(); ++i)  // ❌ 类型不匹配隐患\nfor (size_t i = 0; i < v.size(); ++i) { }  // ✅ 同类型\nfor (int x : v) { }                          // ✅ 范围 for 最稳"}},{"h":"现场四：reserve 当成 resize 用，v[0] 直接越界 UB","s":"凯喵 v.reserve(10) 后直接 v[0] = 1，程序崩溃。reserve 只扩容量不变大小，size() 仍是 0，下标访问越界是未定义行为。要长度用 resize，要容量用 reserve。","c":{"lang":"cpp","code":"std::vector<int> v;\nv.reserve(10);                 // capacity=10, size=0\n// v[0] = 1;                   // ❌ 越界 UB\nv.resize(10);                  // ✅ size=10，可下标\nv.push_back(1);                // ✅ 或 push_back 增长"}},{"h":"现场五：c_str() 指针跨修改使用，悬垂","s":"凯喵 const char p = s.c_str(); s += \"x\"; printf(p);，打印出垃圾。c_str() 返回的指针在 s 被修改（可能扩容搬迁）后失效。C 接口调用要在同一表达式或紧邻作用域内完成，别长期持有。","c":{"lang":"cpp","code":"std::string s = \"hi\";\nconst char* p = s.c_str();\n// s += \"!\";                   // ❌ 之后 p 可能悬垂\nprintf(\"%s\\n\", s.c_str());     // ✅ 紧邻调用"}},{"h":"现场六：const T& 绑定函数返回的引用不延长生命周期","s":"凯喵 const std::string& s = factory_ref();，factory_ref 返回引用，临时对象在 return 语句结束即销毁，s 悬垂。生命周期延长规则只认「引用直接绑定临时」，经过一层返回值就失效。","c":{"lang":"cpp","code":"const std::string& factory_ref();\n// const std::string& s = factory_ref();  // ❌ 悬垂\nstd::string s = factory_ref();            // ✅ 拷贝出来"}},{"h":"现场七：列表初始化才挡窄化，= 初始化静默截断","s":"凯喵 int x = 3.14; 以为会报错，结果 x 静默变成 3。用 = 的初始化允许窄化（丢精度）；用 {} 的列表初始化禁止窄化，编译期就抓出来，默认用 {} 更安全。","c":{"lang":"cpp","code":"int a = 3.14;     // ❌ 静默截断为 3\nint b{3.14};      // ✅ 编译报错，挡住窄化\nstd::vector<int> v{1,2,3};   // ✅ 推荐初始化风格"}},{"h":"现场八：string 拼接用 + 连 char 而不是 string，类型错乱","s":"凯喵 std::string s = \"x\" + 'c'; 编译不过——\"x\" 是 const char[2]，'c' 是 char，两边都不是 std::string，+ 不认识。至少一侧是 std::string 才能拼接。","c":{"lang":"cpp","code":"std::string s = std::string(\"x\") + 'c';   // ✅ 左操作数是 string\ns += 'c';                                  // ✅ += 重载可用\n// std::string t = \"x\" + 'c';              // ❌ 无 string 参与"}},{"h":"现场九：迭代器失效，erase 后还用旧迭代器","s":"凯喵边遍历边 erase，用旧迭代器继续走，直接崩。vector 的 erase 会让被删位置之后的迭代器全部失效。正确写法：it = v.erase(it) 用返回值续上；或反向遍历。","c":{"lang":"cpp","code":"for (auto it = v.begin(); it != v.end(); ) {\n    if (*it % 2 == 0) it = v.erase(it);   // ✅ 用返回值续上\n    else ++it;\n}"}},{"h":"现场十：vector 扩容搬迁，旧指针/引用全废","s":"凯喵持有一个 &v[0] 的引用，之后 push_back 触发扩容，vector 搬到新内存，引用指向旧地址。扩容后所有指向元素的指针/引用/迭代器失效。需要稳定地址用 std::list / std::deque / 存索引而非引用…","c":{"lang":"cpp","code":"std::vector<int> v{1,2,3};\nint& r = v[0];\nv.push_back(4);     // 可能扩容，r 悬垂\n// 改存下标安全：size_t idx = 0; ... v[idx] ..."}},{"h":"现场十一：用 NULL 而非 nullptr，重载歧义","s":"凯喵写 f(NULL) 想传空指针，却调到了 f(int) 重载。NULL 是整数 0，nullptr 才是真正的指针字面量。C++11 起一律用 nullptr，类型安全无歧义。","c":{"lang":"cpp","code":"void f(int); void f(char*);\nf(NULL);     // ❌ 可能选 f(int)\nf(nullptr);  // ✅ 明确选 f(char*)"}},{"h":"现场十二：未初始化局部变量，读到随机垃圾","s":"凯喵 int x; if (cond) x = 1; cout << x; 有时输出巨大随机数。局部非静态变量不默认初始化，走未初始化分支就是 UB。定义即初始化（用 {} 还能顺带挡窄化）。","c":{"lang":"cpp","code":"int x{};          // ✅ 值初始化为 0\n// int x;         // ❌ 未初始化，读它是 UB"}},{"h":"🧑‍💻 程序员视角","s":"把 const auto& x = f(); 写成 auto x = f();，一个百万行的 vector 就被整份复制了一次——auto 的推导规则会剥掉引用与顶层 const，这是 C++ 里最贵的一行节省。reserve 与 re…","c":null},{"h":"🎓 博士生视角","s":"C++ 的初始化语义可以按「值类别 + 生命周期」两轴理解：引用绑定临时对象会延长其生命周期（const T& 绑临时），但 T&& 成员绑定的临时只活到构造函数结束，这是悬垂引用的经典来源。auto 的推导遵循模板实参推导规则（aut…","c":null},{"h":"📚 考研者视角","s":"面试与笔试高频点：","c":null}]}],"exams":[{"kind":"choice","q":"关于引用，下列说法正确的是","stem":"选择所有正确的描述。","opts":[{"k":"A","t":"引用定义后可以不初始化"},{"k":"B","t":"引用一旦绑定就不能改绑其他对象"},{"k":"C","t":"const 引用可以绑定到临时对象"},{"k":"D","t":"引用占用独立的存储空间，与指针完全相同"}],"ans":"BC","why":"引用必须初始化且不可改绑；const 引用可延长临时对象生命周期；引用是否占存储是实现细节，语义上是别名。"},{"kind":"fix_error","q":"修复悬垂引用","stem":"以下代码返回局部变量的引用，存在未定义行为，请修复： cpp int& make() { int x = 42; return x; }","opts":[],"ans":"int make() { int x = 42; return x; }","why":"按值返回即可；不要返回局部对象的引用或指针。"},{"kind":"output","q":"读代码写输出","stem":"cpp #include <iostream> int main() { int a = 5; int& r = a; r += 2; std::cout << a << \" \" << r; }","opts":[],"ans":"7 7","why":"r 是 a 的别名，修改 r 即修改 a。"},{"kind":"coding","q":"读取 n 个数求和","stem":"第一行输入 n（1≤n≤1000），第二行输入 n 个整数，输出它们的和。","opts":[],"ans":"#include <iostream> int main(){int n;std::cin>>n;long long s=0;for(int i=0;i<n;i++){long long x;std::cin>>x;s+=x;}std::cout<<s;}","why":"注意用 long long 防溢出。"},{"kind":"coding","q":"反转字符串中的单词","stem":"反转字符串中单词的顺序（LeetCode 151）。请用 C++ 实现，注意只保留单词之间的单个空格。题面详见原题链接，本题不搬运题面正文。","opts":[],"ans":"#include <iostream> #include <vector> #include <string> int main(){std::vector<std::string> v;std::string w;while(std::cin>>w)v.push_back(w);for(auto it=v.rbegi…","why":"练习 vector 与迭代器的基本使用。"}],"works":[{"h":"引用返回局部变量","d":"函数返回 int& 指向局部变量 = 悬垂引用，未定义行为。"},{"h":"using namespace std; 写进头文件","d":"污染所有包含者的命名空间，只允许在 .cpp 内使用。"},{"h":"整数除法截断","d":"double avg = sum / n; 当 sum、n 都是 int 时先整除再转 double，结果丢失小数。应写 sum / static_cast<double>(n)。"},{"h":"std::vector<bool> 不是普通容器","d":"它是位压缩特化，&v[0] 不能得到 bool。"},{"h":"局部 int x; 不初始化","d":"函数内的 int x; 值是垃圾；只有命名空间作用域与 static 局部才零初始化。声明即初始化（int x{};）是最省事的防线。"},{"h":"auto 按值推导会丢引用与顶层 const","d":"auto x = ref; 是拷贝而不是别名，改 x 不动原对象；需要别名写 auto&，需要只读别名写 const auto&。"},{"h":"有符号与无符号混比","d":"-1 > 0u 为真，因为 -1 先转成 4294967295u。for (int i = 0; i < v.size(); ++i) 在 size() 极大或 i 为负时都会出事，用 std::size_t 或范围 for。"},{"h":"reserve 当成 resize 用","d":"v.reserve(10) 后 size() 仍是 0，此时 v[0] 是越界 UB。要长度用 resize，要容量用 reserve。"}],"asks":[{"q":"指针和引用有什么区别？","a":"1) 引用必须初始化且不可改绑，指针可以；2) 引用没有空值语义（设计上），指针有 nullptr；3) 引用是别名，sizeof 得到被引用对象大小；4) 使用场景：参数传递优先 const 引用，需要可空/可改绑/地址运算时用指针。","fu":["const 引用绑定临时对象的生命周期规则？","什么时候必须用指针而不能用引用？"],"tag":"通用"},{"q":"为什么不建议在头文件里写 using namespace std？","a":"头文件会被多个翻译单元包含，using 指令会污染所有包含者的全局命名空间，可能引发名称冲突且难以定位。允许在 .cpp 文件内局部使用，或使用 using std::cout 等精确声明。","fu":["ADL 是什么？它与命名空间有什么关系？"],"tag":"通用"},{"q":"int a = 5; double d = a / 2; 结果是多少？为什么？","a":"2.0。a / 2 是整数除法，先得到 int 结果 2，再隐式转换为 double 2.0。要得到 2.5 需让任一操作数为浮点：a / 2.0 或 static_cast<double>(a) / 2。","fu":["整型提升规则是什么？","窄化转换在列表初始化中会怎样？"],"tag":"通用"}]},{"id":"cpp-ch02","subj":"cpp","title":"函数：声明/定义、重载、默认参数与 lambda","summary":"函数声明与定义分离；参数传递（值/引用/指针）；函数重载决议；默认参数；inline；lambda 表达式与捕获；函数对象初步。","concepts":[{"id":"cpp-ch02/01-function-decl-def","file":"01-function-decl-def.md","title":"函数声明与定义","kind":"flow","secs":[{"h":"一、为什么必须分声明和定义","s":"C++ 的编译单元（TU）模型决定了：编译器一次只看到一个 .cpp 加上它包含的头文件。调用别处定义的函数时，编译器不需要函数体，只需要签名来检查调用是否合法、并生成一个待重定位的符号引用。真正的地址由链接器在最后一步填上。","c":{"lang":"cpp","code":"// math_utils.h —— 只有声明\n#pragma once\nint add(int a, int b);\ndouble add(double a, double b);"}},{"h":"二、单定义规则（ODR）","s":"ODR 用一句话概括：每个实体在整个程序中恰好定义一次。例外是三类\"允许每个 TU 各有一份、但必须逐字相同\"的实体：","c":null},{"h":"三、名字修饰与 extern \"C\"","s":"C++ 支持重载，所以链接层的符号名必须携带参数信息——这就是名字修饰（name mangling）。int add(int,int) 在 Itanium ABI 下会变成类似 _Z3addii 的符号。这样同名不同参的两个函数在链接层…","c":{"lang":"cpp","code":"#ifdef __cplusplus\nextern \"C\" {\n#endif\n\nint c_api_compute(int x);\n\n#ifdef __cplusplus\n}\n#endif"}},{"h":"四、参数传递的三种方式","s":"三者的选择依据是语义：是否需要看到变化（引用）、是否允许缺失（指针）、是否要隔离（值）。性能是次要考虑，且通常与语义方向一致。","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：重载与默认参数的真实行为","s":"想看名字修饰的真实样貌，用 nm -C 看符号表，或用 g++ -S 看汇编里的调用目标——重载函数在汇编里是两个不同名字，这是\"重载发生在编译期\"最直接的证据。","c":{"lang":"cpp","code":"#include <iostream>\n#include <string>\n\n// 同名重载：链接层是两个不同符号\nint add(int a, int b) { return a + b; }\ndouble add(double a, double b) { return a + b; }\n\n// 默认参数只在一处给（这里是定义，因为单文件演示）\nstd::string greet(const std::string& name, const std::string& suffix = \"!\");\n…"}}]},{"id":"cpp-ch02/02-overload-default-args","file":"02-overload-default-args.md","title":"函数重载与默认参数","kind":"flow","secs":[{"h":"一、重载解决的是什么问题","s":"同名函数，只要参数列表不同（类型 / 个数 / 顺序）即可重载；返回类型不参与。表面上是\"少记几个名字\"，本质是把同一个抽象操作的多种实现放在一个名字下，让调用点表达意图而不是表达类型。","c":{"lang":"cpp","code":"int square(int x)       { return x * x; }\ndouble square(double x) { return x * x; }   // 合法重载"}},{"h":"二、重载决议的四级阶梯","s":"编译器把候选函数按实参到形参的转换序列排序，优先级从高到低：","c":{"lang":"cpp","code":"void f(long x);\nvoid f(double x);\nf(1);        // 有歧义：int→long 与 int→double 同为「标准转换」"}},{"h":"三、默认参数：调用点的静态填充","s":"默认参数只能从右往左连续给定，且只能在声明或定义中提供一次。","c":{"lang":"cpp","code":"void greet(const std::string& name, const std::string& suffix = \"!\");\n// 调用 greet(\"Cat\") 等价于 greet(\"Cat\", \"!\")"}},{"h":"四、= delete 与 = default：对重载集合做精确控制","s":"= delete 把一个函数声明\"删除\"，它仍参与重载决议但被选中时编译报错。这是禁止隐式转换的标准手段：","c":{"lang":"cpp","code":"void process(int x);\nvoid process(double) = delete;   // 禁止 process(3.14) 静默截断"}},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：验证动态绑定与静态默认参数","s":"这段程序把\"函数体动态、默认参数静态\"这条规则钉死了：同一个对象、同一个函数体，默认值却不同。","c":{"lang":"cpp","code":"#include <iostream>\n\nstruct Base {\n    virtual ~Base() = default;\n    virtual void log(int level = 1) const { std::cout << \"Base/\" << level << \"\\n\"; }\n};\n\nstruct Derived : Base {\n    void log(int level = 2) const override { std::cout << \"Derived/\" << level << \"\\n\"; }\n…"}}]},{"id":"cpp-ch02/03-lambda-captures","file":"03-lambda-captures.md","title":"lambda 表达式与捕获","kind":"timeline","secs":[{"h":"一、捕获方式与它们的真实含义","s":"","c":{"lang":"text","code":"lambda 展开后的等价类（[&total](int x){ total += x; }）\n\n  struct __lambda_1 {\n      int& total;                          // 引用捕获 → 引用成员\n      void operator()(int x) const { total += x; }   // 默认 const\n  };\n\n  [=] 展开 → 成员是 int total;（副本）\n  [x] 展开 → 成员是 int x;（同名副本）"}},{"h":"二、闭包类型的四个硬事实","s":"1. 每个 lambda 的类型唯一且无名：两个写法完全相同的 lambda 也是不同类型，所以只能用 auto 或模板参数接，不能写类型名。","c":null},{"h":"三、生命周期：唯一真正危险的地方","s":"按引用捕获不改变任何生命周期，它只是一个引用。因此当 lambda 比被捕获变量活得长时就会悬垂：","c":{"lang":"cpp","code":"std::function<void()> make() {\n    int local = 42;\n    return [&local]() { std::cout << local; };   // 悬垂：local 已销毁\n}"}},{"h":"四、lambda 与 std::function、模板的取舍","s":"选择依据：需要存储/传递异构可调用对象 → std::function；就地使用 → auto 或模板。","c":null},{"h":"五、泛型 lambda 与 constexpr","s":"泛型 lambda 的 operator() 是模板，因此每个实参类型组合都实例化一份。这带来一个坑：同一个泛型 lambda 对不同类型可能返回不同类型，用它做 std::function 参数时会因类型不一致而编译失败。","c":{"lang":"cpp","code":"auto add = [](auto a, auto b) { return a + b; };   // C++14 泛型 lambda\nauto twice = [](auto x) constexpr { return x * 2; }; // C++17 起可 constexpr"}},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：三种捕获的实际效果","s":"关键看两处：by_val 连调两次得到 7、8（副本被累加，外部 total 不变），以及无捕获 lambda 能赋给函数指针——后者是\"闭包无状态才能退化\"的直接证据。[base = total] 演示初始化捕获，这个副本在 lamb…","c":{"lang":"cpp","code":"#include <functional>\n#include <iostream>\n#include <vector>\n\nint main() {\n    int total = 0;\n    std::vector<int> v{1, 2, 3};\n\n    auto by_ref  = [&total](int x) { total += x; };\n…"}}]},{"id":"cpp-ch02/04-func-practical-recipes","file":"04-func-practical-recipes.md","title":"§4 cpp-ch02 实战手记：凯喵带你把函数与 lambda 用「翻车」","kind":"flow","secs":[{"h":"现场一：f(NULL) 选中 f(int)，空指针歧义","s":"凯喵重载了 f(int) 和 f(char)，调用 f(NULL) 却进了 f(int)。NULL 是整数常量 0，不是指针类型。C++11 起一律用 nullptr，它是独立的 std::nullptr_t，只会匹配指针重载。","c":{"lang":"cpp","code":"void f(int); void f(char*);\nf(NULL);       // ❌ 调用 f(int)，不是你想要的空指针\nf(nullptr);    // ✅ 明确匹配 f(char*)"}},{"h":"现场二：[=] 在成员函数里捕获的是 this，不是对象副本","s":"凯喵在成员函数里写 [=]{ use(member); } 以为按值捕获了整个对象，结果对象销毁后 lambda 调用崩溃。[=] 捕获成员时捕获的是 this 指针，不是对象副本；对象没了 this 悬垂。C++20 要求显式写 [=…","c":{"lang":"cpp","code":"struct Widget {\n    int n = 0;\n    auto bad() { return [=]{ return n; }; }      // ❌ 捕获 this，悬垂风险\n    auto good() { int v = n; return [v]{ return v; }; }  // ✅ 按值拷出\n};"}},{"h":"现场三：循环里按引用捕获循环变量，闭包全看到退出值","s":"凯喵 for (int i...) fns.push_back([&i]{ return i; })，所有闭包共享同一个 i，最后全返回循环退出值。要每个闭包一份，按值捕获 [i]。","c":{"lang":"cpp","code":"std::vector<std::function<int()>> fns;\nfor (int i = 0; i < 3; ++i)\n    fns.push_back([i]{ return i; });   // ✅ 按值，每个一份\n// fns.push_back([&i]{ return i; });   // ❌ 共享，全返回 3"}},{"h":"现场四：mutable 改的是闭包内副本，外部变量纹丝不动","s":"凯喵写 = mutable { ++x; } 想改外部 x，结果外部没变。mutable 只是允许修改闭包捕获的副本，外部原变量不受影响。要改外部必须引用捕获 [&x]。","c":{"lang":"cpp","code":"int x = 0;\nauto f = [=]() mutable { ++x; };   // 改的是副本\nf(); /* x 仍是 0 */\nauto g = [&x]() { ++x; };          // ✅ 引用捕获，改外部\ng(); /* x 变 1 */"}},{"h":"现场五：头文件里定义非 inline 函数，multiple definition","s":"凯喵在 util.h 里写了普通函数 int add(int a,int b){...}，被两个 .cpp 包含，链接报 multiple definition。头文件只放声明；要放定义就用 inline（或模板，模板隐式 inline…","c":{"lang":"cpp","code":"// util.h\ninline int add(int a, int b) { return a + b; }   // ✅ inline 允许多翻译单元\n// int add(int a,int b){return a+b;}              // ❌ 重复定义"}},{"h":"现场六：默认参数只能写在声明一处，调用处再写就重定义","s":"凯喵在函数声明和定义里都写了默认参数，链接报重定义。默认参数只应出现在声明（通常是头文件），定义里不能重复。调用方可选填，但默认值以声明为准。","c":{"lang":"cpp","code":"// header\nint pow(int base, int exp = 2);     // ✅ 默认参数在声明\n// impl\nint pow(int base, int exp) {        // ❌ 不要再写 =2\n    int r = 1; for (; exp; --exp) r *= base; return r;\n}"}},{"h":"现场七：重载决议被隐式转换带偏，调到意外版本","s":"凯喵重载 f(short) 和 f(double)，传 int 却进了 f(double)——因为 int→short 是窄化（需用户转换）、int→double 是拓宽（标准转换），编译器选更优的 double。小心「字面量 + 重载…","c":{"lang":"cpp","code":"void f(short); void f(double);\nf(42);        // ❌ 42 是 int，窄化到 short 不如拓宽到 double，选 f(double)\nf((short)42); // ✅ 显式指定"}},{"h":"现场八：返回局部变量的引用/指针，悬垂","s":"凯喵 const int& r = max(a, b); 若 max 返回局部引用，调用完对象就销毁，r 悬垂。函数返回引用/指针时，必须保证所指对象生命周期长于调用者（全局、静态、传入的引用、或 static）。","c":{"lang":"cpp","code":"// ❌ 返回局部引用\n// int& bad() { int x; return x; }\n// ✅ 返回传入引用之一\nint& pick(int& a, int& b) { return a > b ? a : b; }"}},{"h":"现场九：递归没基准情形，栈溢出","s":"凯喵写阶乘忘了 n==0 返回 1，调用炸成 stack overflow。任何递归必须有收敛到基准的路径，否则无限自调用吃光栈。尾递归在 C++ 通常不保证优化，别依赖。","c":{"lang":"cpp","code":"int fact(int n) {\n    if (n <= 1) return 1;     // ✅ 基准情形\n    return n * fact(n - 1);\n}"}},{"h":"现场十：函数指针类型不匹配，赋值编译不过","s":"凯喵 void(fp)(int) = &print; 想接一个 void print(double) 的函数，编译失败。函数指针类型要完全匹配参数与返回；想统一回调可用 std::function + lambda 适配。","c":{"lang":"cpp","code":"void print(int);\nvoid (*fp)(int) = print;                 // ✅ 类型匹配\n// fp = [](double d){};                  // ❌ 类型不对\nstd::function<void(int)> f = [](double d){};  // ✅ function 可适配"}},{"h":"现场十一：lambda 作为模板参数没指明返回类型，auto 推导歧义","s":"凯喵写 [](auto a, auto b){ return a > b ? a : b; } 在三元表达式两分支类型不同时（如 int vs double），返回类型推导冲突。显式写返回类型 -> double 或用 std::com…","c":{"lang":"cpp","code":"auto m = [](auto a, auto b) -> double { return a > b ? a : b; };  // ✅ 显式返回"}},{"h":"现场十二：默认参数表达式在每次调用都重算，带副作用要小心","s":"凯喵 void f(int x = g()) 以为 g() 只在编译期算一次，结果每次调用都重新执行 g()。默认参数是运行时在调用点求值的，带副作用或昂贵计算会被反复触发。","c":{"lang":"cpp","code":"int counter = 0;\nint g() { return ++counter; }\nvoid f(int x = g()) {}    // ❌ 每次调用 f() 都 ++counter"}},{"h":"现场之外：凯喵的三条铁律","s":"写函数最容易犯的错不是语法，而是「生命周期」和「类型匹配」想当然。凯喵给自己定下三条：第一，任何返回引用或指针的函数，先问一句「所指对象到底能活多久」；第二，重载与默认参数宁显式不省略，别让编译器替你做主；第三，lambda 捕获列表把…","c":null},{"h":"🧑‍💻 程序员视角","s":"f(NULL) 选中 f(int) 而不是 f(char)，因为 NULL 在多数实现里就是 0，整型字面量的匹配优先级更高——要传空指针必须写 nullptr。lambda 的两个高频坑：在成员函数里写 [=] 捕获的是 this 指…","c":null},{"h":"🎓 博士生视角","s":"lambda 的本质是编译器生成的函数对象：捕获列表决定它的数据成员，operator() 默认是 const，因此要修改捕获的副本必须加 mutable。[=] 在成员函数中捕获 this 是标准的规定（C++20 起可用 [=, t…","c":null},{"h":"📚 考研者视角","s":"面试常考：","c":null}]}],"exams":[{"kind":"choice","q":"关于函数重载，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"仅返回类型不同的两个同名函数可以重载"},{"k":"B","t":"重载决议优先精确匹配，其次类型提升，再标准转换"},{"k":"C","t":"默认参数可不连续地从任意位置开始"},{"k":"D","t":"函数声明可以写多次，定义也可以写多次"}],"ans":"B","why":"重载看参数列表不看返回类型；默认参数须从右连续；定义只能一处。"},{"kind":"fix_error","q":"修复默认参数重定义","stem":"以下代码报“默认参数重定义”，请修复（只保留一处默认参数）： cpp void greet(const std::string& name, const std::string& suffix = \"!\"); void greet(const std::string& name, const std::string& suffix = \"!\") { / ... / }","opts":[],"ans":"void greet(const std::string& name, const std::string& suffix = \"!\"); void greet(const std::string& name, const std::string& suffix) { / ... / }}","why":"默认参数只在声明处给一次，定义处省略。"},{"kind":"output","q":"读代码写输出","stem":"cpp #include <iostream> void f(int& a, int b) { a += 5; b += 5; } int main() { int x = 1, y = 2; f(x, y); std::cout << x << \" \" << y; }","opts":[],"ans":"6 2","why":"a 是引用，修改影响 x；b 是值传递，不影响 y。"},{"kind":"coding","q":"实现字符串反转函数","stem":"实现 std::string reverse_str(const std::string& s)，返回反转后的字符串。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行字符串 s（可能含空格，不含换行）。 输出：反转后的字符串，占一行。","opts":[],"ans":"#include <algorithm> #include <iostream> #include <string> std::string reverse_str(const std::string& s) { std::string r(s); std::reverse(r.begin(), r.end()); r…","why":"从尾到头拼回即可；const 引用避免拷贝。"},{"kind":"coding","q":"LeetCode 20 · 有效的括号","stem":"给定一个只含 '()[]{}' 的字符串，判断括号是否匹配。用栈实现，封装成函数 bool isValid(const std::string& s)。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行只含 ()[]{} 的字符串（可能为空行）。 输出：true 或 false。","opts":[],"ans":"#include <iostream> #include <stack> #include <string> bool isValid(const std::string& s) { std::stack<char> st; for (char c : s) { if (c == '(' || c == '[' ||…","why":"经典栈题，函数式封装便于复用。"}],"works":[{"h":"默认参数重复提供","d":"声明处写了 = \"!\"，定义处又写一遍，触发\"默认参数重定义\"。只在一处给，且应放在头文件的声明里。"},{"h":"返回局部变量引用/指针","d":"int& f(){ int x; return x; } 返回栈上对象，调用方拿到悬垂引用（未定义行为）。"},{"h":"重载仅靠返回类型区分","d":"int f(); 与 double f(); 非法，重载看参数列表不看返回类型。"},{"h":"lambda 引用捕获悬空","d":"把 [&x] 捕获局部的 lambda 存起来延迟调用，x 已析构，访问即 UB。需延长生命周期或改值捕获。"},{"h":"默认参数从中间断档","d":"void f(int a=1, int b) 非法，默认参数必须连续靠右。"},{"h":"虚函数带默认参数","d":"函数体动态绑定、默认值静态绑定：通过基类引用调用会执行派生类实现，但拿到基类的默认值。虚函数不要用默认参数。"},{"h":"派生类同名函数隐藏基类重载","d":"派生类写了一个同名函数，基类的所有同名重载都被隐藏（不是重载决议的问题，是名字查找阶段就停了）。要 using Base::f; 拉回来。"},{"h":"f(NULL) 选中 f(int)","d":"NULL 是整数常量 0，同时存在 f(int) 与 f(char) 时选前者。用 nullptr 表达空指针。"}],"asks":[{"q":"函数重载在 C++ 里是怎么实现的？为什么 C 不支持？","a":"C++ 编译器在编译期对重载函数做名字改编（name mangling），把函数名、参数类型/个数编码进符号名，链接时据此区分。C 语言不做 name mangling，同名函数符号冲突，所以不支持重载。可用 extern \"C\" 强制按 C 方式改编，常用于兼容 C 接口/导出 C 符号。","fu":["extern \"C\" 有什么用？","mangling 后的名字可读吗，怎么查看？"],"tag":"通用/字节"},{"q":"指针传参和引用传参有什么区别？什么时候用哪个？","a":"1) 引用必须初始化且不可改绑，指针可以；2) 引用无空值语义，指针有 nullptr；3) 使用上：只读/原地修改优先 const 引用（无拷贝、语法简洁）；需要可空、可重指向、或做可选输出参数时用指针。C 语言没有引用，只能指针。","fu":["顶层 const 在传参时有意义吗？","什么时候必须用指针而不能用引用？"],"tag":"通用"},{"q":"默认参数有哪些规则？以下为什么错：void f(int a=1, int b)？","a":"默认参数必须从参数列表最右端连续给定。void f(int a=1, int b) 中 a 有默认值但右侧 b 没有，调用 f(5) 会歧义（5 给 a 还是 b），因此非法。正确写法：void f(int a, int b=1) 或都给默认值且连续靠右。另外默认参数只在一处声明。","fu":["默认参数在声明和定义两处都写会怎样？","虚函数能用默认参数吗（为什么通常不推荐）？"],"tag":"通用/腾讯"}]},{"id":"cpp-ch03","subj":"cpp","title":"数组与字符串：C 数组、std::string 与字符串视图","summary":"C 风格数组与指针退化；std::string 常用接口；std::string_view 零拷贝视图；字符数组与 C 字符串；常见字符串算法（反转/分割/匹配）。","concepts":[{"id":"cpp-ch03/01-c-array-vs-pointer","file":"01-c-array-vs-pointer.md","title":"C 风格数组与指针","kind":"flow","secs":[{"h":"一、数组的真实类型","s":"int a[5]; 的类型是 int[5]——长度是类型的一部分。这一点在三个地方能看出来：","c":{"lang":"cpp","code":"int a[5];\nsizeof(a) == 20;              // 5 * sizeof(int)，长度参与计算\n&a;                           // 类型是 int(*)[5]，指向整个数组\nsizeof(&a) == sizeof(void*);  // 8，但指向的是「5 个 int」这个整体"}},{"h":"二、退化发生在哪里","s":"退化不是\"数组就是指针\"，而是在特定语境下的一次隐式转换。退化发生：","c":null},{"h":"三、函数传参：长度信息的丢失与重建","s":"int a[5] 在形参位置会被编译器直接改写成 int a，5 被忽略，且不产生任何告警。这就是\"形参写成数组很安全\"这个直觉错在哪。","c":{"lang":"cpp","code":"void print(int a[5]);   // 骗人的写法：等价于 void print(int* a)\nvoid print(int* a, std::size_t n);   // 正确：长度一起传"}},{"h":"四、字符串字面量与 const char[]","s":"字符串字面量 \"abc\" 的类型是 const char[4]（含结尾 \\0），存放在只读数据段。C++11 起禁止隐式转成 char——因为写它属于 UB（历史上很多崩溃就是这么来的）。","c":{"lang":"cpp","code":"const char* s = \"abc\";     // OK，只读\nchar* bad = \"abc\";         // C++11 起编译错误\nchar arr[] = \"abc\";        // OK，拷贝到栈上，可修改"}},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：让 sizeof 自己说话","s":"两处对比最值钱：by_array_param 里 sizeof 退化，而 by_ref_param 通过模板把 N 拿到手；&a + 1 跨越 20 字节而不是 4 字节，证明 &a 的类型是 int()[5]。","c":{"lang":"cpp","code":"#include <cstddef>\n#include <iostream>\n\nvoid by_array_param(int a[5]) {           // 形参被改写成 int*\n    std::cout << \"in_func=\" << sizeof(a) << \"\\n\";\n}\n\ntemplate <std::size_t N>\nvoid by_ref_param(int (&a)[N]) {          // 引用绑定，保留完整类型\n…"}}]},{"id":"cpp-ch03/02-std-string","file":"02-std-string.md","title":"std::string 常用接口","kind":"flow","secs":[{"h":"一、容量、长度与 SSO","s":"string 有三个与\"大小\"相关的量：","c":{"lang":"text","code":"string 的接口分层\n\n  观察类   size / length / empty / capacity / max_size\n  访问类   operator[]（无检查） / at（抛异常） / front / back / data / c_str\n  修改类   append / push_back / insert / erase / replace / clear / resize\n  查找类   find / rfind / find_first_of / find_last_of （未找到 → npos）\n  视图类   substr（拷贝） / compare（不拷贝）"}},{"h":"二、查找：npos 不是 -1","s":"find 系列返回 size_type（无符号），未找到时返回 std::string::npos，其值是 size_type 的最大值——不是 -1，尽管在很多实现里它的位模式与 -1 相同。","c":{"lang":"cpp","code":"if (s.find(\"x\") == std::string::npos) { /* 未找到 */ }   // 正确\nif (s.find(\"x\") < 0) { /* 永远为假 */ }                  // 错误且无告警"}},{"h":"三、修改：什么时候会重新分配","s":"不 reserve 也不会是 O(n²)——因为扩容是成倍的，均摊 O(n)。真正 O(n²) 的是 s = s + x：每次构造一个临时对象再赋值，多一次完整拷贝。","c":{"lang":"cpp","code":"std::string s;\ns.reserve(1000);                  // 一次分配\nfor (int i = 0; i < 1000; ++i) s += std::to_string(i);   // 均摊 O(n)"}},{"h":"四、与 C 接口互转","s":"接收外部数据时优先用\"指针 + 长度\"构造，而不是假定 \\0 结尾——网络包、文件块里常常没有 \\0 终止符。","c":null},{"h":"五、比较与排序","s":"string 的 operator< 按逐字节字典序比较，std::string 因此可直接放进 std::set/std::map/std::sort。","c":null},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：验证 npos、SSO 与拷贝代价","s":"最后三行演示了一个容易忽略的点：没有 \\0 的字节块用 (ptr, n) 构造是安全的，用 std::string(raw) 则会越界读。","c":{"lang":"cpp","code":"#include <iostream>\n#include <string>\n\nint main() {\n    std::string s = \"hello world\";\n    std::cout << \"find=\" << s.find(\"world\") << \" npos=\" << (s.find(\"xyz\") == std::string::npos) << \"\\n\";\n    std::cout << \"substr=\" << s.substr(6, 5) << \" len=\" << s.substr(6, 5).size() << \"\\n\";\n\n    std::string short_s = \"abc\";\n…"}}]},{"id":"cpp-ch03/03-string-view","file":"03-string-view.md","title":"std::string_view 零拷贝视图","kind":"timeline","secs":[{"h":"一、它到底是什么：两个字段","s":"代价是：string_view 不知道底层数据什么时候死，因为它只有一个裸指针。","c":{"lang":"cpp","code":"struct string_view {          // 概念示意，实际实现略有差异\n    const char* data_;\n    std::size_t size_;\n};"}},{"h":"二、生命周期：唯一的、也是致命的风险","s":"这两种写法都编译通过、无告警（部分编译器对第一种给 -Wreturn-stack-address 之外的提示，但不可依赖）。原因是 string_view 有从 const char 与 std::string 的隐式转换构造，编译器无…","c":{"lang":"cpp","code":"std::string_view bad() {\n    return std::string(\"tmp\");     // 编译通过，运行时悬垂\n}\nstd::string_view v = std::string(\"tmp\") + \"!\";\n// 这一行结束时临时 string 销毁，v 立即悬垂"}},{"h":"三、它不保证什么","s":"三个常见误解：","c":null},{"h":"四、什么时候该用它","s":"","c":null},{"h":"五、与其它\"视图类型\"的共同模式","s":"C++17 之后标准库引入了成组的视图类型：string_view、span<T>（C++20）、function_ref（提案中）。它们的共同点：","c":null},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：零拷贝分词器","s":"注意 split 返回的 vector<string_view> 只在 owner 存活期间有效。这正是\"不拥有\"的契约：函数的返回值没有延长任何生命周期，调用方必须自己保证 owner 活得更久。","c":{"lang":"cpp","code":"#include <iostream>\n#include <string>\n#include <string_view>\n#include <vector>\n\nstd::vector<std::string_view> split(std::string_view sv, char sep) {\n    std::vector<std::string_view> out;\n    std::size_t start = 0;\n    while (start <= sv.size()) {\n…"}}]},{"id":"cpp-ch03/04-pointer-string-practical-recipes","file":"04-pointer-string-practical-recipes.md","title":"凯喵实战手记 · 数组、指针与字符串的那些「当场爆炸」","kind":"flow","secs":[{"h":"现场 1：数组退化成指针，sizeof 当场翻车","s":"凯喵刚接手一段老代码，想算数组长度：","c":{"lang":"cpp","code":"void foo(int a[]) {\n    std::cout << sizeof(a); // 输出 8（指针大小），不是数组总字节\n}\nint main() {\n    int b[10];\n    foo(b);\n}"}},{"h":"现场 2：char[] 与 char 的本质区别","s":"凯喵写了 char s = \"hello\"; s[0] = 'H';，程序直接段错误。原因：字符串字面量存在只读段 .rodata，char 指向它，写入是 UB。正确做法：要改就拷到栈上 char s[] = \"hello\";（数组初…","c":null},{"h":"现场 3：字符串拼接用 + 在循环里 O(n²)","s":"每次 + 都产生新字符串，整体复杂度 O(n²)，大文本能慢到离谱。凯喵的修法：先 reserve 预估容量，循环里用 s += w；或对字符串列表直接用 std::accumulate/join（C++23 std::ranges::…","c":{"lang":"cpp","code":"std::string s;\nfor (auto& w : words) s = s + w; // 每次都分配新内存并拷贝"}},{"h":"现场 4：std::string 的 SSO 与扩容","s":"短字符串（通常 ≤15 字节）存在对象内部的「小字符串优化」缓冲区，不堆分配；超长才去堆上。凯喵提醒：频繁 += 小规模字符串时，提前 reserve 能避免多次 realloc 拷贝。但别盲目 reserve 超大值，那是浪费。","c":null},{"h":"现场 5：string_view 悬垂的经典场景","s":"string_view 不拥有数据，只是指针+长度。凡是来源是临时 string、函数返回局部 string、或被后续的 erase/clear 改动，view 都会悬垂。凯喵的规矩：view 的寿命必须严格短于它指向的对象。","c":{"lang":"cpp","code":"std::string_view sv = std::string(\"temp\"); // 临时对象销毁，sv 悬垂！\nsv[0]; // UB"}},{"h":"现场 6：substr 的零拷贝替代","s":"取后缀时 s = s.substr(1) 每次复制剩余全部字符。凯喵改用 std::string_view(s).substr(1) 做零拷贝切片，只在最终需要持久化时才 .str() 转回 string。注意切出来的 view 仍受原…","c":null},{"h":"现场 7：C 风格字符串结尾 \\0 的坑","s":"char buf[3] = \"abc\"; 其实越界了——字面量有 4 字符含 \\0，但 buf 只有 3。凯喵的修法：让编译器定大小 char buf[] = \"abc\";（自动 4）。函数接收 C 串时务必确认调用方传的是以 \\0 结…","c":null},{"h":"现场 8：c_str() 返回的指针有效期","s":"c_str() 返回的指针在下次「非 const 修改」或析构前有效。凯喵的规矩：要长期持有就 strdup/拷贝，别存裸指针。","c":{"lang":"cpp","code":"const char* p = s.c_str();\ns += \"x\";      // 可能 realloc，p 失效\nstd::cout << p; // UB"}},{"h":"现场 9：混用 string 与 string_view 重载歧义","s":"同时提供 f(std::string) 和 f(std::string_view)，传字面量 \"x\" 时两者都可匹配，编译报歧义。凯喵只保留 f(std::string_view) 版本（它既能接 string 也能接字面量），消除二义…","c":null},{"h":"现场 10：reserve 避免反复扩容","s":"构造大字符串前 s.reserve(total) 一次性预留，循环里 += 不再触发 realloc。凯喵在解析日志、拼 SQL 时必做这步，性能能差一个数量级。","c":null},{"h":"现场 11：字符串比较别退化成裸指针","s":"if (s == \"abc\") 是 OK 的（string 重载了 ==）。但 if (strcmp(s.c_str(), \"abc\") == 0) 容易写成 = 误赋值，且要记得包含 <cstring>。凯喵优先用 string 的原…","c":null},{"h":"现场 12：宽字符与 UTF-8 的混乱","s":"std::wstring 在 Windows 是 UTF-16、在 Linux 是 UTF-32，跨平台不一致。现代项目凯喵统一用 std::string 存 UTF-8，需要按「字符（而非字节）」遍历时用第三方库或手动解码，别直接当下…","c":null},{"h":"现场 13：只读字符串字面量写入 UB","s":"const char s = \"abc\"; const_cast<char>(s)[0] = 'x'; 即使强转去掉 const 也照样段错误，因为底层在只读段。凯喵铁律：字面量只读，要改先拷贝到可写缓冲区。","c":null},{"h":"现场 14：字符串查找返回 npos 的判等","s":"find 返回 size_t，找不到时返回 npos（最大无符号值）。凯喵提醒：别拿 find(...) == -1 去判等（-1 转成无符号会变成巨大正数），必须和 npos 比。","c":{"lang":"cpp","code":"if (s.find(\"k\") == std::string::npos) { /* 没找到 */ }"}},{"h":"凯喵复盘：把字符串当成「有主之物」","s":"这 14 个现场背后其实是一条主线：字符串不是抽象的值，而是有所有者、有生命周期、有内存布局的具体对象。C 风格 char 指向只读段或某块缓冲区，std::string 拥有堆（或 SSO 内部）内存，string_view 则完全不…","c":null},{"h":"凯喵速记：面试与实战最爱考的串","s":"如果时间只够记三句：第一，数组作参数会退化成指针，长度信息用 span 或显式传；第二，string_view 是别人的内存上的窗，寿命必须短于源，别跨函数返回；第三，字符串拼接和切片在循环里是 O(n²) 重灾区，先 reserve…","c":null},{"h":"🧑‍💻 程序员视角","s":"把数组传进函数后 sizeof(arr) 变成 8，因为数组已退化成指针——sizeof 拿到的是指针大小而非数组长度。char[] 是「可修改的字符数组」，char 指向字面量时不可写，写 char s = \"abc\"; s[0] =…","c":null},{"h":"🎓 博士生视角","s":"数组退化是 C 语言遗留的「类型系统漏洞」：数组类型在大多数表达式里被转换为指向首元素的指针，只有 sizeof、&、字符串字面量初始化三种场景保留数组类型。C++ 用 std::array 与 std::span 补上这一层：前者把长…","c":null},{"h":"📚 考研者视角","s":"笔试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于数组与指针，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"数组作为函数参数时仍保留完整长度信息"},{"k":"B","t":"a[i] 等价于 (a + i)"},{"k":"C","t":"string_view 拥有底层字符存储"},{"k":"D","t":"std::string 的 c_str() 不保证以 \\0 结尾"}],"ans":"B","why":"数组传参退化为指针丢失长度；string_view 不拥有存储；c_str() 以 \\0 结尾。"},{"kind":"fix_error","q":"修复越界访问","stem":"以下循环越界（i <= n 多访问一位），请修复： cpp void f(const std::string& s) { for (size_t i = 0; i <= s.size(); ++i) std::cout << s[i]; }","opts":[],"ans":"void f(const std::string& s) { for (size_t i = 0; i < s.size(); ++i) std::cout << s[i]; }","why":"有效下标是 0..size()-1，用 < 而非 <=。"},{"kind":"output","q":"读代码写输出","stem":"cpp #include <iostream> #include <string> int main() { std::string s = \"hello\"; std::cout << s.find(\"llo\") << ' ' << s.substr(1, 3); }","opts":[],"ans":"2 ell","why":"find 返回首位置 2；substr(1,3) 取 \"ell\"。"},{"kind":"coding","q":"LeetCode 344 · 反转字符串","stem":"给定字符数组/字符串 s，原地反转。实现 void reverseString(std::string& s)。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行字符串 s。 输出：原地反转后的字符串，占一行。","opts":[],"ans":"#include <algorithm> #include <iostream> #include <string> void reverseString(std::string& s) { std::reverse(s.begin(), s.end()); } int main() { std::string s;…","why":"双指针或 std::reverse 均可。"},{"kind":"coding","q":"LeetCode 415 · 字符串相加","stem":"给定两个非负整数字符串 num1、num2，返回其和的字符串（模拟竖式加法，不转整数）。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：两行，分别为非负整数字符串 num1、num2。 输出：两者之和的字符串表示。","opts":[],"ans":"#include <algorithm> #include <iostream> #include <string> std::string addStrings(std::string a, std::string b) { std::string r; int i = (int)a.size() - 1, j =…","why":"从末位逐位相加，注意进位与结果反转。"}],"works":[{"h":"数组传参退化为指针","d":"void f(int a[5]) 内 sizeof(a) 是指针大小（如 8），拿不到数组长度；必须显式传 size 或用 std::array/std::vector。"},{"h":"C 字符串忘了 \\0","d":"字符数组未以 \\0 结尾就当字符串用，strlen/cout 会越界读到垃圾或崩溃。务必留 \\0 位置或用 std::string。"},{"h":"string_view 悬空","d":"std::string_view v(getTempString()); 临时 string 析构后 v 指向已释放内存，访问 UB。确保底层字符串生命周期更长。"},{"h":"下标越界无检查","d":"s[i] / a[i] 越界是未定义行为（不抛异常），用 at() 或在访问前判长度。"},{"h":"&a 与 &a[0] 步长不同","d":"两者地址值相同但类型不同：&a + 1 跳过整个数组（int()[5] 走 20 字节），&a[0] + 1 只跳一个元素。指针算术前先确认类型。"},{"h":"string_view 当 C 字符串用","d":"它不保证 \\0 结尾，v.substr(2) 可能指向大串中间。传给 C API 前先 std::string{v} 拷一份。"},{"h":"find 结果与 npos 比较写成 < 0","d":"size_type 是无符号，< 0 永远为假且无告警。写 == std::string::npos。"},{"h":"npos 参与算术","d":"pos = s.find(x) + 1 在未找到时回绕成 0，导致从头部重新查找 → 死循环。先判 npos 再加。"}],"asks":[{"q":"C 数组和指针是什么关系？数组名是常量指针吗？","a":"数组是一段连续内存；数组名在表达式中（除 sizeof、&、decltype 外）会退化成指向首元素的指针，但它不是指针变量，不能被重新赋值（不是常量指针，而是不可修改的地址表达式）。int a[5]; int p=a; 合法但 a=p; 非法。作为参数 f(int a[]) 即 f(int)，长度信息丢失。","fu":["为什么 sizeof(a) 在函数内是指针大小？","std::array 和裸数组有什么区别？"],"tag":"通用/美团"},{"q":"std::string 是怎么管理内存的？有 COW 吗？","a":"现代主流实现（libstdc++/libc++）采用 SSO（短字符串优化）：短字符串直接存在栈上对象内，不堆分配；长字符串才堆分配，遵循写时复制式的小字符串优化（不是传统 COW，C++11 起标准禁止 COW 因为迭代器/线程安全问题）。理解 SSO 有助于解释为何短字符串拷贝很快。","fu":["SSO 的容量大概多少？","string 的迭代器失效规则？"],"tag":"通用/腾讯"},{"q":"std::string_view 适合什么场景？有什么坑？","a":"适合只读、短暂的字符串观察：函数参数（避免拷贝）、解析/切片。坑：①不拥有底层存储，指向临时 string 会悬空；②不能保证以 \\0 结尾，不能直接传给只认 C 字符串的 API（需先转 string 或确保有 \\0）；③不可修改。只读且生命周期可控时优先它。","fu":["string_view 能做函数返回值吗？","substr 在 string_view 上代价多大？"],"tag":"通用/字节"}]},{"id":"cpp-ch04","subj":"cpp","title":"指针与内存管理：指针运算、new/delete 与悬垂","summary":"指针本质与运算；数组与指针关系；动态内存 new/delete；内存布局（栈/堆/全局）；悬垂指针与内存泄漏；const 指针；this 指针初步。","concepts":[{"id":"cpp-ch04/01-pointer-basics","file":"01-pointer-basics.md","title":"指针基础","kind":"flow","secs":[{"h":"一、指针的四个要素","s":"一个指针值包含的信息只有\"地址\"，但使用它时需要同时知道四件事：","c":{"lang":"text","code":"指针的语义分层\n\n  T* p\n   ├─ 地址         可比较、可打印（%p）\n   ├─ 类型         *p 的类型是 T；p+1 前进 sizeof(T)\n   ├─ 有效性       ✗ 不检查（悬垂、野指针都是 UB）\n   └─ 所有权       ✗ 不表达（由命名/接口约定承载）"}},{"h":"二、空指针与 nullptr","s":"nullptr 的类型是 std::nullptr_t，能隐式转为任意指针类型，但不是整数。这解决了两个老问题：","c":{"lang":"cpp","code":"int* p = nullptr;      // 推荐：类型是 std::nullptr_t\nint* q = NULL;         // 可行但不推荐：NULL 通常是 0\nint* r = 0;            // 可行但不推荐"}},{"h":"三、指针算术：按类型缩放","s":"p + 1 前进的不是 1 字节，而是 sizeof(p) 字节。这是数组下标能工作的基础：a[i] == (a + i)。","c":{"lang":"cpp","code":"int a[3] = {10, 20, 30};\nint* p = a;\n// p+1 的地址比 p 大 4（sizeof(int)），不是 1"}},{"h":"四、const 与指针的四种组合","s":"读法是从右往左：const 修饰它左边最近的东西， 分隔\"指针本身\"与\"所指对象\"。","c":{"lang":"cpp","code":"int x = 1;\nconst int* p1 = &x;         // 指向 const int：*p1 不可改，p1 可改指向\nint* const p2 = &x;         // const 指针：p2 不可改指向，*p2 可改\nconst int* const p3 = &x;   // 都不可改\nint const* p4 = &x;         // 与 p1 等价（const int 与 int const 同义）"}},{"h":"五、函数指针与回调","s":"函数指针的语法难读，现代做法是 using Callback = int()(int,int); 或直接用 std::function/模板。函数指针的价值在于零开销（无类型擦除），C API 回调只能用它。","c":{"lang":"cpp","code":"int add(int a, int b) { return a + b; }\nint (*fp)(int, int) = &add;      // & 可省略\nint r = fp(1, 2);                // 解引用也可省略"}},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：地址、步长与 const 位置","s":"byte_diff=8 而 diff=2 是关键对照：指针相减按元素计，转成 char 后才是字节差。这直接对应 408 的地址计算题。","c":{"lang":"cpp","code":"#include <cstddef>\n#include <iostream>\n\nint main() {\n    int a[3] = {10, 20, 30};\n    int* p = a;\n    int* q = a + 2;\n\n    std::cout << \"*p=\" << *p << \" *(p+1)=\" << *(p + 1) << \" *(p+2)=\" << *(p + 2) << \"\\n\";\n…"}}]},{"id":"cpp-ch04/02-dynamic-memory","file":"02-dynamic-memory.md","title":"动态内存：new / delete","kind":"stack","secs":[{"h":"一、new 是两件事，delete 也是","s":"这一行做了两步：","c":{"lang":"cpp","code":"int* p = new int(7);"}},{"h":"二、new[] / delete[] 与数组 cookie","s":"为什么必须配对？因为 delete[] 需要知道要调多少次析构。对于有析构函数的类型，new T[n] 通常在返回指针的前面多分配几个字节存元素个数（数组 cookie），delete[] 读到它才能正确地析构 n 次。用 delete…","c":{"lang":"cpp","code":"int* a = new int[3];\ndelete[] a;      // 正确\ndelete a;        // UB：漏了 []"}},{"h":"三、异常安全：为什么裸 new 一定会漏","s":"C++ 没有 finally，所以\"手动配对\"在异常路径上必然失效。这不是程序员粗心，而是语言没有提供自动清理机制（除了析构函数）。RAII 正是为此而生：","c":{"lang":"cpp","code":"void f() {\n    Resource* r = new Resource();\n    may_throw();          // 若此处抛异常…\n    delete r;             // …这一行永远不执行 → 泄漏\n}"}},{"h":"四、operator new 可以重载：内存池的入口","s":"operator new / operator delete 是可替换的（全局或类级）。这让内存池、调试分配器、对齐分配成为可能：","c":{"lang":"cpp","code":"void* operator new(std::size_t n);          // 全局替换\nstruct Pooled { static void* operator new(std::size_t n); };  // 类级"}},{"h":"五、什么情况下仍然可以用 new","s":"除此之外，应用层代码应该一次 new 都不写——make_unique / make_shared / 容器足够覆盖所有场景。","c":null},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：观察构造/析构与 cookie 的痕迹","s":"比较 delete one 与 delete[] arr 的输出行数，就能看出\"数组析构必须知道元素个数\"这件事。make_unique 那段演示 RAII：作用域结束时 dtor 99 自动出现，全程没有手写 delete。","c":{"lang":"cpp","code":"#include <cstddef>\n#include <iostream>\n#include <memory>\n\nstruct Tracked {\n    int v;\n    explicit Tracked(int x) : v(x) { std::cout << \"ctor \" << v << \"\\n\"; }\n    ~Tracked() { std::cout << \"dtor \" << v << \"\\n\"; }\n};\n…"}}]},{"id":"cpp-ch04/03-memory-layout","file":"03-memory-layout.md","title":"程序内存布局与对象生命周期","kind":"stack","secs":[{"h":"一、进程地址空间：六个区","s":"三个值得注意的点：","c":{"lang":"text","code":"典型 64 位 Linux 进程布局（低地址 → 高地址）\n\n  ┌──────────────┐ 低地址\n  │ .text        │ 机器码（只读、可执行）\n  ├──────────────┤\n  │ .rodata      │ 字符串字面量、const 全局（只读）  ← \"abc\" 在这里\n  ├──────────────┤\n  │ .data        │ 已初始化的全局/静态变量（可写）\n  ├──────────────┤\n…"}},{"h":"二、存储期：四种，与作用域正交","s":"最容易搞错的是 static 局部变量：作用域是局部的（函数外看不见），存储期是静态的（只初始化一次，程序结束才销毁）。","c":{"lang":"cpp","code":"int& counter() {\n    static int n = 0;      // 只初始化一次；下次进入函数时值保留\n    return ++n;\n}"}},{"h":"三、静态初始化顺序问题（SIOF）","s":"跨翻译单元的全局对象，初始化顺序未定义；同一 TU 内按声明顺序。于是：","c":{"lang":"cpp","code":"// a.cpp\nLogger g_logger;                 // 可能比下面的 registry 晚初始化\n// b.cpp\nRegistry g_registry(g_logger);   // 若 g_logger 还没构造 → 读到未初始化对象"}},{"h":"四、对象的表示：填充字节与 memcmp","s":"对象的内部布局不只包含成员，还有填充字节（padding）：","c":{"lang":"text","code":"struct S { char c; int i; };   // 典型布局（4 字节对齐）\n\n  偏移 0   c        (1 字节)\n  偏移 1~3 填充      (3 字节，内容未指定)\n  偏移 4   i        (4 字节)\n  sizeof(S) == 8，而不是 5"}},{"h":"五、悬垂：最长的生命周期 bug","s":"对象销毁后，指向它的指针/引用不会自动失效——地址还在，内容可能还没被覆盖。于是：","c":{"lang":"cpp","code":"int* f() { int x = 1; return &x; }    // 返回栈地址，UB\nint& g() { int x = 1; return x; }     // 返回栈引用，UB"}},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：观察三个区的地址","s":"看输出就能把抽象的分区落到具体地址上：.bss 与 .data 相邻且都远离栈堆，堆与栈分居地址空间两端（具体数值随 ASLR 变化，但相对关系稳定）。counter() 连调两次得到 1、2，证明静态局部变量的值跨调用保留。","c":{"lang":"cpp","code":"#include <cstdlib>\n#include <iostream>\n\nint  g_init   = 1;        // .data\nint  g_zero;              // .bss\nconst char* g_str = \"lit\";// 指针在 .data，字面量在 .rodata\n\nint& counter() { static int n = 0; return ++n; }   // 静态存储期，局部作用域\n\n…"}}]},{"id":"cpp-ch04/04-pointer-practical-recipes","file":"04-pointer-practical-recipes.md","title":"凯喵实战手记：指针与内存——C++ 一半的 Bug 都长在这儿","kind":"flow","secs":[{"h":"1. 空指针解引用：最朴素的段错误","s":"凯喵第一次看到程序崩在 cout << p：","c":{"lang":"cpp","code":"int* p = nullptr;\n// ... 某些分支没赋值 ...\ncout << *p;   // SIGSEGV"}},{"h":"2. 悬垂指针：对象早死了，指针还活着","s":"凯喵返回局部变量的地址，调用方拿到野指针：","c":{"lang":"cpp","code":"int* danger() {\n    int x = 42;\n    return &x;   // x 在函数返回时已销毁，返回的是悬垂指针\n}"}},{"h":"3. 数组退化与 sizeof 陷阱","s":"凯喵把数组当参数传，算长度算错：","c":{"lang":"cpp","code":"void f(int a[10]) {\n    // sizeof(a) 是指针大小，不是 10*sizeof(int)！\n}\nint b[10];\nf(b);"}},{"h":"4. 指针算术越界：一步踏出数组","s":"凯喵用 p + i 遍历时 i 算错，踩到邻居内存：","c":{"lang":"cpp","code":"int a[5] = {};\nint* p = a;\nfor (int i = 0; i <= 5; ++i)  // i=5 越界\n    p[i] = i;"}},{"h":"5. new/delete 必须配平，且配对","s":"凯喵混用 new[] 和 delete，内存布局错乱：","c":{"lang":"cpp","code":"int* a = new int[10];\ndelete a;        // 错！应该用 delete[] a;"}},{"h":"6. 内存布局：栈、堆、全局、代码段各住哪","s":"凯喵调一个「偶发错乱」的 bug，最后发现是搞错了存储期：","c":{"lang":"cpp","code":"// .data：已初始化全局变量；.bss：未初始化全局；栈：局部；堆：new\nint g_init = 10;     // .data\nint g_uninit;        // .bss\nvoid f() { int x; }  // 栈，函数返回即失效"}},{"h":"7. 浅拷贝与深拷贝：指针成员被「共享」","s":"凯喵的 struct 默认拷贝，两个对象指向同一块堆：","c":{"lang":"cpp","code":"struct Buf { int* p = new int[10]; };\nBuf a; Buf b = a;   // 默认拷贝只复制指针值\n// 析构时 double free！"}},{"h":"8. 智能指针才是现代写法","s":"凯喵把手动 new/delete 全换成智能指针后，泄漏几乎消失：","c":{"lang":"cpp","code":"auto p = std::make_unique<int>(42);  // 离开作用域自动释放\nstd::shared_ptr<int> s = std::make_shared<int>(7);"}},{"h":"9. 跨编译单元的全局初始化顺序","s":"凯喵两个 .cpp 的全局对象互相依赖，结果读到未初始化值：","c":{"lang":"cpp","code":"// a.cpp\nextern int y; int x = y + 1;\n// b.cpp\nextern int x; int y = x + 1;   // 谁先构造？未定义"}},{"h":"10. memcmp 比较结构体不可靠","s":"凯喵用 memcmp 判两个结构体相等，偶尔错：","c":{"lang":"cpp","code":"struct S { int a; char b; /* 填充字节未指定 */ };\n// memcmp 会比较填充字节，内容不确定 → 相同逻辑值可能比较不等"}},{"h":"11. delete 后置空防不住所有副本","s":"凯喵以为 p = nullptr 就安全了：","c":{"lang":"cpp","code":"int* p = new int(1);\nint* q = p;        // 另一个副本\ndelete p; p = nullptr;\n// q 仍然是悬垂指针，use-after-free 仍在"}},{"h":"12. 强转去掉 const 写只读段是 UB","s":"凯喵改字符串字面量，直接段错误：","c":{"lang":"cpp","code":"const char* s = \"abc\";\n*(char*)s = 'x';   // UB：字面量在 .rodata 只读段，通常立即段错误"}},{"h":"凯喵复盘：指针问题的根，都在「所有权」","s":"这 12 个坑几乎都能归到一个词：所有权。悬垂指针是「对象死了指针还活着」；浅拷贝双重释放是「一个对象有两个没约定的主人」；delete 后置空防不住副本，是因为「所有权没真正移交」；跨编译单元初始化顺序、强转写只读段，则是把「生命周期…","c":null},{"h":"🧑‍💻 程序员视角","s":"空指针解引用是最朴素也最致命的段错误，if (p) 只能挡住空，挡不住「已释放」——悬垂指针是更难查的一类：对象析构后指针仍指向原地址，内存可能已被复用，读出来是脏数据、写进去是破坏别人的对象。指针算术越界同样隐蔽：p + n 只要不越…","c":null},{"h":"🎓 博士生视角","s":"C++ 的对象模型把「存储期」与「生命周期」分离：内存可以在对象析构后仍然可读（未定义行为但物理上可行），这正是悬垂指针难以复现的根源。指针算术的合法性边界由标准规定为 [begin, end]（end 可取得但不可解引用），越界即 U…","c":null},{"h":"📚 考研者视角","s":"面试必问：","c":null}]}],"exams":[{"kind":"choice","q":"关于指针与内存，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"new int[3] 必须用 delete 释放"},{"k":"B","t":"delete 后的指针应立即置 nullptr 更安全，且最好用智能指针消除手动管理"},{"k":"C","t":"返回局部变量的地址是安全的"},{"k":"D","t":"未初始化的裸指针默认指向 0"}],"ans":"B","why":"new[] 配 delete[]；返回局部地址悬垂；未初始化指针指向随机地址。"},{"kind":"fix_error","q":"修复内存泄漏","stem":"以下函数申请了堆内存却未释放，请修复（提示：用智能指针或配对 delete）： cpp int make() { int p = new int(5); return p; } // 调用方：int q = make(); / 用了但忘了 delete /","opts":[],"ans":"#include <memory> std::unique_ptr<int> make() { return std::make_unique<int>(5); }","why":"用 unique_ptr 把所有权交还调用方，离开作用域自动释放，杜绝泄漏。"},{"kind":"output","q":"读代码写输出","stem":"cpp #include <iostream> int main() { int a[3] = {10, 20, 30}; int p = a; std::cout << p << ' ' << (p + 2); }","opts":[],"ans":"10 30","why":"p 指向首元素，p+2 指向第三个元素。"},{"kind":"coding","q":"LeetCode 206 · 反转链表","stem":"给定单链表头节点，反转链表并返回新头。用指针操作（迭代或递归）实现 ListNode reverseList(ListNode head)。","opts":[],"ans":"#include <iostream> struct ListNode { int val; ListNode next; ListNode(int v):val(v),next(nullptr){} }; ListNode reverseList(ListNode head){ ListNode prev=nullp…","why":"经典三指针迭代，考察指针改向。"},{"kind":"coding","q":"牛客 BM1 · 反转链表","stem":"反转一个单链表。与 LeetCode 206 同义，按牛客 BM1 题型实现。指针操作，注意边界（空链表/单节点）。","opts":[],"ans":"#include <iostream> struct ListNode { int val; ListNode next; ListNode(int v):val(v),next(nullptr){} }; ListNode reverseList(ListNode head){ ListNode prev=nullp…","why":"牛客 TOP101 高频题，指针改向是面试必考。"}],"works":[{"h":"内存泄漏","d":"int p = new int; p = new int; 第一块内存地址丢失无法释放；或函数提前 return 漏了 delete。→ 用 std::unique_ptr 自动管理。"},{"h":"悬垂指针","d":"delete p; 后继续用 p，对象已回收，读取是 UB（值可能\"看起来还对\"但随时崩）。释放后及时置 nullptr 或改用智能指针。"},{"h":"new/delete 不匹配","d":"int a = new int[3]; delete a;（漏 []）是未定义行为，必须 delete[] a;。"},{"h":"返回局部变量地址","d":"int f(){ int x=1; return &x; } 调用方拿到悬垂指针；应返回对象本身或智能指针。"},{"h":"未初始化裸指针","d":"int p; 后直接 p，指向随机地址，崩溃。务必初始化。"},{"h":"异常路径漏 delete","d":"new 之后、delete 之前抛异常，delete 永不执行。C++ 没有 finally，必须靠 RAII（unique_ptr/容器）保证清理。"},{"h":"基类析构非虚却用基类指针 delete","d":"只调基类析构函数，派生类资源泄漏，UB。基类析构必须是 virtual。"},{"h":"大数组放栈","d":"int buf[1000000] 约 4 MB，超过默认栈上限（常见 1~8 MB）直接栈溢出。改用 std::vector（堆）。"}],"asks":[{"q":"指针和引用的本质区别是什么？什么时候必须用指针？","a":"引用是对象的别名，必须初始化且不可改绑，无空值语义；指针是独立变量存地址，可空、可重指向、可做地址运算。必须用指针的场景：需要表示“可能为空/可选”的对象（nullptr）、需要改变指向（如遍历/链表）、需要地址运算或底层内存操作、与 C API/数组交互。现代 C++ 默认 const 引用传参，仅在上述场景用指针（或智能指针）。","fu":["智能指针能完全取代裸指针吗？","函数参数何时用指针何时用引用？"],"tag":"通用"},{"q":"什么是内存泄漏？怎么在 C++ 里排查和预防？","a":"内存泄漏是申请了堆内存却再也无法释放（地址丢失或路径漏 delete），进程占用的内存只增不减。预防：①优先 RAII/智能指针（unique_ptr/shared_ptr）自动释放；②配对 new/delete、new[]/delete[]；③异常路径也保证释放（析构函数/智能指针）。排查：AddressSanitizer（-fsanitize=address）、Valgrind、Visual…","fu":["shared_ptr 循环引用为什么也会泄漏？","怎么用 ASan 跑出问题？"],"tag":"通用/字节"},{"q":"栈（stack）和堆（heap）有什么区别？","a":"①分配：栈由编译器自动（进入作用域分配、离开释放），堆由程序员 new/delete 手动管理；②速度：栈快（仅移动栈指针），堆慢（需查找空闲块）；③大小：栈有限（通常几 MB，大数组易溢出），堆大得多；④碎片：堆可能碎片化；⑤生命周期：栈对象随作用域结束，堆对象独立于作用域。大对象/需要跨作用域存活的用堆（或 vector 封装）。","fu":["为什么递归太深会栈溢出？","线程有自己的栈吗？"],"tag":"通用/腾讯"}]},{"id":"cpp-ch05","subj":"cpp","title":"类与对象：封装、构造/析构、拷贝与运算符重载","summary":"类定义与访问控制；构造函数/析构函数；拷贝构造与拷贝赋值（三/五法则）；const 成员函数；运算符重载；友元；静态成员。","concepts":[{"id":"cpp-ch05/01-class-basics","file":"01-class-basics.md","title":"01 · 类与对象：从对象模型到内存布局","kind":"stack","secs":[{"h":"一、理论根基：为什么要引入\"类\"","s":"从计算机科学的视角看，类（class）不是语法糖，而是一种抽象机制：它把「数据」与「作用于数据的操作」绑定，并用访问控制划出一条\"不变式（invariant）边界\"。","c":null},{"h":"二、实现机制：对象在内存里到底是什么","s":"这是程序员必须掌握的底层事实（C++ 对象模型，参见 Stanley Lippman《深度探索 C++ 对象模型》）：","c":null},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：眼见为实","s":"","c":{"lang":"cpp","code":"#include <iostream>\n\nstruct Empty {};\n\nstruct Bad  { char c; double d; char c2; };\nstruct Good { double d; char c; char c2; };\n\nclass Counter {\n    int value_ = 0;                      // private：不变式由类维护\n…"}}]},{"id":"cpp-ch05/02-ctor-dtor-copy","file":"02-ctor-dtor-copy.md","title":"02 · 对象生命周期：构造、析构与拷贝控制","kind":"timeline","secs":[{"h":"一、理论根基：什么是\"资源\"，为什么需要生命周期管理","s":"核心矛盾：资源的获取与释放必须成对发生，但中间可能提前返回或抛异常。","c":null},{"h":"二、实现机制：编译器到底合成了哪些函数","s":"一个类的\"特殊成员函数\"（C++11 起共 6 个），在用户未声明时可能被编译器隐式合成：","c":{"lang":"cpp","code":"struct Bad { int* p; Bad(int n): p(new int[n]) {} ~Bad(){ delete[] p; } };\nBad a(4); Bad b = a;   // 浅拷贝：a.p 与 b.p 指向同一块内存\n// 作用域结束 → 析构两次 → 双重释放（UB，通常崩溃）"}},{"h":"三、实现机制：拷贝省略与 RVO","s":"不要一看到\"返回对象\"就担心拷贝代价。编译器被允许（C++17 起部分情形强制）省略拷贝：","c":{"lang":"cpp","code":"T make() { return T(42); }   // C++17: 保证无拷贝（T 直接在调用者处构造）\nT x = make();"}},{"h":"四、工程实践：正确的拷贝赋值写法","s":"手写拷贝赋值必须处理自赋值与异常安全，惯用手法是 copy-and-swap：","c":{"lang":"cpp","code":"class Buf {\n    std::unique_ptr<int[]> data_; size_t n_;\npublic:\n    Buf(size_t n) : data_(std::make_unique<int[]>(n)), n_(n) {}\n    // Rule of Zero 的威力：unique_ptr 不可拷贝（自动禁止错误的浅拷贝）\n    //                     可移动（unique_ptr 自带移动语义）\n};"}},{"h":"五、边界与陷阱","s":"1. 构造函数中调用虚函数不触发多态：基类构造期间对象尚不完整，虚调用绑定到当前构造层（vptr 尚未切到派生类）。","c":null},{"h":"六、可运行示例：观察生命周期","s":"","c":{"lang":"cpp","code":"#include <iostream>\n\nstruct Traced {\n    int id;\n    explicit Traced(int i) : id(i) { std::cout << \"构造 \" << id << '\\n'; }\n    ~Traced()                      { std::cout << \"析构 \" << id << '\\n'; }\n    Traced(const Traced& o) : id(o.id) { std::cout << \"拷贝 \" << id << '\\n'; }\n};\n\n…"}}]},{"id":"cpp-ch05/03-operator-overload","file":"03-operator-overload.md","title":"03 · 运算符重载：重载决议、ADL 与对称性","kind":"compare","secs":[{"h":"一、理论根基：运算符本质上是\"有语法糖的函数调用\"","s":"写 a + b 时，编译器把它变换为：","c":null},{"h":"二、实现机制：重载决议与 ADL","s":"调用 a + b 时编译器要做重载决议（overload resolution）：","c":null},{"h":"三、成员函数 vs 非成员函数：对称性判据","s":"","c":{"lang":"cpp","code":"struct Vec { double x, y; };\nVec operator*(double k, const Vec& v) { return {k*v.x, k*v.y}; }  // 非成员：支持 2 * v\nVec operator*(const Vec& v, double k) { return k * v; }           // 再提供 v * 2"}},{"h":"四、工程实践：返回类型与复合赋值的约定","s":"1. 复合赋值 += 返回 T&（引用），支持链式：a += b += c。","c":null},{"h":"五、边界与陷阱","s":"1. 不要为了\"聪明\"重载：运算符语义应与数学/内置类型直觉一致。","c":null},{"h":"六、可运行示例","s":"","c":{"lang":"cpp","code":"#include <iostream>\n\nstruct Vec {\n    double x, y;\n    Vec& operator+=(const Vec& o) { x += o.x; y += o.y; return *this; }   // 返回引用\n    friend Vec operator+(Vec a, const Vec& b) { a += b; return a; }        // 复用 +=\n    friend Vec operator*(double k, const Vec& v) { return {k*v.x, k*v.y}; }// 非成员：支持 2*v\n    friend Vec operator*(const Vec& v, double k) { return k * v; }\n    friend std::ostream& operator<<(std::ostream& os, const Vec& v) {\n…"}}]},{"id":"cpp-ch05/04-class-practical-recipes","file":"04-class-practical-recipes.md","title":"类与对象实战手记：凯喵的十二次封装事故复盘","kind":"flow","secs":[{"h":"开场：一个只有三个字段的类，为什么改了两天","s":"凯喵接手的第一份 C++ 代码里有一个 Task 类，三个字段：标题、优先级、完成标记。按说这种类闭着眼都能写对，可它偏偏出了两个问题：优先级偶尔变成随机数，以及把它放进 std::vector 之后，某个任务的名字莫名其妙变成了另一个…","c":{"lang":"cpp","code":"#include <cstddef>\n#include <vector>\n\nclass Buffer {\npublic:\n    // 写法 A：初始化列表按\"依赖顺序\"写，但声明顺序相反\n    Buffer(std::size_t n) : size_(n), data_(size_) {}\n    //                       ↑ 先执行 data_，此时 size_ 是垃圾值\n\n…"}},{"h":"收尾：封装是一种承诺，不是一层括号","s":"凯喵最后想说的一句是：private 不是「别人不许看」，而是「我承诺这些字段任何时候都满足我的不变量」。构造函数负责建立不变量，成员函数负责维持它，析构函数负责体面地收尾。只要这三件事成立，哪怕类里有一百个字段也没关系；一旦有一件事破…","c":null}]}],"exams":[{"kind":"choice","q":"关于 const 成员函数，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"const 成员函数可以修改成员变量"},{"k":"B","t":"const 对象只能调用 const 成员函数"},{"k":"C","t":"成员函数加 const 只影响返回值类型"},{"k":"D","t":"const 与非 const 版本不能构成重载"}],"ans":"B","why":"const 对象的状态不可改，只能调用承诺不改状态的 const 成员函数；const/非 const 成员函数可重载（按对象常量性区分）。"},{"kind":"fix_error","q":"修复拷贝赋值中的自赋值与泄漏","stem":"以下拷贝赋值在自赋值时会先销毁共享内存、又未防自赋值，存在 UB 与泄漏。请修复（保留深拷贝语义）： cpp class Vec { double d_; public: Vec& operator=(const Vec& o) { delete[] d_; d_ = new double[/n/]; // 缺少自赋值保护 return this; } };","opts":[],"ans":"Vec& operator=(const Vec& o) { if (this == &o) return this; // 防自赋值 double tmp = new double[/n/]; // 先分配 delete[] d_; // 再释放旧资源 d_ = tmp; return this; }","why":"先判自赋值；采用「先分配成功再释放旧资源」的拷贝并交换式写法，异常安全且避免悬垂。"},{"kind":"output","q":"读代码写输出（构造/析构顺序）","stem":"cpp #include <iostream> struct T { const char s; T(const char x):s(x){ std::cout << s << \"c \"; } ~T(){ std::cout << s << \"d \"; } }; int main() { T a(\"A\"); { T b(\"B\"); } std::cout << \"e \"; }","opts":[],"ans":"Ac Bc Bd e Ad","why":"a 先构造；进入块 b 构造；块结束 b 析构；打印 e；main 结束 a 析构。"},{"kind":"explain","q":"什么情况下必须自定义拷贝控制（三法则）","stem":"解释：为什么管理裸指针/资源的类必须自定义拷贝构造、拷贝赋值与析构？简述三法则与五法则。","opts":[],"ans":"当类手动管理资源（裸指针、文件句柄等）时，编译器生成的逐成员浅拷贝会让多个对象共享同一资源，析构时 double free。三法则：需要析构/拷贝构造/拷贝赋值之一，通常三者都要。C++11 后扩展为五法则（加移动构造与移动赋值）。","why":"核心是「资源管理职责」与「浅拷贝陷阱」；RAII 下析构负责释放，拷贝负责深拷贝或禁用以保持不变量。"},{"kind":"coding","q":"实现字符串包装类的拷贝构造","stem":"实现 MyStr 的拷贝构造函数，使其与源对象各自拥有独立内存（深拷贝）。已给出构造函数与析构。","opts":[],"ans":"#include <iostream> #include <cstring> class MyStr { char p_; public: MyStr(const char s){ p_=new char[std::strlen(s)+1]; std::strcpy(p_,s); } MyStr(const MyStr…","why":"拷贝构造必须重新 new 一块内存并逐字节拷贝，否则与 a 共享 p_，析构时双重释放。"},{"kind":"design","q":"LeetCode 707 · 设计链表","stem":"设计单/双向链表数据结构，支持头部/尾部插入、按索引取值、按索引插入/删除等接口。请用类封装节点与链表（详见 external_url，不在此复述题面）。","opts":[],"ans":"class MyLinkedList { struct Node { int val; Node next; Node(int v):val(v),next(nullptr){} }; Node head_ = nullptr; int sz_ = 0; public: int get(int i){ if(i<0||…","why":"用类封装节点与哨兵逻辑，注意索引越界返回 -1、增删时维护 size 与指针。"},{"kind":"design","q":"牛客 BM101 · 设计 LRU 缓存","stem":"设计一个满足 LRU（最近最少使用）淘汰策略的缓存结构，支持 O(1) 查询与更新。建议用类封装哈希表 + 双向链表（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 用类封装：unordered_map<key, list<Node>::iterator> + list 维护使用序 // get 命中则把节点移到表头；put 超容量则删除表尾并同步删 map。 // 具体实现见 external_url 原题要求。","why":"核心是「哈希 O(1) 定位 + 双向链表维护冷热序」，二者都需封装在同一类中，并保证迭代器在节点移动后仍然有效。"}],"works":[{"h":"忘记定义拷贝控制导致双重释放","d":"管理裸指针却不写拷贝构造/赋值/析构，编译器浅拷贝使两个对象指向同一内存，析构时 delete 两次崩溃。 用智能指针（ch10）或严格实现 Rule of Three/Five。"},{"h":"拷贝赋值未处理自赋值与内存泄漏","d":"cpp Vec& operator=(const Vec& o) { delete[] data_; // 若 this==&o，先销毁了共享内存 data_ = new double[...]; // 已悬空 } 先 if (this == &o) return this;，再释放旧资源、深拷贝。"},{"h":"const 对象调用非 const 成员函数","d":"const Counter c; c.inc(); 编译失败——inc() 未声明 const。 不修改状态的函数一律加 const。"},{"h":"构造函数内调用虚函数不触发多态","d":"基类构造期间对象尚未成为派生类，虚调用绑定到当前构造中的类（见 ch06）。"},{"h":"在构造函数/析构函数中抛异常导致资源泄漏","d":"构造中途抛异常，已分配成员由编译器自动析构，但裸指针手动 new 的部分需谨慎。 用成员初始化列表 + 智能指针（RAII），让异常安全由析构保证。"},{"h":"返回局部对象的引用","d":"Money& f() { Money m; return m; } 返回已销毁对象的引用——悬垂引用。 返回值的场景用值返回（RVO 会避免拷贝）。"},{"h":"初始化列表顺序 ≠ 声明顺序","d":"初始化按成员声明顺序执行，与列表书写顺序无关；乱序会触发警告/未定义行为。 列表顺序与成员声明顺序保持一致。"},{"h":"滥用 friend 破坏封装","d":"随意 friend 全局函数会让 private 形同虚设。 仅在运算符对称性等必要时使用，保持最小暴露。"}],"asks":[{"q":"什么是三法则（Rule of Three）？什么情况下又该考虑五法则？","a":"若类需要自定义析构函数、拷贝构造函数、拷贝赋值运算符中的任意一个，通常三者都要自定义——因为这意味着类在管理某项资源（如裸指针），编译器默认的逐成员浅拷贝会造成多个对象共享同一资源、析构时双重释放。C++11 引入移动语义后，若还想支持高效的移动，就要再加移动构造与移动赋值，称为五法则。最省心的做法是优先用智能指针/容器，让编译器生成的默认版本就足够（零法则）。","fu":["为什么现在更推崇「零法则」？","移动构造为什么通常要标 noexcept？"],"tag":"通用/腾讯"},{"q":"构造函数初始化列表和函数体内赋值，哪个更好？为什么？","a":"优先用初始化列表：1) 对 const 成员、引用成员、没有默认构造的类的成员，只能在初始化列表里初始化，不能在函数体内赋值；2) 初始化列表直接构造，函数体内赋值是「先默认构造再拷贝赋值」，对复杂类型多一次开销；3) 成员按声明顺序初始化，与列表书写顺序无关，建议保持一致以免告警。","fu":["成员初始化顺序由什么决定？","哪些成员必须在初始化列表里初始化？"],"tag":"通用"},{"q":"运算符重载有哪些约定和禁区？以 operator= 为例说明返回值与自赋值。","a":"约定：+/ 等返回新对象（值），+=/= 返回 this 引用以支持链式；比较运算符返回 bool；单目 ++ 前置返回引用、后置返回值。禁区：不能创造新运算符（如 ）；不能重载 ::、.、?:、sizeof 等。以 operator= 为例：必须先判断自赋值（if (this == &o) return this;），再释放旧资源、深拷贝新资源，最后返回 this。","fu":["为什么 operator= 通常返回引用？","拷贝并交换（copy-and-swap）惯用法如何兼顾自赋值与异常安全？"],"tag":"字节/美团"}]},{"id":"cpp-ch06","subj":"cpp","title":"继承与多态：虚函数、抽象类与 RTTI","summary":"公有/保护/私有继承；派生类构造顺序；虚函数表与动态绑定；纯虚函数与抽象类；override/final；dynamic_cast 与 RTTI；多重继承要点。","concepts":[{"id":"cpp-ch06/01-inheritance-basics","file":"01-inheritance-basics.md","title":"01 · 继承的本质：子对象模型、访问边界与对象切片","kind":"stack","secs":[{"h":"一、理论根基：继承不是「代码复用」那么简单","s":"从语言设计视角，继承在 C++ 里首先是一种「子类型（subtyping）+ 子对象组合」机制，而非 Java/C# 那种单纯的类型层级。它同时承担两种语义：","c":null},{"h":"二、实现机制：派生类对象的真实内存布局","s":"编译器把派生类对象布局为「基类子对象在前，派生成员在后」（标准保证基类子对象地址可经适当转换得到，常见实现里基类子对象就在对象起始）。","c":{"lang":"text","code":"struct Base { int a; char b; };          // sizeof(Base)=8 (int 4 + char 1 + pad 3)\nstruct Der : Base { long c; double d; }; // 布局如下：\n\n  Der 对象（从高地址到低地址简化表示）:\n  +-------------------+  <- Der 起始 == Base 子对象起始\n  | int  a   (4)      |      Base 子对象\n  | char b   (1)      |\n  | pad     (3)       |\n  +-------------------+  <- 偏移 8\n…"}},{"h":"三、对象切片（Slicing）：值语义的代价","s":"当派生对象被按值赋给/传给基类对象时，拷贝的是「基类子对象」那一块，派生部分被丢弃：","c":{"lang":"cpp","code":"Der d; d.a = 1; d.c = 99;\nBase b = d;        // 只拷贝 Base 子对象 → b.c 不存在，d.c 被切片"}},{"h":"四、构造/析构顺序（与 ch05 衔接）","s":"构造由内向外（先基类子对象，再派生成员），析构由外向内（先派生，再基类）。这保证：在基类构造函数执行时，派生部分尚未存在；在派生析构执行时，基类子对象仍然有效。","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：验证构造顺序与内存布局","s":"","c":{"lang":"cpp","code":"#include <iostream>\nstruct Base {\n    Base()  { std::cout << \"Base-ctor \"; }\n    ~Base() { std::cout << \"Base-dtor \"; }\n};\nstruct Der : Base {\n    Der()  { std::cout << \"Der-ctor \"; }\n    ~Der() { std::cout << \"Der-dtor \"; }\n};\n…"}}]},{"id":"cpp-ch06/02-virtual-dispatch","file":"02-virtual-dispatch.md","title":"02 · 虚函数与动态绑定：vptr/vtable 内存布局、this 调整与性能","kind":"stack","secs":[{"h":"一、理论根基：为什么需要「运行期多态」","s":"静态类型语言要在「同一段代码对不同对象表现不同行为」之间取得平衡。两种主流方案：","c":null},{"h":"二、实现机制：vtable 与 vptr（核心）","s":"当类至少有一个虚函数时，编译器为它生成一张 vtable（虚函数表）：","c":{"lang":"text","code":"                .rodata (只读)                        栈/堆 (对象)\n            +-------------------+                 +------------------+\n            |  Base vtable:     |                 |  Base 对象:      |\n            |  [0] &Base::f     | ←---┐           |  vptr ───────────┼──┐\n            |  [1] &Base::g     |     │           +------------------+  │\n            +-------------------+     │                               │\n                                      └\n…"}},{"h":"三、this 指针调整（多继承下的 thunk）","s":"单继承时「派生对象起始 == 基类子对象起始」，所以 Base 与 Der 的值相同，无需调整。但多重继承下子类对象里各个基类子对象起始地址不同（见 03），通过次要基类指针调用「在派生类重写、属于派生接口」的虚函数时，必须把 this…","c":null},{"h":"四、override / final：把错误交给编译器","s":"","c":{"lang":"cpp","code":"struct Base { virtual void f(int); virtual void g() const; };\nstruct Der : Base {\n    void f(int) override;   // 编译器校验：确实覆盖了某个基类虚函数\n    // void g() override;    // 若签名不一致（如漏掉 const）→ 编译错误，而非悄悄新函数\n    void h() final;         // 禁止进一步派生类覆盖 h\n};"}},{"h":"五、与 Java / C# 的对比（程序员视角的工程取舍）","s":"","c":null},{"h":"六、性能与 ABI 影响","s":"1. 时间：虚调用 = 一次指针解引用 + 间接跳转，阻碍内联、可能误预测分支。但绝对多数业务代码瓶颈不在此；编译器能 devirtualize（静态类型可知 / PGO 确认唯一目标）时还原为直接调用。","c":null},{"h":"七、可运行示例：动态绑定与 override","s":"","c":{"lang":"cpp","code":"#include <iostream>\nstruct Animal {\n    virtual void speak() const { std::cout << \"Animal\\n\"; }\n    virtual ~Animal() = default;\n};\nstruct Dog : Animal {\n    void speak() const override { std::cout << \"Dog\\n\"; }   // 覆盖槽位 [0]\n};\nint main() {\n…"}}]},{"id":"cpp-ch06/03-abstract-rtti","file":"03-abstract-rtti.md","title":"03 · 抽象类、RTTI 与多重/虚继承：运行时查表与 this 修正","kind":"flow","secs":[{"h":"一、纯虚函数与抽象类：接口隔离的契约","s":"","c":{"lang":"cpp","code":"struct Shape {                       // 抽象类\n    virtual double area() const = 0; // 纯虚：必须被覆盖\n    virtual void draw() const = 0;\n    virtual ~Shape() = default;      // 仍要 virtual 析构（ch06 pitfalls 第 2 条）\n};"}},{"h":"二、RTTI：dynamic_cast 与 typeid 的运行时查表","s":"C++ 的运行时类型信息（RTTI）依赖 vtable 中额外存放的 std::type_info 与（多继承时）offset_to_top：","c":{"lang":"text","code":"dynamic_cast<Derived*>(base_ptr) 的运行期动作：\n  取 base_ptr 指向对象的 vtable → 读取 type_info / 继承链\n     ├─ 找到 Derived 在链上 → 计算 this 调整偏移 → 返回修正后的 Derived*\n     └─ 找不到            → 返回 nullptr（指针）/ 抛 bad_cast（引用）"}},{"h":"三、多重继承：多个 vptr 与 this 修正","s":"内存布局（示意）：","c":{"lang":"cpp","code":"struct A { virtual void fa(); int a; };\nstruct B { virtual void fb(); int b; };\nstruct C : A, B { virtual void fc(); int c; };"}},{"h":"四、菱形继承与虚继承：消除重复基类子对象","s":"经典菱形：D : B, C 且 B, C : A——D 里会有两份 A 子对象，带来二义性（pitfalls 第 4 条）。解决：虚继承 class B : virtual A。","c":{"lang":"text","code":"非虚继承（两份 A，二义）：          虚继承（共享一份 A）：\n        A                                  A (虚基类，仅一份)\n       / \\                                / \\\n      B   C                              B   C   (均 virtual 继承 A)\n       \\ /                                \\ /\n        D                                   D\n   D 内：B 的 A + C 的 A（重复）        D 内：仅一个共享 A 子对象"}},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：dynamic_cast 成功与失败","s":"","c":{"lang":"cpp","code":"#include <iostream>\nstruct Base { virtual ~Base() = default; };\nstruct Derived : Base { void hello() const { std::cout << \"Derived::hello\\n\"; } };\nstruct Other   : Base {};\n\nint main() {\n    Derived d;\n    Base* p1 = &d;\n    if (auto* dp = dynamic_cast<Derived*>(p1)) dp->hello();   // 成功\n…"}}]},{"id":"cpp-ch06/04-inheritance-practical-recipes","file":"04-inheritance-practical-recipes.md","title":"凯喵实战手记 · 继承、虚函数与 RTTI 的「多态陷阱」","kind":"flow","secs":[{"h":"现场 1：基类指针调派生类方法，忘了 virtual","s":"非虚函数按「静态类型」Base 决议，根本不走派生类。凯喵的规矩：想要多态行为，基类函数必须 virtual；现代 C++ 派生端加 override 让编译器帮你查签名。","c":{"lang":"cpp","code":"struct Base { void f() { cout << \"B\"; } };\nstruct Der : Base { void f() { cout << \"D\"; } };\nBase* p = new Der;\np->f(); // 输出 \"B\"，不是 \"D\""}},{"h":"现场 2：构造/析构里调虚函数不触发多态","s":"构造基类时对象还是「基类半成品」，虚表指向基类版本；析构对称。凯喵铁律：绝不在构造/析构里依赖虚函数的多态，把多态初始化推迟到构造完成后。","c":{"lang":"cpp","code":"struct Base {\n    Base() { virt(); }          // 调的是 Base::virt\n    virtual void virt() { cout << \"B\"; }\n};\nstruct Der : Base { void virt() override { cout << \"D\"; } };\nDer d; // 输出 \"B\"（构造 Base 时 Der 还没出生）"}},{"h":"现场 3：名字遮蔽（Name Hiding）掩盖基类重载","s":"派生类写了 void f(int)，基类的 void f(double)、void f() 会被整个隐藏，调用 d.f(1.0) 直接编译失败。凯喵的修法：派生类里写 using Base::f; 把基类重载集拉进来；或显式转发。","c":null},{"h":"现场 4：对象切片（Slicing）悄悄丢数据","s":"按值赋值时只拷贝基类子对象，派生部分凭空消失。凯喵铁律：需要多态就只用指针/引用（Base& / Base / 智能指针），绝不对多态类型按值传参或返回。","c":{"lang":"cpp","code":"Der d; Base b = d; // 只拷了 Base 子对象，Der 部分被切掉"}},{"h":"现场 5：dynamic_cast 对引用失败抛异常","s":"dynamic_cast<Der&>(base) 失败时抛 std::bad_cast，而非返回 null（引用不能为空）。凯喵：对指针用 dynamic_cast<Der>(p)（失败返回 nullptr，判空即可），对引用要准备好…","c":null},{"h":"现场 6：基类成员遮蔽与 protected","s":"派生类写了同名成员会遮蔽基类成员，: 访问到的未必是你想的那个。凯喵提醒：继承体系里命名要克制，必要时用 Base::member 显式指明；能 private 继承表达「实现复用」就别用 public。","c":null},{"h":"现场 7：纯虚析构必须给定义","s":"纯虚析构函数仍需在类外提供函数体 Base::~Base() {}。凯喵：想让类「抽象不可实例化」，用纯虚函数即可，析构别也标纯虚，徒增麻烦。","c":{"lang":"cpp","code":"struct Base { virtual ~Base() = 0; }; // 声明了纯虚析构\n// 但派生类析构会调用 Base::~Base()，若没定义 → 链接错误"}},{"h":"现场 8：多重继承的菱形与虚继承","s":"菱形继承产生两份基类子对象。凯喵的修法：B : virtual A、C : virtual A，让 D 共享一份 A（virtual 继承），访问 x 不再歧义，但对象布局变复杂、构造顺序由最派生类负责。","c":{"lang":"cpp","code":"struct A { int x; };\nstruct B : A {};\nstruct C : A {};\nstruct D : B, C {}; // D 里有两份 A::x，d.x 歧义"}},{"h":"现场 9：override / final 让你的意图被编译器校验","s":"没写 override 时这是「新函数」而非重写，Bug 静默产生。凯喵：所有重写都写 override；不希望再被覆盖的写 final。这两个关键字是免费的安全网。","c":{"lang":"cpp","code":"struct Der : Base {\n    void virt(int) override; // 编译报错：基类没有 void virt(int)，你以为是重写其实签名不符\n};"}},{"h":"现场 10：RTTI 的代价与禁用","s":"dynamic_cast / typeid 依赖运行期类型信息，开 -fno-rtti 时不可用，且对性能敏感路径有开销。凯喵：能靠虚函数多态解决就别用 RTTI；确实需要「按类型分发」时，考虑 std::variant + std::…","c":null},{"h":"现场 11：虚析构是基类的最低底线","s":"基类若可能被多态删除（delete basePtr），析构必须是 virtual，否则只调基类析构，派生部分泄漏。凯喵铁律：任何打算被继承并经由基类指针释放的类，virtual ~Base() = default; 必写。","c":null},{"h":"现场 12：拷贝/移动与继承的微妙","s":"派生类没写拷贝构造时，编译器生成的会调用基类拷贝 + 逐成员拷贝，通常 OK；但自己写了 =delete 或只定义移动，派生类可能继承到不合预期的行为。凯喵：继承体系里明确「五法则」，需要深拷贝就基类虚一个 clone() 返回 uni…","c":null},{"h":"凯喵复盘：对象的「出生与死亡」决定多态是否成立","s":"这 12 个现场里最反直觉的就是构造/析构期的虚函数行为。凯喵总跟人说：对象在构造函数执行期间，它还不是完整的派生类，虚表指针还指向基类版本，所以你在 Base() 里调 virt() 只能看到基类自己。析构对称——当派生部分已经销毁…","c":null},{"h":"凯喵速记：三句话记住继承的命脉","s":"若只记三句：第一，想多态就基类函数 virtual、派生端 override，编译器替你查签名；第二，多态类型绝不对值传递或返回，只用指针/引用，否则对象切片让派生部分凭空消失；第三，基类若可能被经指针 delete，析构必 virtu…","c":null},{"h":"🧑‍💻 程序员视角","s":"基类指针调用派生类重写的方法却没加 virtual，走的是静态绑定——运行时不会报错，只是「行为不对」，这类 bug 极难定位。构造/析构函数里调虚函数同样不触发多态：构造基类时派生类部分还没构造，虚表指针仍指向基类版本。最阴的是对象切…","c":null},{"h":"🎓 博士生视角","s":"虚函数的实现依赖虚表（vtable）与虚表指针（vptr）：每个多态类一张表，每个对象一个指针，调用时经两次间接寻址。这解释了「虚函数不能内联」以及「对象体积多一个指针」的代价。RTTI 的 dynamic_cast 依赖虚表里的类型信…","c":null},{"h":"📚 考研者视角","s":"面试必问：","c":null}]}],"exams":[{"kind":"choice","q":"关于虚函数与动态绑定，正确的是","stem":"选择正确的描述（可多选提示，答案单选）。","opts":[{"k":"A","t":"虚函数调用一定比普通函数慢，应尽量避免使用多态"},{"k":"B","t":"通过基类指针/引用调用虚函数时，实际调用的函数由「指针/引用所指向对象的动态类型」决定"},{"k":"C","t":"把派生对象按值赋给基类变量，虚函数仍会动态绑定到派生版本"},{"k":"D","t":"构造函数中调用虚函数会动态绑定到最派生类的版本"}],"ans":"B","why":"动态绑定的触发条件是「通过基类指针或引用 + 虚函数」；按值传递会对象切片（C 错）；构造/析构中虚调用静态绑定到当前层（D 错）；虚函数开销多数场景可忽略，且可被 devirtualization 优化（A 错）。"},{"kind":"output","q":"读代码写输出（构造顺序 + 虚函数）","stem":"cpp #include <iostream> struct B { B(){ std::cout << \"Bc \"; } ~B(){ std::cout << \"Bd \"; } virtual void f() const { std::cout << \"Bf \"; } }; struct D : B { D(){ std::cout << \"Dc \"; } ~D(){ std::cout <<…","opts":[],"ans":"Bc Dc Df Dd Bd","why":"构造由内向外：先 B 后 D；r.f() 因 r 指向 D 且 f 为虚 → 调 D::f；析构由外向内：先 D 后 B。"},{"kind":"fix_error","q":"修复「基类析构非 virtual」导致派生部分泄漏","stem":"以下代码 delete base_ptr 时只调用 ~Base，派生类申请的资源泄漏。请修复（最小改动）： cpp struct Base { ~Base() { / 释放基类资源 / } }; struct Derived : Base { int buf = new int[64]; ~Derived() { delete[] buf; } }; int main() { Base p = n…","opts":[],"ans":"struct Base { virtual ~Base() = default; }; // 关键：析构 virtual struct Derived : Base { int buf = new int[64]; ~Derived() override { delete[] buf; } // 推荐显式 overri…","why":"被多态继承的基类必须把析构声明为 virtual；= default 即可让编译器生成正确版本，delete 时沿最派生类析构链完整释放。"},{"kind":"choice","q":"关于对象切片（slicing），错误的是","stem":"选择错误的描述。","opts":[{"k":"A","t":"把派生对象按值赋给基类变量，会丢弃派生类独有的成员"},{"k":"B","t":"切片后通过基类变量调用虚函数，只会调用基类版本"},{"k":"C","t":"用基类引用或指针传递派生对象不会发生切片"},{"k":"D","t":"把派生对象按值赋给基类变量，动态绑定仍然生效"}],"ans":"D","why":"按值传递发生切片，得到的是纯基类子对象，虚调用静态绑定到基类（D 错）；引用/指针传递不切片（C 对）。"},{"kind":"coding","q":"实现抽象基类 Animal 与派生类 Cat/Dog","stem":"定义抽象基类 Animal，含纯虚函数 sound()（返回叫声字符串）与虚析构；派生 Cat/Dog 各自实现 sound()。用 std::unique_ptr<Animal> 持有对象并统一调用，输出各自叫声。","opts":[],"ans":"#include <iostream> #include <memory> #include <string> struct Animal { virtual std::string sound() const = 0; virtual ~Animal() = default; }; struct Cat : Anim…","why":"纯虚函数使 Animal 成为抽象类（不可实例化）；unique_ptr<Animal> 承载多态并自动释放；override 显式标注覆盖。"},{"kind":"design","q":"LeetCode 208 · 实现 Trie（前缀树）","stem":"设计一个支持 insert / search / startsWith 的 Trie（前缀树）数据结构。建议结合多态设计节点接口或把节点行为封装为类（详见 external_url，不在此复述题面）。","opts":[],"ans":"class Trie { struct Node { bool end = false; std::array<std::unique_ptr<Node>, 26> next; }; std::unique_ptr<Node> root_ = std::make_unique<Node>(); public: void…","why":"节点可用 RAII（unique_ptr）管理子节点，避免裸指针泄漏；多叉分支用定长数组（26 字母）换取 O(1) 跳转。"},{"kind":"design","q":"牛客 BM65 · 最长公共子序列","stem":"求两个字符串的最长公共子序列（LCS）长度。可借接口/策略类封装「比较与状态」以练习多态封装（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 经典 DP：dp[i][j] = LCS(s1[0..i), s2[0..j)) // 可将「状态转移」抽象为接口，由不同策略实现；此处核心是二维 DP + 滚动数组优化。 // 具体实现见 external_url 原题要求。","why":"DP 转移是 O(nm)；把状态比较封装为可替换策略，是本章「接口隔离变化」思想在算法题中的落地尝试。"}],"works":[{"h":"对象切片（Slicing）：用值传递多态对象","d":"把派生对象按值赋给基类变量/参数时，只拷贝「基类子对象」，派生部分被切掉，且虚调用不再动态绑定： cpp void f(Animal a) { a.speak(); } // 永远调 Animal::speak，即便传入 Dog Dog d; f(d); // d 被切片成 Animal 多态一律用引用或指针（Animal& / An…"},{"h":"基类析构函数未声明 virtual → 派生部分泄漏 / UB","d":"cpp struct Base { ~Base() {} }; // 非 virtual struct Derived : Base { int p = new int[8]; ~Derived(){ delete[] p; } }; Base b = new Derived; delete b; // 只调 ~Base，~Deriv…"},{"h":"忘记 override：签名写错却「默默新增重载」","d":"cpp struct Base { virtual void foo(int); }; struct Derived : Base { void foo(double) override; }; // 编译错误：根本没有可覆盖的 foo(double) // 若漏写 override：foo(double) 只是一个新函数，foo(i…"},{"h":"多重继承的菱形二义性","d":"cpp struct A { void f(); }; struct B : A {}; struct C : A {}; struct D : B, C {}; // D 里有两份 A 子对象 D d; d.f(); // 歧义：B::A::f 还是 C::A::f？——编译失败 用虚继承 struct B : virtual A…"},{"h":"dynamic_cast 对非多态类型返回 null / 编译失败","d":"对没有虚函数的类做 dynamic_cast<Derived>(base_ptr)：引用版本编译失败，指针版本返回 null（不做运行时检查）。 即便类型匹配，若基类无虚函数，指针 dynamic_cast 也会返回 null。 cpp struct Base {}; struct Der : Base {}; // 无虚函数 → 非…"},{"h":"基类成员遮蔽（Name Hiding）","d":"派生类定义了与基类同名的成员/函数，会隐藏基类所有同名重载，而非重载： cpp struct Base { void g(int); void g(double); }; struct Der : Base { void g(int); }; // 隐藏了 Base::g(double) Der d; d.g(1.0); // 错误：…"},{"h":"在基类构造/析构中调用虚函数不触发多态","d":"基类构造期间 vptr 指向「当前构造层的 vtable」，派生部分尚未存在；析构时派生部分已销毁。因此其中的虚调用静态绑定到当前层： cpp struct Base { Base(){ virt(); } virtual void virt(){ cout<<\"B\"; } }; struct Der : Base { void vi…"},{"h":"基类缺虚析构，多态删除泄漏","d":"Base p = new Der; delete p; 若 ~Base() 非虚，只调基类析构，派生部分泄漏。正确写法：任何打算经基类指针释放的类，virtual ~Base() = default;。"}],"asks":[{"q":"虚函数表（vtable）存放在哪里？单继承下对象内存如何布局？","a":"vtable 是一张只读数据段（.rodata）里的函数指针数组，由编译器为「至少有一个虚函数的类」生成一份（同类的所有对象共享）。每个该类的对象在构造时会被插入一个隐式成员 vptr（指向本类的 vtable），通常位于对象起始地址（实现相关，但这是主流布局）。单继承时，派生类对象内存 = [vptr][基类成员变量][派生类成员变量]，派生类自己的 vtable 在基类 vtable 基础上「…","fu":["vptr 一定在对象最前面吗？为什么构造期间要多次改写 vptr？","多重继承下有多个 vptr 吗？"],"tag":"通用/腾讯"},{"q":"多重继承下，this 指针为什么要调整（thunk）？","a":"当一个类 Der : B1, B2 时，对象内存里 B1 子对象从偏移 0 开始，B2 子对象在后面某偏移处。若你持有 B2 p = new Der，则 p 指向的是「Der 内部的 B2 子对象」而非 Der 起始——即 p 的值 ≠ (Der)p 的值，二者相差一个 offsetToTop。当通过 B2 调用一个在 Der 中重写、且属于 Der 接口的虚函数时，进入函数前的 this 必须被…","fu":["thunk 是什么？它如何影响调用开销与代码体积？","虚继承如何进一步改变 this 调整？"],"tag":"字节/美团"},{"q":"为什么基类析构函数必须是 virtual？不写会怎样？","a":"多态删除的语义是：delete base_ptr 时，必须调用「实际对象类型」的析构函数（从最派生类一路析构到基类），才能保证派生类拥有的资源被正确释放。析构函数若非 virtual，delete 表达式按静态类型（基类）调用 ~Base，派生类析构不执行——派生部分申请的堆内存/句柄全部泄漏，且行为是未定义（实践中常表现为只释放了基类子对象那块内存）。只要类设计成「会被继承并通过基类指针删除」…","fu":["如果一个类有虚函数但析构非 virtual，继承它安全吗？","std::unique_ptr<Base> 持有派生对象时，默认删除器依赖什么？"],"tag":"通用/阿里"},{"q":"虚函数有性能开销吗？体现在哪些方面？能否被优化掉？","a":"有三处成本：① 时间：每次虚调用是一次通过 vptr 的间接跳转，无法在调用点内联，且可能破坏分支预测/指令缓存局部性（间接跳转目标不固定）；② 空间：每个多态类一份 vtable（.rodata 膨胀），每个对象多一个 vptr（典型 8 字节/对象），对象整体变大、缓存利用率下降；③ 可维护性/编译：跨编译单元的虚调用削弱 LTO/内联。但现代编译器能做 devirtualization（当静…","fu":["CRTP 如何把运行期多态搬到编译期？它牺牲了什么？","devirtualization 在哪些条件下会失败？"],"tag":"字节/NVIDIA"}]},{"id":"cpp-ch07","subj":"cpp","title":"模板与泛型：函数模板、类模板与特化","summary":"函数模板与类型推导；类模板；模板特化（全/偏）；非类型模板参数；可变参数模板；模板实参推导与 SFINAE 入门。","concepts":[{"id":"cpp-ch07/01-function-template","file":"01-function-template.md","title":"01 · 函数模板：类型参数化、实参推导与重载决议","kind":"flow","secs":[{"h":"一、理论根基：模板解决的到底是什么问题","s":"在没有模板之前，要写\"对任意类型 T 都成立的 max\"，只能：","c":{"lang":"cpp","code":"template <typename T>\nT my_max(T a, T b) { return a > b ? a : b; }"}},{"h":"二、实现机制：模板实参推导（Template Argument Deduction）","s":"调用 my_max(3, 7) 时，编译器要做实参推导：","c":null},{"h":"三、实现机制：重载决议（Overload Resolution）与模板","s":"函数模板与手写函数（以及多个模板之间）参与同一套重载决议，规则要点（来自 [over.match]）：","c":null},{"h":"四、工程实践：实例化成本与头文件（包含模型）","s":"","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：眼见为实","s":"","c":{"lang":"cpp","code":"#include <iostream>\n\ntemplate <typename T>\nT my_max(T a, T b) { return a > b ? a : b; }   // 模板：类型参数化\n\n// 普通函数与模板同名，用于演示重载决议\nvoid demo(int x) { std::cout << \"普通函数 demo(int): \" << x << '\\n'; }\ntemplate <typename T>\nvoid demo(T x)    { std::cout << \"模板 demo(T): \" << x << '\\n'; }\n…"}}]},{"id":"cpp-ch07/02-class-template-specialization","file":"02-class-template-specialization.md","title":"02 · 类模板与特化：全特化、偏特化与特化优先级","kind":"flow","secs":[{"h":"一、理论根基：为什么类也需要模板与\"特化\"","s":"容器是类模板最自然的载体：std::vector<T> 对所有 T 共享同一套\"大小/扩容/下标\"逻辑，但行为在某些类型上应当不同——例如 std::vector<bool> 在 C++ 标准里被特化为位压缩存储（每个 bool 占 1…","c":null},{"h":"二、实现机制：类模板与实例化","s":"模板参数不限于类型，也可以是编译期常量：整型、枚举、nullptr_t、指针/引用（C++17 起还能是 auto 与字面量类类型）。","c":{"lang":"cpp","code":"template <typename T>\nclass Stack {\n    std::vector<T> data_;\npublic:\n    void push(const T& x) { data_.push_back(x); }\n    void pop()            { data_.pop_back(); }\n    T top() const         { return data_.back(); }\n    bool empty() const    { return data_.empty(); }\n};"}},{"h":"三、实现机制：全特化（Full / Explicit Specialization）","s":"为某一具体类型组合完全重写一份定义，所有模板参数都被固定：","c":{"lang":"cpp","code":"template <>\nclass Stack<bool> {            // 全特化：T 固定为 bool\n    unsigned bits_ = 0;\npublic:\n    void push(bool b) { bits_ = (bits_ << 1) | (b ? 1u : 0u); }\n    bool top() const { return bits_ & 1u; }\n    // ...\n};"}},{"h":"四、实现机制：偏特化（Partial Specialization）","s":"只固定部分模板参数，或对参数施加模式约束，其余仍参数化：","c":{"lang":"cpp","code":"// 主模板\ntemplate <typename T, typename U>\nstruct Pair { /* 异构对 */ };\n\n// 偏特化 ①：两个类型相同\ntemplate <typename T>\nstruct Pair<T, T> { /* 同类型对的优化实现 */ };\n\n// 偏特化 ②：第二个参数为指针\n…"}},{"h":"五、工程实践：特化的正确用法与陷阱","s":"1. 特化的\"主模板要先于特化可见\"：特化声明必须出现在主模板之后，且特化版本对原模板\"不可见\"内部成员不做任何隐式继承。","c":null},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：眼见为实","s":"","c":{"lang":"cpp","code":"#include <iostream>\n\n// 主模板\ntemplate <typename T, typename U>\nstruct Pair { static const char* tag() { return \"two types\"; } };\n\n// 偏特化：两类型相同\ntemplate <typename T>\nstruct Pair<T, T> { static const char* tag() { return \"same type\"; } };\n…"}}]},{"id":"cpp-ch07/03-variadic-sfinae","file":"03-variadic-sfinae.md","title":"03 · 可变参数模板与 SFINAE：参数包展开、折叠表达式与编译期重载筛选","kind":"flow","secs":[{"h":"一、理论根基：为什么需要\"参数个数可变\"的模板","s":"C 的可变参靠 std::va_list，但完全丢失类型信息、无类型安全、靠约定读取个数。C++11 引入可变参数模板（variadic templates）：把\"参数包（parameter pack）\"作为一等公民带入模板，每个元素都…","c":{"lang":"cpp","code":"template <typename... Ts>   // Ts 是类型参数包\nvoid f(Ts... args);         // args 是函数参数包"}},{"h":"二、实现机制：折叠表达式（C++17，强烈推荐）","s":"(包 op ...)（一元左折叠）等价于 (((e1 op e2) op e3) ... op en)。支持所有二元运算符，并可为空包提供初值：(args + ... + 0)。","c":{"lang":"cpp","code":"template <typename... Ts>\nauto sum(Ts... ts) { return (ts + ...); }        // 左折叠求和\n\ntemplate <typename... Ts>\nvoid print_all(Ts... ts) { (std::cout << ... << ts) << '\\n'; }  // 逗号式链式输出"}},{"h":"三、理论根基：SFINAE —— 替换失败并非错误","s":"这正是 §一 提到的\"推导失败不是错误\"的正式名称，但 SFINAE 的威力远超重载：它让我们能在编译期根据类型属性筛选重载。","c":{"lang":"cpp","code":"template <typename T>\ntypename std::enable_if<std::is_integral<T>::value, T>::type\nprocess(T v) { /* 仅当 T 是整型才存在此重载 */ }\n\ntemplate <typename T>\ntypename std::enable_if<std::is_floating_point<T>::value, T>::type\nprocess(T v) { /* 仅当 T 是浮点才存在此重载 */ }"}},{"h":"四、实现机制：检测\"是否有某成员\"（SFINAE 实战）","s":"用\"伪表达式 + decltype 替换\"探测类型能力（C++17 前标准库 void_t 惯用法）：","c":{"lang":"cpp","code":"template <typename T, typename = void>\nstruct has_size : std::false_type {};\ntemplate <typename T>\nstruct has_size<T, std::void_t<decltype(std::declval<T>().size())>> : std::true_type {};"}},{"h":"五、concept 的前世今生：SFINAE 的终结者","s":"SFINAE + enable_if + void_t 虽强大，但错误信息如天书（满屏\"替换失败\"），且写法晦涩、易出错。C++20 引入 concept / requires 从根本上解决：","c":null},{"h":"六、工程实践与陷阱","s":"","c":null},{"h":"七、可运行示例：眼见为实","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <type_traits>\n\n// ---- 可变参数 + 折叠表达式 ----\ntemplate <typename... Ts>\nauto sum(Ts... ts) { return (ts + ...); }               // 左折叠求和\n\ntemplate <typename... Ts>\nvoid print_all(Ts... ts) { (std::cout << ... << ts); std::cout << '\\n'; }\n…"}}]},{"id":"cpp-ch07/04-two-phase-compile-lookup","file":"04-two-phase-compile-lookup.md","title":"04 · 两阶段编译、依赖名与包含模型：模板为何\"难报错\"又\"必须放头文件\"","kind":"compare","secs":[{"h":"一、理论根基：模板为什么是\"两阶段\"编译","s":"普通函数编译一次即可；模板不能一次性编译成机器码，因为类型 T 未知。标准规定模板分两阶段处理（two-phase translation，[temp.res] / [temp.inst]）：","c":null},{"h":"二、实现机制：依赖名（Dependent Name）与两个关键字","s":"不写 typename 时，编译器按\"变量/成员\"解析 T::value_type，随后若它其实是类型就语法报错。规则：任何\"嵌套依赖类型名\"前加 typename。","c":{"lang":"cpp","code":"template <typename T>\nvoid f() {\n    typename T::value_type x;   // 必须写 typename：T::value_type 是依赖名，默认被当作\"值\"\n}"}},{"h":"三、实现机制：名称查找的两阶段（Dependent vs Non-dependent）","s":"经典坑：std::swap(a, b) 在模板里若直接 using std::swap; swap(a,b); 才能两阶段都正确落到用户特化（参见 concept 01 的重载决议）。","c":null},{"h":"四、工程实践：包含模型（为什么模板实现放头文件）","s":"由 §一 可知：实例化需要模板的完整定义。模板通常在头文件中给出完整定义（包含模型），调用方 #include 后即可在自身翻译单元内实例化。这与普通函数\"声明在 .h、定义在 .cpp\"相反：","c":null},{"h":"五、与 Java 泛型 / 类型擦除的本质区别（程序员视角）","s":"","c":null},{"h":"六、工程实践：模板的代码膨胀与编译期成本","s":"","c":null},{"h":"七、可运行示例：眼见为实","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <type_traits>\n\n// 依赖名 + typename / template 关键字的真实用法\ntemplate <typename T>\nvoid inspect() {\n    // T::value_type 是嵌套依赖类型名 → 必须 typename\n    using value_type = typename T::value_type;\n    std::cout << \"value_type size=\" << sizeof(value_type) << '\\n';\n…"}}]}],"exams":[{"kind":"choice","q":"关于函数模板实例化与头文件，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"模板在编译时直接生成一份通用机器码，运行时按类型选择"},{"k":"B","t":"模板实现通常放头文件，因为实例化需要模板完整定义对调用方可见（包含模型）"},{"k":"C","t":"模板实参推导时，多个参数可以各自推出不同的 T"},{"k":"D","t":"函数模板不能与普通函数构成重载"}],"ans":"B","why":"模板不是实体而是配方，实例化才生成具体代码（A 错）；多参数必须推出同一 T，否则推导冲突（C 错）；函数模板与普通函数参与同一套重载决议（D 错）。包含模型要求定义在调用处可见，故模板多放头文件（B 对）。"},{"kind":"fix_error","q":"修复模板中依赖名漏写 typename","stem":"以下模板无法编译：编译器不知道 T::value_type 是类型还是值。请修复（只需补关键字，不改逻辑）： cpp template <typename T> void f() { T::value_type x; // 编译报错：依赖名默认不被视为类型 }","opts":[],"ans":"template <typename T> void f() { typename T::value_type x; // 加 typename：告诉编译器这是嵌套依赖类型名 }","why":"两阶段编译下，依赖名 T::value_type 默认按“值/成员”解析；嵌套依赖类型名前必须加 typename 显式声明其为类型，否则语义阶段报语法错。"},{"kind":"output","q":"读代码写输出（函数模板重载决议）","stem":"cpp #include <iostream> template <typename T> void log(T v) { std::cout << \"T:\" << v << '\\n'; } void log(int v) { std::cout << \"int:\" << v << '\\n'; } int main() { log(42); log(3.14); log<>(7); }","opts":[],"ans":"int:42 T:3.14 T:7","why":"log(42) 有更特化的普通函数优先选中；log(3.14) 只有模板能匹配 double；log<>(7) 强制只从模板候选里选，故走模板版本。"},{"kind":"coding","q":"实现函数模板 my_max 并演示跨类型调用","stem":"实现 template<typename T> T my_max(T a, T b)，返回较大者；并演示当两实参类型不一致时，应显式指定模板实参 my_max<double>(3, 2.5) 以避免推导冲突。给出可编译运行的 main()。","opts":[],"ans":"#include <iostream> template <typename T> T my_max(T a, T b) { return a > b ? a : b; } int main() { std::cout << my_max(3, 7) << '\\n'; std::cout << my_max<doubl…","why":"多参数必须推出同一 T；跨类型调用需显式 <double> 让两实参都转 double，否则推导冲突硬报错。"},{"kind":"design","q":"牛客 BM90 · 最小覆盖子串（泛型滑动窗口）","stem":"用泛型/模板实现一个可复用的「滑动窗口」工具（如 SlidingWindow<T, Eq> 或模板函数 min_window(s, t, eq)），并基于它求解最小覆盖子串。题面与数据范围请见 external_url（不在此复述题面），本题重点考察：把窗口维护逻辑抽象为模板、用非类型/类型参数适配不同字符集与比较策略。","opts":[],"ans":"// 推荐结构：模板函数 min_window(string s, string t) 内部用数组作哈希（字符集固定） // 双指针维护窗口 [slow, fast]，用 need/count 两个计数判“窗口是否已覆盖 t”； // 收缩窗口求最小长度。完整题面与判题见 external_url。 // 泛型点：把“…","why":"核心算法是双指针 + 滑动窗口；用模板把“窗口覆盖判定”与“元素相等性”参数化，体现泛型复用。注意本题来自 nowcoder，仅存元数据与链接，不搬运题面。"},{"kind":"choice","q":"关于 SFINAE 与 std::enable_if，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"SFINAE 指替换失败时直接编译错误，必须修掉才能过"},{"k":"B","t":"把 enable_if 检查写进函数体，类型不满足时该候选会被悄悄丢弃"},{"k":"C","t":"SFINAE = 替换失败并非错误；enable_if 放在签名位置可在编译期按类型属性筛选重载"},{"k":"D","t":"std::enable_if 的两个条件无需互斥，编译器会自动选更优的一个"}],"ans":"C","why":"SFINAE 是“替换失败并非错误”，候选出局而非报错（A 错）；enable_if 必须放在签名位置（返回类型/默认模板参数），写在函数体里是硬错误（B 错）；多个 enable_if 条件必须互斥，否则同时启用会歧义（D 错）。"},{"kind":"coding","q":"GitHub · 用可变参数模板 + 折叠表达式实现泛型打印","stem":"实现 print_all(Ts... ts)：用 C++17 折叠表达式把任意数量、任意类型的实参顺序打印到一行（以空格分隔，末尾换行）。再用一个 sum(Ts...) 折叠求和验证可变参数模板。参考 external_url 中 TheAlgorithms 的 C++ 模板实践（不在此复述题面）。","opts":[],"ans":"#include <iostream> template <typename... Ts> void print_all(Ts... ts) { ((std::cout << ts << ' '), ...); std::cout << '\\n'; } template <typename... Ts> auto su…","why":"折叠表达式 (ts + ...) 一行实现任意长参数求和，((std::cout << ts << ' '), ...) 用逗号运算符顺序打印；二者都在编译期展开，零运行时间接。本题来自 github 模板实践仓库，仅存元数据与链接。"}],"works":[{"h":"模板声明与定义分离到不同文件导致链接错误（undefined reference）","d":"把函数/类模板的定义放进 .cpp、声明放进 .h，别的翻译单元 #include 后使用时，实例化点看不到定义，链接报 undefined reference to f<int>(int) 。 模板定义应放在头文件（包含模型）；若坚持分离，需在 .cpp 用 template void f<int>(int); 显式实例化导出。"},{"h":"依赖名前漏写 typename / template 关键字","d":"在模板里写 T::value_type x; 或 c.push_back<X>(...)（其中 T/c 类型依赖模板参数）会编译错：编译器默认依赖名不是类型、< 不是模板参数列表。 嵌套依赖类型名前加 typename（typename T::value_type）；成员模板调用前加 template（c.template push_…"},{"h":"模板特化优先级理解错导致选中错误版本 / 歧义","d":"偏特化之间若存在\"无可比特化关系\"的重叠，或全特化晚于主模板却未被优先选中，会选错或报歧义。 记牢顺序：全特化 > 越具体的偏特化 > 主模板；偏序规则是\"能把 A 的参数代入 B、反之不行，则 B 更特化\"。避免写出无法比较的重叠偏特化。"},{"h":"误入\"非推导上下文\"却指望自动推导","d":"template<class T> void f(typename Traits<T>::type); 中 T 嵌套在依赖类型里，无法从实参推导，调用必须显式 f<int>(...)；否则报\"无法推导模板参数\"。 把需要推导的参数放在\"非嵌套\"位置；或在调用处显式指定模板实参。"},{"h":"跨类型调用函数模板时推导冲突硬报错","d":"my_max(3, 2.5) 一边 int 一边 double，两个参数要推出同一 T → 冲突 → 编译错误。 显式指定 my_max<double>(3, 2.5)，或封装一层转为同类型，或用 auto/公共类型（std::common_type_t）。"},{"h":"SFINAE 误用：约束放在函数体内而非签名位置","d":"把 enable_if 检查写进函数体，类型不满足时不是\"候选出局\"，而是直接硬错误；且两个 enable_if 条件若不互斥会歧义。 把 enable_if/requires 放在返回类型或默认模板参数等签名位置；条件务必互斥；优先用 C++20 concept 替代 enable_if。"},{"h":"模板错误信息爆炸（代码膨胀 + 实例化链嵌套）","d":"深度嵌套模板（如 std::vector<std::map<...>>）一旦实例化失败，编译器吐出几十层 in instantiation of ... 栈，定位困难。 用 static_assert + concept 在入口给出\"人话\"约束；缩小模板接口、把非依赖逻辑抽成非模板函数；善用 -fsyntax-only 与编译器缩写（…"},{"h":"以为模板是\"运行时多态\"，滥用导致二进制膨胀","d":"把本可用 virtual / std::function 的类型分发硬写成大量类模板特化，导致每类型一份代码、二进制变大、编译变慢。 能用运行期多态（接口稳定、类型集开放）就用虚函数；模板适合\"类型集在编译期已知、要零开销\"的场景；必要时用类型擦除（std::function/any）折中。"}],"asks":[{"q":"什么是模板实例化？隐式/显式实例化与特化有何区别？为什么模板实现常放在头文件？","a":"实例化是编译器用具体模板实参（如 int）把模板“配方”生成为真实函数/类代码的过程。三种形态：① 隐式实例化——首次以某实参使用模板时自动生成；② 显式实例化——template int f<int>(int); 手动强制生成某实例（常用于把定义留在 .cpp 并导出）；③ 特化——为某具体/部分实参提供一份独立的定制定义（全/偏特化），与隐式生成不同，它是作者手写的新实现。 模板实现放头文件的…","fu":["显式实例化与显式特化（全特化）语法和语义差别？","extern template 如何缓解重复实例化？"],"tag":"通用/腾讯"},{"q":"SFINAE 是什么？std::enable_if 如何利用它做编译期重载筛选？C++20 concept 又解决了什么？","a":"SFINAE = Substitution Failure Is Not An Error（替换失败并非错误）。在模板实参推导与替换阶段，若某候选把实参代入其声明签名时产生非良构类型，该候选被悄悄丢弃而非报错，只要还有别的候选可匹配即可。 std::enable_if<B,T>::type 在 B==false 时没有 type 成员，把它放在返回类型（非推导上下文）配合 type_traits：…","fu":["SFINAE 与硬错误（函数体内错误）的边界在哪？","void_t 惯用法如何检测成员存在？"],"tag":"字节/美团"},{"q":"C++ 模板与 Java 泛型（类型擦除）的本质区别是什么？各有什么取舍？","a":"C++ 模板在编译期为每个实参组合生成独立的真实代码（图灵完备的编译期元编程）；Java 泛型是类型擦除——运行时只有一份擦成 Object/边界的代码，仅编译期保证类型安全。 关键差异：① C++ 保留运行时类型信息，可做偏特化、typeid；Java 运行时无类型、不能 instanceof List<Integer>、不支持特化。② C++ 直接支持基本类型 vector<int>，零抽象开…","fu":["为什么 Java 不改造成像 C++ 那样生成代码（reified generics 提案难点）？","C++ 模板代码膨胀如何缓解？"],"tag":"阿里/谷歌"},{"q":"可变参数模板如何展开？C++17 折叠表达式相比递归展开好在哪？","a":"可变参数模板用参数包（parameter pack）表示可变数量，Ts.../args... 在实例化时展开为逗号分隔列表。经典 C++11 用递归展开（一个参数+剩余包，配空包终止函数）。 C++17 折叠表达式 (args op ...) 把二元运算符对整包做编译期归约，sum = (ts + ...) 一行实现任意长参数求和，等价于手写 ((a+b)+c)+d。优势：① 无需写终止函数、无递…","fu":["一元折叠与二元折叠（带初值）区别？","空包在折叠表达式中为何可能需要初值？"],"tag":"通用/拼多多"}]},{"id":"cpp-ch08","subj":"cpp","title":"STL 容器：vector/list/map/set/unordered","summary":"顺序容器 vector/deque/list/forward_list；关联容器 map/set；无序容器 unordered_map/unordered_set；容器选择策略；迭代器类别。","concepts":[{"id":"cpp-ch08/01-vector","file":"01-vector.md","title":"01 · vector：连续内存、2× 扩容与迭代器失效","kind":"stack","secs":[{"h":"一、理论根基：为什么需要「可增长数组」","s":"高级语言的第一性需求之一，是在保留数组 O(1) 随机访问的同时，又能按需增长。C 风格数组长度固定，手动 realloc 既繁琐又易错。C++ 的标准答案是 std::vector——它是一个将「连续裸数组 + 长度/容量簿记」封装为…","c":null},{"h":"二、实现机制：amortized 2× 扩容到底发生了什么","s":"当 push_back 时发现 finish == end_of_storage（空间已满），容器必须扩容，标准流程是：","c":null},{"h":"三、实现机制：迭代器/引用/指针的失效规则","s":"因为扩容是「搬家到新地址」，旧块上的所有指针/引用/迭代器全部悬空。规则（[vector.modifiers]，C++ 标准）：","c":null},{"h":"四、工程实践：什么时候用 vector，怎么用","s":"1. 默认首选容器：只要没有「频繁在头部/中间插入删除」的硬性需求，vector 几乎永远是对的——它缓存最友好（连续内存顺序遍历能打满 prefetch），算法最多（<algorithm> 全部适配随机访问迭代器）。","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：眼见为实","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <vector>\n\nint main() {\n    std::vector<int> v;\n    std::cout << \"empty: size=\" << v.size() << \" cap=\" << v.capacity() << '\\n';\n    for (int i = 0; i < 9; ++i) {\n        v.push_back(i);\n        std::cout << \"after push \" << i\n…"}},{"h":"七、与 Java 对照","s":"","c":null}]},{"id":"cpp-ch08/02-associative","file":"02-associative.md","title":"02 · 关联容器 map/set：红黑树与「有序」的本质","kind":"flow","secs":[{"h":"一、理论根基：为什么需要「自动有序 + O(log n) 查找」","s":"vector 的查找是 O(n)（除非先排序再二分），且插入要保持有序就得 O(n) 搬移。当数据需要长期保持有序、又频繁增删查时，我们需要一种「任何时刻都能 O(log n) 插入/删除/查找，且中序遍历天然有序」的结构——这正是关联…","c":null},{"h":"二、实现机制：红黑树（Red-Black Tree）","s":"C++ 标准规定 map/set 是「以 key 为序的平衡二叉搜索树」，业界实现（libstdc++ / libc++ / MSVC）统一采用 红黑树——一种自平衡 BST，通过节点着色（红/黑）+ 旋转维持「黑高平衡」，从而保证：","c":null},{"h":"三、实现机制：关键接口的语义与复杂度","s":"","c":null},{"h":"四、工程实践：map 还是 unordered_map？","s":"经验法则（详见于 04 章容器选择）：","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：有序性 + operator[] 的副作用","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <map>\n#include <string>\n\nint main() {\n    std::map<std::string, int> score;\n    score[\"alice\"] = 90;\n    score[\"bob\"]   = 75;\n    score[\"carol\"] = 88;\n…"}},{"h":"七、与 Java 对照","s":"","c":null}]},{"id":"cpp-ch08/03-unordered","file":"03-unordered.md","title":"03 · 无序容器 unordered_：哈希表、冲突与负载因子","kind":"stack","secs":[{"h":"一、理论根基：用「哈希」换平均 O(1)","s":"当需要纯按 key 点查、不关心顺序时，红黑树的 O(log n) 仍不够快。理想是「像数组下标」一样 O(1) 访问——哈希表（hash table） 正是为此：把任意 key 经哈希函数映射到整数桶下标 bucket = hash(…","c":null},{"h":"二、实现机制：桶数组 + 链地址法（Separate Chaining）","s":"libstdc++/libc++ 的实现采用开链法（链式寻址）：一个桶数组 bucket[]，每个桶挂着一条单向链表（libstdc++ 早期为链表，现代用「桶内节点 + 桶间桶数组」结构，但逻辑仍是链地址）。插入/查找流程：","c":null},{"h":"三、实现机制：负载因子与再哈希（rehash）","s":"为维护平均 O(1)，容器设有阈值 max_load_factor（默认 1.0，libstdc++ 实际约为 1.0；有的实现默认 0.75/1.0）。当插入后 load_factor > max_load_factor，触发 reh…","c":null},{"h":"四、工程实践：怎么用好 unordered_","s":"1. 提供高质量哈希：内置类型（int/string 等）已有效果良好的 std::hash。自定义 key 类型必须特化 std::hash<YourKey> 或提供哈希函数对象，且 hash 与 key_equal 必须一致（相等的…","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例：频次统计 + rehash 观察","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <unordered_map>\n#include <string>\n\nint main() {\n    std::unordered_map<std::string, int> freq;\n    std::cout << \"init: buckets=\" << freq.bucket_count()\n              << \" load=\" << freq.load_factor() << '\\n';\n    for (std::string w : {\"a\",\"b\",\"c\",\"a\",\"b\",\"a\",\"d\",\"e\",\"f\",\"g\",\"h\"})\n…"}},{"h":"七、与 Java 对照","s":"","c":null}]},{"id":"cpp-ch08/04-selection","file":"04-selection.md","title":"04 · 容器选择、迭代器类别与缓存友好：工程决策框架","kind":"flow","secs":[{"h":"一、list / forward_list：节点结构为何「缓存不友好」","s":"std::list 是双向链表，每个节点在堆上单独 new，含 prev/next/value 三块；forward_list 是单向链表（C++11，无 size() 成员，更省内存）。它们的本质特征：","c":null},{"h":"二、迭代器类别（Iterator Categories）","s":"迭代器的能力层级决定了哪些算法能用它。按由弱到强：","c":null},{"h":"三、容器选择决策树（工程实践）","s":"经验法则（可直接背）：","c":{"lang":"text","code":"需要频繁随机访问（按下标）？\n├─ 是 → vector（默认）/ deque（头尾都频繁）/ array（固定大小）\n└─ 否 → 需要保持有序 / 范围查询？\n        ├─ 是 → map / set（红黑树，O(log n) 有序）\n        └─ 否 → 只去重 / 只点查？\n                ├─ 是 → unordered_set / unordered_map（平均 O(1)）\n                └─ 否 → 频繁在**中部**插入删除且持有迭代器？\n                        ├─ 是 → list / forward_list\n                        └─ 否 → vector（再次回到默认）"}},{"h":"四、内存局部性与缓存友好的量化直觉","s":"","c":null},{"h":"五、与 Java 容器对照速查","s":"","c":null},{"h":"六、可运行示例：vector 遍历 vs list 遍历计时对比","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <vector>\n#include <list>\n#include <chrono>\n\nint main() {\n    const int N = 5'000'000;\n    std::vector<int> v(N, 1);\n    std::list<int>   l(N, 1);\n…"}}]},{"id":"cpp-ch08/05-container-pitfalls-in-practice","file":"05-container-pitfalls-in-practice.md","title":"cpp-ch08 · STL 容器实战选择：凯喵带你踩过的坑","kind":"flow","secs":[{"h":"真实场景：vector 扩容带来的隐性拷贝","s":"凯喵写了 vector<int> v; for(...) v.push_back(x); 塞了十万个数，性能惨不忍睹。原因：capacity 不够时 vector 翻倍扩容、整体搬迁到新内存，平均每次 push 是 O(1) 摊还，但单…","c":{"lang":"cpp","code":"vector<int> v;\nv.reserve(100000);           // 一次性预留，杜绝中途搬迁\nfor (int i = 0; i < 100000; ++i) v.push_back(i);"}},{"h":"迭代器失效的三种现场","s":"vector 插入/删除会让指向其后的迭代器、引用、指针全部失效（元素搬迁）；list 只有被删节点的迭代器失效；unordered 容器 rehash 时全体迭代器失效。凯喵曾在 for 循环里 erase(it++) 却在 vect…","c":{"lang":"cpp","code":"// vector 正确删法：erase 返回下一个有效迭代器\nfor (auto it = v.begin(); it != v.end(); ) {\n    if (*it % 2 == 0) it = v.erase(it);\n    else ++it;\n}"}},{"h":"emplace_back 省掉的这一次拷贝","s":"push_back(T(...)) 先构造临时对象再移动；emplace_back(args...) 直接在容器内存里就地构造，少一次移动/拷贝，对重对象收益明显。","c":{"lang":"cpp","code":"struct Big { string name; vector<int> data; };\nv.push_back(Big{\"a\", {1,2,3}});   // 构造临时 + 移动\nv.emplace_back(\"a\", vector<int>{1,2,3});  // 原地构造，更省"}},{"h":"list 真的是 O(1) 插入吗（缓存视角）","s":"list 中部插入确实是 O(1)，但节点零散在堆上，遍历时缓存命中率极低。凯喵做过基准：vector 顺序遍历比 list 快数倍，哪怕 list 插入更快。结论：除非「频繁中部增删 + 长期持有迭代器」，否则 vector 优先。","c":null},{"h":"map 还是 unordered_map 怎么选","s":"map 是红黑树，key 有序、查找 O(log n)、内存紧凑；unordered_map 是哈希表，平均 O(1) 但最坏 O(n)、有哈希开销与重哈希。数据量小或需要有序遍历用 map，海量点查用 unordered_map。","c":null},{"h":"用 reserve 消灭扩容抖动","s":"不仅是 vector，unordered 容器用 reserve(n) 预分配桶，能避免插入时反复 rehash（rehash 会让所有迭代器失效且耗时）。已知规模就先 reserve。","c":null},{"h":"用 shrink_to_fit 归还多余容量","s":"vector 删掉大量元素后 capacity 不变，内存白占。shrink_to_fit() 请求归还，但标准只要求「请求」——多数实现会真的缩。","c":{"lang":"cpp","code":"v.clear();\nv.shrink_to_fit();   // 真正释放多余内存"}},{"h":"自定义 key 时的相等与哈希","s":"unordered 容器用自定义 struct 当 key，必须同时提供相等比较和哈希函数，否则要么编译不过要么运行时行为错乱。凯喵见过只写哈希不写 == 导致查不到的 bug。","c":{"lang":"cpp","code":"struct Pt { int x, y; };\nbool operator==(const Pt& a, const Pt& b){ return a.x==b.x && a.y==b.y; }\nstruct PtHash { size_t operator()(const Pt& p) const {\n    return hash<int>()(p.x) ^ (hash<int>()(p.y) << 1); } };\nunordered_set<Pt, PtHash> s;"}},{"h":"范围遍历里偷偷修改的陷阱","s":"for (auto x : m) 拿到的是拷贝，改 x 不影响容器；要改元素用 auto& 或 auto& kv。凯喵曾想「遍历时改 value」，结果改了副本，容器纹丝不动。","c":null},{"h":"容器选择决策清单","s":"末尾给一张「闭眼可用」的清单：默认 vector；需要键查且有序 → map；海量点查 → unordered_map；频繁两端增删 → deque；需要集合语义 → set/unordered_set；队列/栈 → queue/sta…","c":null},{"h":"🧑‍💻 程序员视角","s":"vector 扩容时把元素搬到新内存，所有旧迭代器、指针、引用立即失效——循环里 push_back 后再用之前的迭代器，是典型的 use-after-free。emplace_back 省掉的是「临时对象 + 移动」中的临时对象构造…","c":null},{"h":"🎓 博士生视角","s":"容器的选择本质是「访问模式 × 内存布局」的匹配：vector 连续存储、随机访问 O(1)、插入删除 O(n)，缓存友好；deque 分段连续，两端 O(1)；list/forward_list 结点式，任意位置插入 O(1) 但遍历…","c":null},{"h":"📚 考研者视角","s":"面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 vector 的扩容与迭代器失效，正确的是","stem":"以下描述中，选出正确的一项。","opts":[{"k":"A","t":"vector 每次 push_back 都会重新分配内存"},{"k":"B","t":"push_back 发生扩容时，所有已有的迭代器/引用/指针都会失效"},{"k":"C","t":"reserve(n) 会把 size 增加到 n"},{"k":"D","t":"vector 的 operator[] 会做越界检查并抛异常"}],"ans":"B","why":"扩容会整体搬到新地址，故所有迭代器/引用/指针失效（B 对）；A 错在只有容量不足才分配；reserve 只改 capacity 不改 size（C 错）；operator[] 不检查越界、越界是 UB，at() 才抛异常（D 错）。"},{"kind":"output","q":"读代码写输出（reserve 与扩容）","stem":"cpp #include <iostream> #include <vector> int main() { std::vector<int> v; v.reserve(4); for (int i = 0; i < 4; ++i) v.push_back(i); std::cout << v.size() << ' ' << v.capacity() << '\\n'; v.push_back(4…","opts":[],"ans":"4 4 5 8","why":"reserve(4) 使初始 capacity=4；push 0..3 不扩容，size=4 cap=4；第 5 个元素触发 2× 扩容到 8，size=5。"},{"kind":"fix_error","q":"修复 erase 循环中迭代器失效","stem":"以下代码在删除偶数元素时迭代器失效（erase 后 it 已悬空，再 ++it 是 UB）。请修复，使其能正确删除所有偶数且不崩溃： cpp std::vector<int> v = {1,2,3,4,5,6}; for (auto it = v.begin(); it != v.end(); ++it) if (it % 2 == 0) v.erase(it);","opts":[],"ans":"std::vector<int> v = {1,2,3,4,5,6}; for (auto it = v.begin(); it != v.end(); ) it = (it % 2 == 0) ? v.erase(it) : std::next(it); // 或 C++20：std::erase_if(v, [](…","why":"erase 返回下一个有效迭代器，必须用其推进；不能用失效的 it 再 ++。std::next(it) 在保留元素时前进。"},{"kind":"design","q":"LeetCode 1 · 两数之和","stem":"给定一个整数数组与目标和 target，返回两个数下标使其和为 target。请用一次遍历 + unordered_map 记录「值→下标」来把时间降到 O(n)（详见 external_url，不在此复述题面）。","opts":[],"ans":"vector<int> twoSum(vector<int>& nums, int target) { unordered_map<int,int> idx; // 值 -> 下标 for (int i = 0; i < (int)nums.size(); ++i) { auto it = idx.find(targe…","why":"每遇到 nums[i] 先查「补数 target-nums[i]」是否已在 map；不在就记录自身。平均 O(n)，空间 O(n)。"},{"kind":"design","q":"LeetCode 49 · 字母异位词分组","stem":"给定字符串数组，将互为字母异位词的字符串分到同一组。建议用「排序后的 key」或「计数 key」作为 unordered_map 的键，把同组串收集到 vector（详见 external_url，不在此复述题面）。","opts":[],"ans":"vector<vector<string>> groupAnagrams(vector<string>& s) { unordered_map<string, vector<string>> mp; // key=排序后的词 for (auto& w : s) { string k = w; sort(k.begin(…","why":"异位词排序后 key 相同，借 unordered_map<key,vector> 归类；平均 O(n·k·log k)（k 为词长）。"},{"kind":"design","q":"LeetCode 347 · 前 K 个高频元素","stem":"给定整数数组与 k，返回出现频率最高的前 k 个元素。建议先 unordered_map 统计频次，再用堆/快速选择取 Top-K（详见 external_url，不在此复述题面）。","opts":[],"ans":"vector<int> topKFrequent(vector<int>& nums, int k) { unordered_map<int,int> freq; // 频次统计 for (int x : nums) freq[x]++; // 用小顶堆维护前 k 大（按频次） using P = pair<int,i…","why":"unordered_map 计数 O(n)；小顶堆取 Top-K 为 O(m·log k)（m 为不同元素数），整体远优于全排序。"},{"kind":"design","q":"牛客 BM50 · 两数之和","stem":"在给定数组中找出和为 target 的两个数（返回下标，下标从 1 或 0 起依题面）。哈希表解法与 LeetCode 1 同思路（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 同 LeetCode 1：unordered_map<值,下标> 边遍历边查补数，O(n) 命中即返回。","why":"牛客 BM50 与 LeetCode 1 思路一致，注意返回下标的起始编号依题面要求调整。"}],"works":[{"h":"vector 扩容导致迭代器/引用/指针全部失效","d":"push_back/insert/resize 一旦触发扩容，底层会搬到新地址，旧块上的 it、&v[0]、v.data() 全部悬空。继续用就是 UB（常表现为数据错乱或崩溃）。 若循环中要增删且保留迭代器：用 it = v.insert(it, x); ++it; 的返回值推进；或先 reserve 预分配避免扩容；或改用下标 i…"},{"h":"erase 循环中迭代器失效（最经典的段错误来源）","d":"cpp for (auto it = v.begin(); it != v.end(); ++it) { if (it % 2 == 0) v.erase(it); // erase 后 it 失效，再 ++it 是 UB } 用返回值推进：for (auto it = v.begin(); it != v.end(); ) it =…"},{"h":"range-for 中修改容器导致失效 / 无限循环","d":"cpp for (auto& x : v) { v.push_back(x); } // push_back 可能扩容 → x 悬空（UB）；也极易死循环 range-for 期间不要插入/删除使迭代器失效；要改就把原容器内容先拷出，或改用带返回值的普通循环。"},{"h":"unordered_map 哈希质量差 → 最坏 O(n)","d":"自定义 key 的 std::hash 若把大量 key 映射到同一桶（如 hash % 2 式设计、或可被攻击者构造碰撞），查询退化为链表 O(n)，且 rehash 频繁。 用高质量哈希（如组合各字段的 FNV-1a / 标准 std::hash 组合）；不可信输入用实现自带的盐化哈希；reserve 降低负载因子。"},{"h":"误用 map::operator[] 触发「意外插入」","d":"cpp auto it = m.find(\"k\"); if (m[\"k\"] > 0) { ... } // 即使只想读，[] 也会插入默认 value！size 悄悄 +1 只读用 m.find(k)（判 != end()）或 m.at(k)（越界抛异常、不插入）；C++20 用 m.contains(k) 做纯判断。"},{"h":"认为 unordered_ 的遍历顺序可预期","d":"unordered_map 顺序依赖桶布局/哈希，reserve/rehash 后顺序会变，绝不能依赖遍历顺序做断言或序列化。 需要有序输出就改用 map，或对 unordered_ 取出 key 后另行排序。"},{"h":"erase 后仍在用被删迭代器 / 误以为 erase 返回 void","d":"C++98 的 map::erase(it) 返回 void；C++11 起返回下一迭代器。旧代码 m.erase(it++); 仍对，但混用新写法更一致。 统一用 it = c.erase(it);（C++11+ 全容器通用）。"},{"h":"把 list 当 vector 用追求「O(1) 插入」却牺牲缓存","d":"仅因「中间插入 O(1)」就选 list，但场景其实是「建好后遍历多次」——结果比 vector 慢数倍（见 concept/04）。 先算访问模式；绝大多数情况 vector 是更优解，list 仅留给「频繁中部增删 + 持有迭代器不失效」场景。"}],"asks":[{"q":"vector 的扩容机制是怎样的？push_back 为什么是摊还 O(1)？","a":"vector 用三指针（start/finish/end_of_storage）维护连续内存，size 与 capacity 解耦。当 push_back 发现 finish == end_of_storage 时触发扩容：通常按约 2 倍分配新块（实现相关，主流是 2×，MSVC 旧版 1.5×），把旧元素移动/拷贝过去，释放旧块。摊还 O(1) 来自等比数列：第 i 次扩容搬运约 C_{i-1…","fu":["扩容后迭代器/引用/指针为何失效？","vector 与 Java ArrayList 扩容因子差多少？"],"tag":"通用/腾讯"},{"q":"map / set 与 unordered_map / unordered_set 的区别？分别什么时候用？","a":"有序关联容器（map/set）底层是红黑树（自平衡 BST），元素按 key 有序，查找/插入/删除均 O(log n)，支持 lower_bound、范围查询、前驱后继；迭代器是双向迭代器。无序关联容器（unordered_）底层是哈希表（桶+链地址法），平均 O(1) 点查，最坏 O(n)（哈希碰撞），迭代器是前向迭代器，遍历顺序不可预期。 选型：需要有序 / 范围查询 / 按序输出 → ma…","fu":["unordered_map 最坏为什么是 O(n)？","rehash 时迭代器/引用是否失效？"],"tag":"通用/阿里"},{"q":"什么操作会导致迭代器失效？vector / list / map 各有什么不同？","a":"vector：insert/push_back（扩容时）使所有迭代器/引用/指针失效；erase(pos) 使 pos 及之后失效；reserve/resize 触发扩容同理。list：插入/删除不使其他迭代器、引用失效（仅被删节点的失效），这是 list 相对 vector 的最大优势；迭代器是双向的。map/set（红黑树）：插入不使任何迭代器失效；erase(pos) 仅使 pos 失效，其…","fu":["range-for 里 push_back 为什么危险？","unordered_map rehash 后引用为何仍有效？"],"tag":"字节/拼多多"},{"q":"为什么 list 的 O(1) 插入在实际遍历场景常常比 vector 慢？","a":"因为 list 节点在堆上分散分配，内存不连续，顺序遍历时 CPU 缓存几乎每次都 miss（prefetcher 无法预测下一节点地址），且无法向量化；而 vector 连续内存一次缓存行喂饱多个元素。即便 list 插入/删除是指针级 O(1)，其顺序遍历常慢于 vector 的 O(n) 搬移数倍。结论：除非频繁在中部插入删除且持有迭代器不希望失效，否则默认选 vector；这是「算法复杂度…","fu":["list::sort 为什么不能用 std::sort？","何时真正该用 list？"],"tag":"字节/腾讯"}]},{"id":"cpp-ch09","subj":"cpp","title":"STL 算法与迭代器：sort/find/lambda/范围","summary":"迭代器分类；常用算法 sort/stable_sort/find/count/transform/accumulate；lambda 配合算法；C++20 范围（ranges）入门。","concepts":[{"id":"cpp-ch09/01-iterator-categories","file":"01-iterator-categories.md","title":"01 · 迭代器分类：算法契约与复杂度边界","kind":"compare","secs":[{"h":"一、理论根基：迭代器是「算法与容器之间的接口契约」","s":"从计算机科学的视角看，迭代器模式（Gamma 等《设计模式》）把「遍历」与「数据结构」解耦。C++ 没有为此发明新概念，而是把它锚定到一组递增的能力层级（concept 雏形）：","c":null},{"h":"二、实现机制：范畴如何被编译器强制（concept 之前 vs 之后）","s":"在 C++20 concept 之前，STL 用 “鸭子类型 + 模板实例化错误信息” 表达范畴约束：sort 的实现里一旦对前向迭代器使用 it + n，就会在实例化时报一长串模板错误。C++20 起直接用 std::random_a…","c":null},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：迭代器范畴差异（编译期可观察）","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <vector>\n#include <list>\n#include <iterator>\nint main() {\n    std::vector<int> v = {1,2,3};\n    auto it = v.begin();\n    std::cout << \"随机访问: *(it+2) = \" << *(it + 2) << '\\n';  // O(1) 跳跃\n\n…"}}]},{"id":"cpp-ch09/02-algorithms-lambda","file":"02-algorithms-lambda.md","title":"02 · 常用算法与 lambda：sort/find/transform/accumulate 内部机理","kind":"flow","secs":[{"h":"一、理论根基：泛型算法 = 「对迭代器区间施加的纯函数式操作」","s":"STL 算法的第一性原理是 「数据结构的操作」与「数据结构本身」正交：<algorithm> 里几乎所有函数都形如 f(first, last, ...)，操作的是半开区间 [first, last)，与容器类型无关。这本质是函数式编程…","c":null},{"h":"二、实现机制：sort 的 introsort（混合排序）","s":"std::sort 的复杂度要求是 O(N log N) 平均、且最坏不能退化成 O(N²)。libstdc++ / libc++ 均采用 introsort（introspective sort，Musser 1997）：","c":null},{"h":"三、工程实践：lambda 配合算法","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例","s":"见 examples/ex01（sort）、ex02（stable_sort）、ex03（find）、ex04（count）、ex05（transform）、ex06（accumulate）、ex07（stable_partition）…","c":null}]},{"id":"cpp-ch09/03-ranges-cpp20","file":"03-ranges-cpp20.md","title":"03 · C++20 ranges：惰性求值与可组合管道","kind":"compare","secs":[{"h":"一、理论根基：从「立即执行」到「惰性视图」","s":"C++98–17 的传统算法（如 std::transform / std::copy_if）是 eager（立即执行） 的：必须先把结果写进一个已分配好的容器里，再喂给下一个算法——于是产生大量中间 vector 与拷贝。<range…","c":null},{"h":"二、实现机制：惰性如何发生","s":"std::views::filter 返回的是一个 filter_view，它内部只存「底层区间 + 谓词」。当你写：","c":{"lang":"cpp","code":"for (int y : v | views::filter(even) | views::transform(sq) | views::take(3)) { ... }"}},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例","s":"见 examples/ex08：惰性管道 filter(even) | transform(sq) | take(3)，并用计数器实证「只访问了必要元素」——证明惰性求值。","c":null}]},{"id":"cpp-ch09/04-iterator-algo-practical-recipes","file":"04-iterator-algo-practical-recipes.md","title":"迭代器与算法实战手记：凯喵的十二次「编译过了，结果就是不对」","kind":"flow","secs":[{"h":"开场：算法不是函数，是契约","s":"std::sort 不检查你的比较器是否是严格弱序，std::lower_bound 不检查你的区间是否已排序，std::copy 不检查目标区间是否够大。它们全部信任调用者——因为检查的代价太高，而且这些前置条件在编译期无法验证。","c":{"lang":"cpp","code":"#include <iterator>\n#include <list>\n#include <vector>\n\nstatic_assert(std::is_same_v<\n    std::iterator_traits<std::vector<int>::iterator>::iterator_category,\n    std::random_access_iterator_tag>);\n\n// list 是双向：支持 ++/--，不支持 it + 3\n…"}},{"h":"收尾：用 STL 的三条纪律","s":"凯喵最后总结：STL 算法用得好不好，取决于三条纪律。","c":null}]}],"exams":[{"kind":"choice","q":"关于 std::sort 的比较器，正确的是","stem":"以下描述中，选出正确的一项。","opts":[{"k":"A","t":"比较器可以写成 a <= b，方便表达「小于等于」"},{"k":"B","t":"std::sort 的比较器必须满足严格弱序（Strict Weak Ordering）"},{"k":"C","t":"std::list 可以直接传随机访问迭代器给 std::sort"},{"k":"D","t":"std::sort 最坏复杂度可能退化到 O(N^2) 也无所谓"}],"ans":"B","why":"sort 要求严格弱序，违反即 UB（A 错）；list 是双向迭代器，不能调需要随机访问的 std::sort，只能 list::sort（C 错）；introsort 把最坏锁在 O(N log N)（D 错）。"},{"kind":"output","q":"读代码写输出（stable_sort 稳定性）","stem":"cpp #include <iostream> #include <vector> #include <algorithm> struct Item { int key; int id; }; int main() { std::vector<Item> a = {{1,0},{2,1},{1,2},{3,3},{2,4},{1,5}}; std::stable_sort(a.begin(), a…","opts":[],"ans":"1:0 1:2 1:5 2:1 2:4 3:3","why":"stable_sort 对相等 key 保持原相对顺序：key=1 的 id 依次为 0,2,5；key=2 为 1,4；key=3 为 3。"},{"kind":"fix_error","q":"修复 erase 循环中的迭代器失效","stem":"以下代码删除偶数元素，但 erase(it) 后 it 已失效，再 ++it 是 UB。请修复，使其安全删除所有偶数： cpp std::vector<int> v = {1,2,3,4,5,6}; for (auto it = v.begin(); it != v.end(); ++it) if (it % 2 == 0) v.erase(it);","opts":[],"ans":"std::vector<int> v = {1,2,3,4,5,6}; for (auto it = v.begin(); it != v.end(); ) it = (it % 2 == 0) ? v.erase(it) : std::next(it); // C++20 更简洁：std::erase_if(v, […","why":"erase 返回下一有效迭代器，必须用其推进，绝不能用失效的 it 再 ++。需 #include <iterator> 用 std::next。"},{"kind":"coding","q":"用 STL 算法统计并输出词频 Top3","stem":"给定 vector<string> words，要求：1) 用 std::unordered_map 统计每个词频次；2) 用 std::vector 收集 (词,频次) 对；3) 用 std::sort + lambda 按频次降序排序并输出前 3 个（频次相同按字典序）。只调 STL，不手写排序循环。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向…","opts":[],"ans":"#include <algorithm> #include <iostream> #include <string> #include <unordered_map> #include <vector> int main() { int n = 0; if (!(std::cin >> n)) return 0; st…","why":"unordered_map 计数 O(N)；sort lambda 先比频次（降序）再比字典序；min(3,size) 避免越界。综合考察 find/count 思路 + sort + lambda。"},{"kind":"design","q":"LeetCode 75 · 颜色分类（sort-colors）","stem":"给定只含 0/1/2 的数组，原地按 0、1、2 顺序排好，要求一次扫描且常数空间（即「荷兰国旗问题」）。建议用双指针 / partition 思想原地划分（详见 external_url，不在此复述题面）。","opts":[],"ans":"void sortColors(vector<int>& a) { int lo = 0, mid = 0, hi = (int)a.size() - 1; while (mid <= hi) { if (a[mid] == 0) swap(a[lo++], a[mid++]); else if (a[mid] ==…","why":"三路划分：lo 之前全 0、hi 之后全 2、中间全 1；用「一次扫描 + 常数空间」的方法，本质与 std::partition 同族。"},{"kind":"design","q":"LeetCode 56 · 合并区间（merge-intervals）","stem":"给定若干闭区间，合并所有重叠的区间。标准做法是：先按左端点 sort，再线性扫描合并（详见 external_url，不在此复述题面）。","opts":[],"ans":"vector<vector<int>> merge(vector<vector<int>>& iv) { sort(iv.begin(), iv.end(), [](auto& a, auto& b){ return a[0] < b[0]; }); vector<vector<int>> ans; for (auto…","why":"先按左端点排序（sort + lambda），再贪心合并：当前区间左端点大于上一区间右端点就新开，否则延展。考察 sort + lambda + 区间处理。"},{"kind":"design","q":"牛客 BM89 · 合并区间","stem":"与 LeetCode 56 同思路：给定区间集合，合并所有重叠区间（注意牛客题面返回格式/下标约定）。建议先 sort 再扫描合并（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 同 LeetCode 56：按左端点 sort，再贪心合并；注意牛客返回下标/格式依题面调整。","why":"牛客 BM89 与 LeetCode 56 思路一致，重点仍是「排序 + 一次扫描合并」的 STL 算法组合。"}],"works":[{"h":"sort 比较器不满足严格弱序（Strict Weak Ordering）→ 未定义行为","d":"cpp std::sort(v.begin(), v.end(), [](int a, int b){ return a <= b; }); // 错：用了 <= sort 用比较器判定「相等/可交换」，违反非对称/传递会越界读写、死循环或数据错乱，且编译不报错。 比较器只用 <（或 > 用于降序），保证 comp(a,a)==fal…"},{"h":"迭代器失效：在 vector 上 erase 后继续使用旧迭代器","d":"vector 删除元素会使「被删位置及之后」的迭代器/引用/指针失效；扩容（push_back 触发）会使全部失效。在循环里 erase(it) 后再 ++it 是 UB（见 examples/ex09）。 用 it = v.erase(it) 拿返回值推进；或 C++20 std::erase_if。"},{"h":"find 找不到时直接解引用 end()","d":"cpp auto it = std::find(v.begin(), v.end(), x); std::cout << it; // 若 x 不存在，it==end()，解引用 UB 先判 if (it != v.end())，再解引用（见 examples/ex03）。"},{"h":"transform 目标区间容量不足 → 写入未分配空间","d":"cpp std::vector<int> b; // 空！ std::transform(a.begin(), a.end(), b.begin(), f); // UB：写到 b 的非法位置 预分配 std::vector<int> b(a.size());，或 std::back_inserter(b) 让算法 push_back…"},{"h":"lambda 引用捕获悬垂（dangling reference）","d":"cpp auto mk() { int k = 10; return &k{ return x + k; }; } // 返回后 k 已销毁 按引用捕获的变量必须保证 lambda 调用时该对象仍存活。 生命周期可控时再用 [&]；否则 [=]/初始化捕获 [k=std::move(big)] 按值捕获（见 examples/ex10…"},{"h":"partition 不保证稳定性，误以为相等元素顺序不变","d":"std::partition 会把「满足谓词」的元素聚到前端，但组内相对顺序不保证；需要保序用 std::stable_partition / std::stable_sort。 涉及「先按某键排序、再稳定分组/二次排序」时选 stable_（见 examples/ex02、ex07）。"},{"h":"把 std::remove 当成「删除元素」","d":"cpp std::remove(v.begin(), v.end(), 3); // 错：v.size() 一点没变 remove 是重排算法：它把要保留的元素前移，返回新的逻辑尾，容器大小不变，尾部残留的是被「移走」的旧值（不是被删掉）。 erase-remove 惯用法：v.erase(std::remove(v.begin(),…"},{"h":"在未排序区间上用 lower_bound / binary_search","d":"cpp std::vector<int> v = {3, 1, 2}; bool has = std::binary_search(v.begin(), v.end(), 2); // 区间无序 → 结果未定义 二分查找族（lower_bound/upper_bound/equal_range/binary_search）都要求区间已…"}],"asks":[{"q":"std::sort 底层是什么算法？为什么它最坏不会退化成 O(N^2)？","a":"主流标准库（libstdc++/libc++）实现的是 introsort（自省排序，Musser 1997）：先跑三数取中的快速排序，递归深度一旦超过 2·log2(N) 就切换到堆排序（把最坏锁在 O(N log N)），子区间小于阈值（约 16）时改用插入排序（小数据常数极小）。因此：平均 O(N log N)、最坏保证 O(N log N)，且比裸快排更抗恶意输入。它要求随机访问迭代器，所…","fu":["为什么 vector 的 sort 通常比 list::sort 更快？","stable_sort 用什么算法（归并）？代价是什么？"],"tag":"字节/腾讯"},{"q":"为什么 std::sort 的比较器必须满足「严格弱序（Strict Weak Ordering）」？写错会怎样？","a":"sort 内部用比较器同时做「小于」和「相等」判定：两块「互相都不小于对方」就被视为相等、可交换位置。严格弱序要求非自反、非对称、传递、等价类传递四条。若比较器违反（如写成 a <= b 或带等号、或浮点 NaN 比较），两个「应相等」的元素会被反复交换，分区指针会越过区间边界读写，结果是未定义行为——崩溃、死循环或数据错乱，且编译期不报错。正确写法只用 <（降序用 >）。","fu":["浮点 NaN 参与比较为什么危险？","如何给自定义类型写一个安全的比较器？"],"tag":"美团/阿里"},{"q":"C++ 有哪几类迭代器？算法复杂度如何被迭代器范畴约束？","a":"经典五类（C++20 再加连续迭代器）：输入/输出、前向、双向、随机访问。范畴是「算法对容器的能力要求」：算法只要求刚好够用的范畴。例如 std::sort 需要随机访问（要 O(1) 跳跃 partition），list 只有双向迭代器故不能调 std::sort；std::advance 对随机访问是 O(1) 指针算术，对双向/前向是 O(n) 一步步走。硬件层的差异是：随机访问对应 lea…","fu":["C++20 的 contiguous_iterator 解决了什么问题？","为什么输入迭代器只能单遍遍历？"],"tag":"通用/百度"},{"q":"什么是「无捕获 lambda 可隐式转函数指针」？和捕获 lambda 在性能上有何区别？","a":"无捕获的 lambda（如 [](int a,int b){ return a>b; }）没有状态，其 operator() 等价于一个普通函数，标准允许它隐式转换为函数指针——因此能传给任何接受函数指针的接口（包括 C API）。有捕获的 lambda 是带状态的闭包对象，不能转函数指针，但作为模板实参传入算法时通常会被内联展开，运行期零分发开销。std::sort 传无捕获 lambda 与传…","fu":["初始化捕获（C++14）[k=std::move(x)] 有什么用？","lambda 默认是 const 的，为什么需要 mutable？"],"tag":"腾讯/通用"}]},{"id":"cpp-ch10","subj":"cpp","title":"智能指针与 RAII：unique_ptr/shared_ptr/weak_ptr","summary":"RAII 原则；unique_ptr 独占所有权；shared_ptr 引用计数与循环引用；weak_ptr 打破循环；自定义删除器；与裸指针的边界。","concepts":[{"id":"cpp-ch10/01-raii","file":"01-raii.md","title":"01 · RAII：资源获取即初始化，与异常安全的第一性原理","kind":"flow","secs":[{"h":"一、理论根基：为什么\"确定性析构\"是 C++ 的脊梁","s":"为什么这能成立？因为 C++ 有一条语言级的、不可绕过的保证（[basic.stc]/[except.ctor]）：","c":null},{"h":"二、实现机制：析构调用到底是怎么被\"插入\"的","s":"从编译器的视角，RAII 等价于在每个作用域出口（包括异常路径）生成对析构函数的调用：","c":{"lang":"cpp","code":"void f() {\n    FileGuard g(open(\"x\"));   // 构造：获取资源\n    may_throw();              // 若抛异常 → 栈展开 → 自动调 g.~FileGuard()\n}                             // 正常返回 → 同样调 g.~FileGuard()"}},{"h":"三、工程实践：异常安全三保证与 RAII 的关系","s":"1. 基本保证：异常发生后，程序仍处于有效状态、无资源泄漏（RAII 即可达到）。","c":{"lang":"cpp","code":"// Rule of Zero：不写析构、不写拷贝、不写移动，全部交给成员\nclass Connection {\n    std::unique_ptr<Socket> sock_;          // 独占资源\n    std::lock_guard<std::mutex> lk_ = ...;   // 不可拷贝的 RAII\npublic:\n    Connection() : sock_(std::make_unique<Socket>()) {}\n};"}},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：观察 RAII 在异常下的确定性回收","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <memory>\n#include <stdexcept>\n\nstruct Guard {\n    const char* name;\n    explicit Guard(const char* n) : name(n) { std::cout << \"获取 \" << name << '\\n'; }\n    ~Guard() { std::cout << \"释放 \" << name << '\\n'; }\n};\n…"}}]},{"id":"cpp-ch10/02-unique-shared","file":"02-unique-shared.md","title":"02 · unique_ptr 独占 vs shared_ptr 引用计数：控制块、原子与开销","kind":"compare","secs":[{"h":"一、理论根基：两种\"所有权语义\"的数学区别","s":"智能指针本质是把\"谁负责 delete\"这件事编码进类型系统：","c":null},{"h":"二、实现机制：unique_ptr 为何\"零开销\"","s":"unique_ptr 只是一个带删除器的裸指针包装，典型布局：","c":{"lang":"text","code":"unique_ptr<T, D> { T* ptr; /* D 若无状态则被空基类优化(EBCO)消除 */ }"}},{"h":"三、实现机制：shared_ptr 的控制块与原子引用计数","s":"shared_ptr 的内存布局远比 unique_ptr 复杂。它内部持有两个指针或一个指针 + 控制块：","c":{"lang":"text","code":"shared_ptr<T> { T* ptr;  control_block* cb; }\ncontrol_block {\n    atomic<long> strong_count;   // 强引用（shared_ptr）计数\n    atomic<long> weak_count;     // 弱引用（weak_ptr + 自身）计数\n    deleter;                     // 类型擦除后的删除器\n    allocator;                   // 控制块自身的分配器\n    T*          object_ptr;       // 有时与 cb 合并（make_shared）\n}"}},{"h":"四、工程实践：选择矩阵","s":"","c":null},{"h":"五、可运行示例：计数变化与别名构造","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <memory>\n\nstruct Holder { int value = 7; };\n\nint main() {\n    auto holder = std::make_shared<Holder>();\n    std::shared_ptr<int> alias(holder, &holder->value);   // 别名构造\n    std::cout << *alias << '\\n';\n…"}}]},{"id":"cpp-ch10/03-weak-circular","file":"03-weak-circular.md","title":"03 · weak_ptr 打破循环、自定义删除器、enable_shared_from_this","kind":"flow","secs":[{"h":"一、理论根基：为什么 shared_ptr 处理不了循环引用","s":"shared_ptr 的释放条件是\"强引用计数降到 0\"。若存在 A ↔ B 的互相持有：","c":{"lang":"text","code":"A.sp_B → B     B.sp_A → A"}},{"h":"二、实现机制：weak_ptr 与控制块的弱计数","s":"weak_ptr 与 shared_ptr 共享同一个控制块，但只操作 weak_count（弱引用计数），不影响 strong_count：","c":null},{"h":"三、实现机制：自定义删除器（类型擦除的成本差异）","s":"删除器决定\"delete 时到底调什么\"。两种智能指针对删除器的处理策略截然不同：","c":null},{"h":"四、实现机制：enable_shared_from_this 与构造期陷阱","s":"std::enable_shared_from_this<T> 在 T 内部嵌入一个 weak_ptr<T> 成员。规则（[util.smartptr.enab]）：","c":null},{"h":"五、可运行示例：循环引用 vs 打破、enable_shared_from_this","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <memory>\n\nstruct A; struct B;\nstruct A { std::shared_ptr<B> b; ~A(){ std::cout << \"~A\\n\"; } };\nstruct B { std::weak_ptr<A>   a; ~B(){ std::cout << \"~B\\n\"; } };   // 弱引用打破环\n\nstruct Node : std::enable_shared_from_this<Node> {\n    void report() {\n…"}},{"h":"六、边界与陷阱","s":"","c":null}]},{"id":"cpp-ch10/04-smartptr-practical-recipes","file":"04-smartptr-practical-recipes.md","title":"§4 cpp-ch10 实战手记：凯喵带你把智能指针用「漏」","kind":"flow","secs":[{"h":"现场一：裸指针交给两个智能指针，双重释放","s":"凯喵 int p = new int; std::shared_ptr<int> a(p); std::shared_ptr<int> b(p); 两个独立控制块，析构时各 delete 一次，double free 崩溃。一个裸指针只…","c":{"lang":"cpp","code":"auto sp = std::make_shared<int>(1);   // ✅ 一个控制块\nauto sp2 = sp;                        // ✅ 拷贝共享，引用计数 +1\n// std::shared_ptr<int> a(p), b(p);   // ❌ 两个控制块，双重释放"}},{"h":"现场二：shared_ptr 循环引用，内存永远不释放","s":"凯喵让 A 持有 shared_ptr<B>、B 持有 shared_ptr<A>，引用计数永远 ≥1，析构时互相等对方先释放，内存泄漏。环里的一侧改用 weak_ptr 打破循环。","c":{"lang":"cpp","code":"struct B;\nstruct A { std::shared_ptr<B> b; ~A(){/* 不打印也行 */} };\nstruct B { std::weak_ptr<A> a; };     // ✅ weak_ptr 不增加计数，打破环\nauto a = std::make_shared<A>();\nauto b = std::make_shared<B>();\na->b = b; b->a = a;                   // 析构时正常释放"}},{"h":"现场三：用 this 直接构造 shared_ptr，自引用炸裂","s":"凯喵在成员函数里 return std::shared_ptr<Self>(this);，等于把这个裸 this 交给新控制块，和外部的 shared_ptr 不是同一个，双重释放。要让对象自身成为 shared_ptr 用 std::…","c":{"lang":"cpp","code":"struct Self : std::enable_shared_from_this<Self> {\n    std::shared_ptr<Self> get() { return shared_from_this(); }  // ✅ 共享同一控制块\n};\n// return std::shared_ptr<Self>(this);   // ❌ 新控制块，双重释放"}},{"h":"现场四：unique_ptr 当值返回会拷贝，编译失败","s":"凯喵 std::unique_ptr<T> p = make(); 想返回 unique_ptr 却编译不过——unique_ptr 不可拷贝，只能移动。返回用 return std::move(p) 或让函数返回类型就是 unique…","c":{"lang":"cpp","code":"std::unique_ptr<Res> make() {\n    auto p = std::make_unique<Res>();\n    return p;                  // ✅ 移动语义，自动转移所有权\n}\nstd::unique_ptr<Res> q = make();"}},{"h":"现场五：shared_ptr 和裸指针混用，生命周期失控","s":"凯喵 shared_ptr<T> sp = ...; T raw = sp.get(); 之后用 raw 访问，sp 提前析构后 raw 悬垂。.get() 只用于临时传给 C 接口，别长期持有；要共享所有权就再拷贝一个 shared_…","c":{"lang":"cpp","code":"void c_api(const T*);\nc_api(sp.get());              // ✅ 紧邻调用，sp 还活着\n// T* raw = sp.get(); use_later(raw);  // ❌ sp 可能已析构"}},{"h":"现场六：make_shared 与私有构造 / 单独控制块释放的权衡","s":"凯喵无脑 make_shared，但只要有 weak_ptr 存活，控制块（及合并分配）就一直不释放，哪怕对象本身已析构。需要「对象析构后立刻回收内存」或构造可能抛异常需隔离时，才用 shared_ptr<T>(new T(...),…","c":{"lang":"cpp","code":"// 普通场景直接 make_shared（一次分配，快）\nauto p = std::make_shared<Big>();\n// 需要 weak_ptr 频繁过期且内存敏感时，分开分配\nauto q = std::shared_ptr<Big>(new Big, std::default_delete<Big>());"}},{"h":"现场七：把栈对象地址塞进智能指针，析构时 double free","s":"凯喵 int x; std::shared_ptr<int> p(&x); 智能指针析构时会 delete &x，而 x 在栈上根本不能 delete，直接崩。智能指针只接管堆上 new 出来的对象（或自定义 deleter 管理的资源…","c":{"lang":"cpp","code":"// ❌ 栈对象不能交给智能指针\nint x; std::shared_ptr<int> p(&x);\n// ✅ 只接管堆对象\nauto p = std::make_shared<int>(0);"}},{"h":"现场八：数组用 shared_ptr<T> 而非 shared_ptr<T[]>，delet…","s":"凯喵 std::shared_ptr<int> p(new int[10]); 析构时用 delete 而非 delete[]，未定义行为。数组要用 std::shared_ptr<T[]>（C++17+）或干脆用 std::vecto…","c":{"lang":"cpp","code":"std::shared_ptr<int[]> arr(new int[10]);   // ✅ 数组特化，正确 delete[]\nstd::unique_ptr<int[]> u(new int[10]);     // ✅ 更轻量"}},{"h":"现场九：weak_ptr 没 lock 就用，悬垂访问","s":"凯喵 weak_ptr<T> w; w->foo(); 直接调用，weak_ptr 不能解引用。必须先 lock() 拿到 shared_ptr，判空后再用——锁失败说明目标已析构。","c":{"lang":"cpp","code":"if (auto sp = w.lock()) {        // ✅ lock 成功才有对象\n    sp->foo();\n}                                  // 失败说明已析构，安全跳过"}},{"h":"现场十：自定义 deleter 类型不一致，shared_ptr 不可赋值","s":"凯喵两个 shared_ptr 用了不同签名的 deleter，互相赋值编译失败——shared_ptr<T, Deleter> 的删除器是类型的一部分。需要不同类型间转换就统一 deleter 类型，或用默认 deleter。","c":{"lang":"cpp","code":"auto a = std::shared_ptr<Res>(new Res, [](Res* p){ delete p; });\nauto b = std::shared_ptr<Res>(new Res);   // 不同 deleter 类型，不能互赋"}},{"h":"现场十一：把智能指针当函数参数传值，意外延长生命周期","s":"凯喵函数参数写 void f(std::shared_ptr<T> p)（按值），调用处拷贝一次，引用计数 +1，对象在函数返回前不释放——可能比预期活得更久，还隐藏所有权。只读观察用 const T& 或 const shared_p…","c":{"lang":"cpp","code":"void observe(const T& o);                 // ✅ 只读，不碰所有权\nvoid take(std::shared_ptr<T> p);          // ✅ 真要接管所有权才按值"}},{"h":"现场十二：用 auto 推断 shared_ptr 结果，类型被吃掉","s":"凯喵 auto p = std::make_shared<Derived>(); std::shared_ptr<Base> b = p; 没问题，但若中间用 auto 接了 weak_ptr::lock() 返回又强转，容易混。明确类…","c":{"lang":"cpp","code":"std::shared_ptr<Base> b = std::make_shared<Derived>();  // ✅ 显式基类指针，多态清晰\n// auto x = b;  // x 是 shared_ptr<Base>，语义 OK 但隐式，关键处写全类型"}},{"h":"现场之外：凯喵的智能指针四句口诀","s":"用智能指针，凯喵把经验编成四句口诀。第一句，一个裸指针只许进一个智能指针，要共享就拷贝同一个 shared_ptr，绝不让两个独立控制块指向同一块内存。第二句，环里必有一侧是 weak_ptr，否则引用计数永远降不到零，内存悄悄泄漏。第…","c":null},{"h":"现场拾遗：先想所有权，再写代码","s":"最后一句话：用智能指针之前，先想清楚这块内存的「所有权」归谁。是独享就 unique_ptr，是共享就 shared_ptr，是临时观察就 raw 或 weak_ptr。很多内存 bug 的根源不是语法用错，而是一开始就没想清谁该负责释…","c":null},{"h":"一句话收尾","s":"凯喵最后提醒：智能指针再智能，也只是把「谁负责 delete」这件事自动化了，它替不了你对所有权的思考。一个函数到底是接管、共享还是只是借看一眼，这个判断得你来下，然后才选 unique、shared 还是 raw/weak。把智能指针…","c":null},{"h":"🧑‍💻 程序员视角","s":"同一个裸指针交给两个 shared_ptr 会各自建一个控制块，引用计数各算各的，最后双重释放——必须用 make_shared 或从已有的 shared_ptr 拷贝。循环引用是另一类泄漏：A 持有 B 的 shared_ptr、B…","c":null},{"h":"🎓 博士生视角","s":"shared_ptr 是「引用计数 + 控制块」的实现：控制块存强引用数、弱引用数、删除器与分配器，强引用归零时析构对象，弱引用归零时释放控制块。原子计数的增减带内存序开销，因此高频拷贝 shared_ptr 在多线程下会成为争用点。u…","c":null},{"h":"📚 考研者视角","s":"面试必问：","c":null}]}],"exams":[{"kind":"choice","q":"关于 unique_ptr 与 shared_ptr 的所有权语义，正确的是","stem":"以下描述中，选出正确的一项。","opts":[{"k":"A","t":"unique_ptr 可以随意拷贝，多个 unique_ptr 指向同一对象"},{"k":"B","t":"shared_ptr 的引用计数存放在 shared_ptr 对象本身里"},{"k":"C","t":"unique_ptr 默认删除器为空类型，经空基类优化后与裸指针同尺寸、零额外开销"},{"k":"D","t":"shared_ptr 能自动回收循环引用，无需 weak_ptr"}],"ans":"C","why":"unique_ptr 独占、不可拷贝（A 错）；引用计数在独立的控制块里，不在 shared_ptr 对象里（B 错）；shared_ptr 无法自动回收循环引用，需把环的一侧改为 weak_ptr（D 错）。unique_ptr 的默认删除器是空类型，EBCO 后 sizeof(unique_ptr<T>)==sizeof(T)，零额外内存、删除调用可内联（C 对）。"},{"kind":"output","q":"读代码写输出（shared_ptr use_count 变化）","stem":"cpp #include <iostream> #include <memory> int main() { auto p = std::make_shared<int>(10); std::cout << p.use_count() << '\\n'; auto q = p; std::cout << p.use_count() << '\\n'; q.reset(); std::cout << p…","opts":[],"ans":"1 2 1","why":"初始只有 p 持有 → 1；q=p 拷贝使强计数 +1 → 2；q.reset() 释放 q 的持有使强计数 -1 → 1。引用计数在共享的控制块里，p、q 看到同一数值。"},{"kind":"fix_error","q":"修复 shared_ptr 循环引用导致泄漏","stem":"以下代码 A、B 互相强引用，离开作用域后析构函数都不打印（泄漏）。请改最少代码打破循环（保留 A 强持有 B 的语义）： cpp struct A; struct B; struct A { std::shared_ptr<B> b; ~A(){ std::cout << \"~A\\n\"; } }; struct B { std::shared_ptr<A> a; ~B(){ std::cout…","opts":[],"ans":"struct B { std::weak_ptr<A> a; ~B(){ std::cout << \"~B\\n\"; } }; // 把 B 侧改为 weak_ptr // 若 B 需要访问 a 所指对象： auto sp = a.lock(); if (sp) sp->...;","why":"循环引用靠强引用互相钉死，必须把环的一侧改为 weak_ptr：B::a 改为 std::weak_ptr<A>，它不增加强计数，于是作用域结束时 A、B 的强计数能归零、析构正常触发。访问前用 lock() 提升并检查。"},{"kind":"design","q":"LeetCode 146 · LRU 缓存（用 shared_ptr 管理节点所有权）","stem":"设计并实现一个容量固定的 LRU 缓存，支持 O(1) 的 get/put。建议用 unordered_map<key, shared_ptr<Node>> + 双向链表（或 list）管理节点；删除最久未用时 shared_ptr 引用归零自动回收，避免手动 delete（详见 external_url，不在此复述题面）。","opts":[],"ans":"struct Node { int key, val; shared_ptr<Node> prev, next; }; // map: key -> shared_ptr<Node>；头尾哨兵节点 // get: 命中则把节点移到最近使用（splice 到头部） // put: 命中改值并提到头部；未命中新建节点，超容…","why":"用 shared_ptr 持有节点可让删除逻辑只关心『从 map 与链表移除』，内存回收交给引用计数；双向链表维护使用顺序保证 O(1)。注意 map 与链表必须同步，否则会出现悬空 shared_ptr。"},{"kind":"design","q":"牛客 BM101 · 设计 LRU 缓存（智能指针实现）","stem":"牛客 BM101 要求实现一个 LRU 缓存。可用 std::list 存键值对、unordered_map<int, list::iterator> 做索引，节点所有权交给容器自动管理；或用 shared_ptr 管理节点（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 思路同 LeetCode 146：list<pair<int,int>> 维护顺序，map<key, iterator> 索引； // 命中则 splice 到链头，超限则 pop_back 并 erase map 项，所有权由 STL 容器自动回收。","why":"BM101 与 LeetCode 146 同构。用 STL 容器（list/map）天然 RAII，省去手动内存管理；也可显式用 shared_ptr 体现本章知识点。"},{"kind":"coding","q":"用 unique_ptr 实现工厂函数 safe_open（独占所有权 + 自定义删除器）","stem":"实现一个工厂函数 std::unique_ptr<File, FileDeleter> safe_open(const char path)，返回一个独占文件句柄；自定义删除器 FileDeleter 在 fclose 前打印 \"closed\"。要求：不能拷贝返回的句柄（只能移动），离开作用域自动关闭。","opts":[],"ans":"struct FileDeleter { void operator()(FILE f) const { if (f) { std::cout << \"closed\\n\"; fclose(f); } } }; std::unique_ptr<FILE, FileDeleter> safe_open(const char…","why":"unique_ptr 的删除器是编译期类型参数，自定义 FileDeleter 在析构时自动 fclose；由于 unique_ptr 不可拷贝，所有权必须通过 std::move 转移，天然防止重复关闭。"}],"works":[{"h":"循环引用导致 shared_ptr 泄漏","d":"两个对象互相持有 shared_ptr，彼此强引用计数永远不为 0，析构不会被触发，内存与资源泄漏。 把其中一侧改为 weak_ptr（见 concept/03-weak-circular.md）。"},{"h":"enable_shared_from_this 在构造函数中调用 shared_from_t…","d":"尚未被任何 shared_ptr 接管时，内部 weak_ptr 还是空，shared_from_this() 直接抛 bad_weak_ptr（std::bad_weak_ptr，C++17 起）。 只在已由 shared_ptr 管理的成员函数里（如 init()、回调）调用 shared_from_this()，绝不在构造函数体…"},{"h":"把 this 直接交给新 shared_ptr（重复控制块 / 双重释放）","d":"std::shared_ptr<Self>(this); 会为 this 创建第二个控制块，与已有的控制块各自独立 → 析构时两次 delete 崩溃。 让类继承 std::enable_shared_from_this<Self>，统一用 shared_from_this() 取共享所有权。"},{"h":"混用 get() 返回的裸指针构造第二个 shared_ptr / unique_ptr","d":"auto q = std::shared_ptr<int>(p.get()); 与 p 各自拥有独立控制块，指向同一块内存 → 双重释放。 get() 只用于\"借用\"交给不接管所有权的 C API；绝不基于它再构造智能指针。若需共享，复制原 shared_ptr 或用 weak_ptr::lock()。"},{"h":"用 delete 而非 delete[] 释放 unique_ptr<T[]> 管理的数组","d":"std::unique_ptr<int> 默认删除器是 delete，对数组 UB；且 operator[] 不可用。 数组务必用 std::unique_ptr<T[]>（删除器自动为 delete[]，并提供 [] 下标访问），见 examples/ex04。"},{"h":"误以为 weak_ptr 自身持有所有权 / 直接解引用","d":"weak_ptr 不参与引用计数，不能直接 wp 或 wp->。 先 auto sp = wp.lock(); 提升为 shared_ptr 再使用；提升失败（expired() 为 true）即对象已析构。"},{"h":"shared_ptr 按值传参会抬高引用计数，带来原子开销","d":"大循环里反复按值传递 shared_ptr 会频繁执行原子递增/递减，成为性能热点。 只读观察场景传 const shared_ptr<T>&；确需延长生命周期才按值传；不可拷贝所有权时优先 unique_ptr 移动。"},{"h":"make_shared 与私有构造 / 单独控制块释放的权衡","d":"make_shared 把对象与控制块合并一次分配，但只要有 weak_ptr 存活，控制块（及合并分配）就一直不释放，哪怕对象本身已析构。 需要\"对象析构后立刻回收内存\"或构造可能抛异常需隔离时，才用 shared_ptr<T>(new T(...), deleter) 分开分配。"}],"asks":[{"q":"shared_ptr 的引用计数存在哪里？为什么会发生循环引用？weak_ptr 是如何打破循环的？","a":"引用计数不在 shared_ptr 对象里，而在一个独立的控制块（control block）中，所有指向同一对象的 shared_ptr/weak_ptr 共享它。控制块里有强引用计数（strong_count）和弱引用计数（weak_count），以及类型擦除后的删除器/分配器。 循环引用：若 A、B 互相用 shared_ptr 持有对方，双方的强计数被彼此钉死在 ≥1，外部最后一个持有者离…","fu":["强引用计数归零和弱引用计数归零分别释放什么？","为什么 weak_ptr::lock() 是线程安全的？"],"tag":"通用/字节"},{"q":"unique_ptr 和 shared_ptr 在性能与内存上有何本质区别？什么时候该用哪个？","a":"unique_ptr：独占所有权，不可拷贝只可移动。它只包装一个裸指针，默认删除器为空类型、经空基类优化后 sizeof == sizeof(T)，零额外内存；删除调用在编译期确定、可被内联，无堆分配、无原子操作。适合工厂返回值、唯一拥有者、成员独占资源。 shared_ptr：共享所有权。内部持有对象指针 + 控制块指针，控制块需一次堆分配（或与对象合并于 make_shared），每次拷贝/析…","fu":["为什么 shared_ptr 拷贝是 atomic 的？不共享同一对象时也要 atomic 吗？","shared_ptr 传值 vs 传 const 引用各有什么代价？"],"tag":"美团/阿里"},{"q":"enable_shared_from_this 是做什么的？为什么不能在构造函数里调用 shared_from_this()？","a":"std::enable_shared_from_this<T> 在类 T 内嵌一个 weak_ptr<T> 成员。当第一个 shared_ptr<T> 接管 this 时，会把这个内嵌 weak_ptr 初始化指向自身（同一控制块）。之后在成员函数里调用 shared_from_this()，就能把它安全地提升为指向自身的 shared_ptr，从而拿到共享所有权而不制造第二个控制块（避免双重释放…","fu":["为什么 shared_ptr(this) 是错的、会双重释放？","enable_shared_from_this 内嵌的 weak_ptr 何时被赋值？"],"tag":"通用/华为"},{"q":"make_shared 有什么优点和隐患？什么时候反而要用 shared_ptr(new T, deleter)？","a":"优点：① 对象与控制块一次分配（shared_ptr(new T) 是两次），减少分配次数、提升缓存局部性；② 异常安全——避免 f(shared_ptr(new T), g()) 因参数求值顺序导致 new T 已执行却未交给 shared_ptr 的泄漏。 隐患（make_shared 的代价）：对象内存与控制块合并在同一块分配里，控制块的释放条件是 strong_count==0 && we…","fu":["make_shared 与单独 new 的异常安全差异具体在哪？","为什么 weak_ptr 存在会拖住对象内存？"],"tag":"腾讯/字节"}]},{"id":"cpp-ch11","subj":"cpp","title":"异常处理与断言：try/catch、noexcept 与契约","summary":"throw/try/catch；异常安全保证（基本/强/不抛）；noexcept；标准异常体系；断言 assert 与静态断言 static_assert；RAII 与异常交互。","concepts":[{"id":"cpp-ch11/01-try-catch","file":"01-try-catch.md","title":"01 · try/catch 与栈展开：从控制流到 unwind table","kind":"stack","secs":[{"h":"一、理论根基：异常不是\"错误返回\"，而是\"控制流机制\"","s":"在 C 与早期系统编程里，错误处理靠返回码（error code）沿调用链逐层上返：if (rc != OK) return rc;。","c":null},{"h":"二、实现机制：栈展开到底发生了什么","s":"当 throw 执行时，运行时会做一件非常具体的事——栈展开（stack unwinding）：","c":null},{"h":"三、工程实践：怎么 catch 才对","s":"1. 几乎总是 catch 引用（尤其是 const std::exception&）：避免对象切片（见 pitfalls），且零拷贝。","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：亲眼看见栈展开","s":"见 examples/ex01-try-catch-multiple.json（多重捕获顺序）、examples/ex02-stack-unwinding.json（析构在展开中被调用）、examples/ex08-rethrow.js…","c":{"lang":"cpp","code":"// 摘自 examples/ex02-stack-unwinding.json 的核心逻辑\nstruct Tracer { const char* n; Tracer(const char* s):n(s){ std::cout << \"ctor \" << n << '\\n'; }\n                     ~Tracer(){ std::cout << \"dtor \" << n << '\\n'; } };\nvoid f() { Tracer b(\"b\"); throw 42; }      // b 尚未离开作用域\nint main() {\n    try { Tracer a(\"a\"); f(); }\n    catch (int v) { std::cout << \"caught \" << v << '\\n'; }\n}"}}]},{"id":"cpp-ch11/02-exception-safety","file":"02-exception-safety.md","title":"02 · 异常安全保证：基本 / 强 / 不抛 与 RAII","kind":"flow","secs":[{"h":"一、理论根基：异常安全的\"契约\"","s":"异常安全的讨论对象不是\"会不会抛异常\"，而是——当异常发生时，程序处于什么状态？ 1996 年 Herb Sutter 与 Bjarne Stroustrup 等将保证形式化为三档（另有一档\"不抛\"作为最强约定）：","c":null},{"h":"二、实现机制：RAII 是\"基本保证\"的物理实现","s":"但 RAII 只解决\"资源不泄漏\"（基本保证）。要拿到强保证，还需要 copy-and-swap / 先做再提交 这类\"先把新状态在临时对象上建好，最后用不抛的交换落地\"的惯用法：","c":{"lang":"cpp","code":"void process() {\n    std::unique_ptr<Big> p = std::make_unique<Big>(); // RAII：无论怎样退出都释放\n    std::lock_guard<std::mutex> lk(m);                 // RAII：离开作用域自动解锁\n    maybe_throw();                                     // 抛了也不泄漏内存/锁\n}"}},{"h":"三、实现机制：不抛保证与 move / noexcept 的联动","s":"","c":null},{"h":"四、工程实践：在真实项目里给保证","s":"1. 默认目标：至少基本保证。用 RAII 容器/智能指针管理一切资源，你就已经达成基本保证。","c":null},{"h":"五、边界与陷阱","s":"","c":null},{"h":"六、可运行示例","s":"见 examples/ex03-raii-exception-safety.json：在 try 中构造 RAII 对象、抛异常，证明资源（析构）依然被释放。","c":{"lang":"text","code":"open\nwork\nclose      ← 异常后析构仍被调用：基本保证（资源不泄漏）\nhandled: fail"}}]},{"id":"cpp-ch11/03-noexcept-assert","file":"03-noexcept-assert.md","title":"03 · noexcept、断言与契约：把\"承诺\"写进类型与编译期","kind":"compare","secs":[{"h":"一、理论根基：noexcept 不是优化提示，而是一份\"契约\"","s":"noexcept 同时出现在函数声明和运算符/类型特性两个层面，但它的本质是对调用者的承诺：","c":null},{"h":"二、实现机制：noexcept 如何改变 std::vector 的\"移动 vs 拷贝\"","s":"这是 noexcept 最经典、最该背下来的工程影响：","c":null},{"h":"三、实现机制：noexcept 函数的\"违约\"代价","s":"若 noexcept 函数内部还是抛了（包括它调用的函数抛且未捕获），运行时会调用 std::terminate——直接结束进程，不展开、不运行后续析构。这既是\"承诺的强制\"，也是把\"不可能发生的事\"变成\"一旦发生了就立刻崩，便于定位\"…","c":null},{"h":"四、断言：assert / static_assert / 契约（contracts）","s":"断言是另一种\"契约\"，但它处理的是前条件/不变量，与异常互补：","c":null},{"h":"五、边界与陷阱（详见 pitfalls.md）","s":"","c":null},{"h":"六、可运行示例","s":"见：","c":null}]},{"id":"cpp-ch11/04-exception-practical-recipes","file":"04-exception-practical-recipes.md","title":"§4 cpp-ch11 实战手记：凯喵带你把异常用「崩」","kind":"flow","secs":[{"h":"现场一：异常对象用 throw new MyErr() 抛指针","s":"凯喵 throw new MyErr(); 后必须 catch (MyErr) 且调用方负责 delete，极易泄漏，且与标准体系（catch (const std::exception&)）不兼容。正确：抛值或引用指向的栈对象，如 t…","c":{"lang":"cpp","code":"// ❌ 抛指针，谁 delete？\nthrow new std::runtime_error(\"x\");\n// ✅ 抛值，catch 用 const 引用\nthrow std::runtime_error(\"x\");\ncatch (const std::runtime_error& e) { }"}},{"h":"现场二：catch 按值接，对象被 slicing","s":"凯喵 catch (std::exception e) 按值接，派生类特有的信息在拷贝时被「切片」丢掉。一律用 catch (const std::exception& e) 引用接，保留动态类型和多态。","c":{"lang":"cpp","code":"try { throw Derived(); }\ncatch (const Base& e) { e.what(); }   // ✅ 引用保留派生类型\n// catch (Base e) { }                  // ❌ 切片，丢失派生信息"}},{"h":"现场三：catch 顺序写反，窄的永远进不去","s":"凯喵先 catch (std::exception) 再 catch (std::runtime_error)，后者成了死代码——基类在前会把派生类一并接走。catch 必须从最派生到最基类排，否则派生分支永远触发不到。","c":{"lang":"cpp","code":"try { /* ... */ }\ncatch (const std::runtime_error& e) { }  // ✅ 先窄\ncatch (const std::exception& e) { }      // ✅ 再宽"}},{"h":"现场四：在析构函数里抛异常，程序直接 terminate","s":"凯喵在析构函数里 throw，结果栈展开途中又抛异常，C++ 标准规定此时直接 std::terminate，进程崩溃。析构函数要么吞掉异常（捕获后记日志），要么标 noexcept(false) 但绝对不在栈展开时抛。","c":{"lang":"cpp","code":"~Guard() {\n    try { cleanup(); }\n    catch (...) { /* 记录日志，绝不向外抛 */ }\n}"}},{"h":"现场五：没用 RAII，异常跳过释放导致泄漏","s":"凯喵 lock(); do_work(); unlock();，do_work() 一抛异常，unlock() 被跳过，锁永远不释放。资源获取即初始化（RAII）：把资源放进对象，构造拿、析构放，异常安全自动清理。","c":{"lang":"cpp","code":"struct LockGuard {\n    LockGuard(Mutex& m): m_(m) { m_.lock(); }\n    ~LockGuard() { m_.unlock(); }   // ✅ 异常也释放\n    Mutex& m_;\n};"}},{"h":"现场六：noexcept 函数里抛异常，直接 terminate","s":"凯喵给函数标了 noexcept 却在里面 throw，一旦抛出直接 terminate。noexcept 是承诺「绝不抛」，移动构造/移动赋值标了它 STL 才敢用移动优化；不确定就别标，或确保内部不抛。","c":{"lang":"cpp","code":"void f() noexcept { throw 1; }   // ❌ 抛即 terminate\nvoid g() { throw 1; }            // ✅ 不标 noexcept"}},{"h":"现场七：用 assert 做运行期参数校验，release 下失效","s":"凯喵 assert(ptr != nullptr); 当参数校验，结果 release 编译（NDEBUG）后 assert 整段消失，空指针一路裸奔。assert 只查内部不变式；对外参数校验用显式 if (!p) throw。","c":{"lang":"cpp","code":"assert(invariant_holds());        // ✅ 内部不变式，release 可被优化掉\nif (user_ptr == nullptr) throw std::invalid_argument(\"null\");  // ✅ 运行期校验"}},{"h":"现场八：catch (...) 吞掉一切却不知啥错","s":"凯喵 catch (...) { return -1; } 把异常吃了，排错时完全不知道发生了什么。至少打印/记录，或重新抛出（throw;）交给上层；别静默吞。","c":{"lang":"cpp","code":"catch (...) {\n    log(\"unknown error\");   // ✅ 至少留痕\n    throw;                  // 或重新抛给上层\n}"}},{"h":"现场九：在构造函数里抛异常，对象部分构造难清理","s":"凯喵构造函数里中途抛异常，已分配的资源没释放（因为析构不会被调——对象没构造成功）。构造函数要么成功要么抛，资源分配用 RAII 成员（成员析构会自动清理已构造的部分）。","c":{"lang":"cpp","code":"struct Widget {\n    std::unique_ptr<Res> a = std::make_unique<Res>();  // ✅ 成员 RAII，异常时自动释放\n    Widget() { maybe_throw(); }\n};"}},{"h":"现场十：异常说明（dynamic exception specification）已废弃","s":"凯喵写 void f() throw(int); 想声明只抛 int，这是 C++11 起已移除的特性，现代应改用 noexcept 或什么都不写。动态异常规格既难用又会因不符而意外 terminate。","c":{"lang":"cpp","code":"void f() noexcept;   // ✅ 现代写法\n// void f() throw(int);  // ❌ 已废弃"}},{"h":"现场十一：跨 ABI / 跨语言边界抛异常，直接崩","s":"凯喵从 C 接口回调里抛 C++ 异常，或动态库边界抛自定义类型，对方无法 catch，栈损坏。异常不要跨 ABI / C 边界；接口层捕获后转错误码返回。","c":{"lang":"cpp","code":"extern \"C\" int api() {\n    try { do_cpp(); return 0; }\n    catch (...) { return -1; }   // ✅ 边界内消化，转错误码\n}"}},{"h":"现场十二：异常成本高就全盘禁用，反而更难维护","s":"凯喵因「异常慢」在全局禁用异常，结果错误码层层 return 检查，漏一处就静默失败。异常在不抛的路径几乎免费，只在抛出时贵。用异常表达真正「意外」，普通错误仍可用 std::optional / 错误码。","c":{"lang":"cpp","code":"// 意外失败用异常\nif (!open_file()) throw std::runtime_error(\"open failed\");\n// 可预期的空结果用 optional\nstd::optional<int> find(int k);"}},{"h":"现场之外：凯喵的异常五条军规","s":"写 C++ 异常处理，凯喵给自己立了五条军规。第一，抛值接引用：throw 栈对象，catch 用 const 引用，既避免指针泄漏又避免值拷贝的 slicing。第二，析构函数绝对不向外抛，栈展开途中再抛就是 terminate，有风…","c":null},{"h":"现场拾遗：异常不是用来吞的","s":"再补一句心态：异常存在的意义是让程序在「做不到」的时候诚实地停下来，而不是悄悄带着错误继续跑。新人最容易犯的错是 catch 之后什么都不做，或者只打一行日志就继续，结果错误被埋进调用链的更深处，最后在完全不相干的地方炸出来，排查时一头…","c":null},{"h":"一句话收尾","s":"凯喵最后提醒：C++ 给了你四种错误处理路径——异常、错误码、optional、断言——不是为了让你随便挑，而是让你按「这件事是不是意外」来选。真正意外、上层才能决定怎么处理的用异常；可预期、调用方应当检查结果的用 optional 或…","c":null},{"h":"🧑‍💻 程序员视角","s":"throw new MyErr() 抛的是指针，捕获方必须 delete，一旦中途再次抛出就泄漏——标准做法是抛值、按 const& 捕获。按值捕获会切片：catch (Base e) 把派生异常切成基类，丢失派生信息。catch 顺序…","c":null},{"h":"🎓 博士生视角","s":"异常机制依赖「栈展开」（stack unwinding）：抛出后沿调用栈逐层销毁局部对象（调用析构），直到匹配的 catch。这带来两个约束：析构函数不能抛（否则展开中再抛导致 terminate）、异常安全需要 RAII 保证（资源在…","c":null},{"h":"📚 考研者视角","s":"面试常考：","c":null}]}],"exams":[{"kind":"choice","q":"关于栈展开（stack unwinding），正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"异常发生时，只有抛异常的那个函数里的对象会被析构"},{"k":"B","t":"栈展开期间，从 throw 点到 catch 之间沿途的局部对象按其构造逆序被析构"},{"k":"C","t":"try 块本身在运行时会产生异常检测指令，因此有性能开销"},{"k":"D","t":"catch 子句按派生类在前、基类在后的顺序匹配，与书写顺序无关"}],"ans":"B","why":"栈展开从 throw 点逐帧向上，逆序析构沿途局部对象（RAII 异常安全的基础）。异常路径才有成本，正常路径无异常检测指令（零开销原则）；catch 匹配按书写顺序取第一个可转换的子句，故派生类应写在基类前。"},{"kind":"fix_error","q":"修复 catch 顺序错误与按值切片","stem":"以下代码意图捕获运行时错误，但有两处问题：① catch 顺序写反，② 按值捕获导致切片。请修复： cpp try { throw std::runtime_error(\"x\"); } catch (std::exception e) { std::cout << e.what() << '\\n'; } // 问题①按值 ②基类在前 catch (std::runtime_error e) { s…","opts":[],"ans":"try { throw std::runtime_error(\"x\"); } catch (const std::runtime_error& e) { std::cout << \"rt: \" << e.what() << '\\n'; } catch (const std::exception& e) { std::c…","why":"派生类 catch 必须写在基类之前（否则被基类吃掉）；用 const 引用捕获避免切片并保留动态类型与零拷贝。"},{"kind":"output","q":"读代码写输出（catch 顺序与引用）","stem":"cpp #include <iostream> #include <stdexcept> struct E : std::runtime_error { E():std::runtime_error(\"E\"){} }; int main() { try { throw E(); } catch (const std::runtime_error& e) { std::cout << e.what(…","opts":[],"ans":"E end","why":"抛出的 E 对象先匹配到第一个可转换的 const std::runtime_error&，于是打印 E 并结束；第二个 catch(E&) 因已匹配而不可达。注意 0 结束的 what() 字符串打印出 \"E\"。"},{"kind":"explain","q":"解释异常安全三保证（基本 / 强 / 不抛）","stem":"简述异常安全的三个保证级别分别承诺什么，并指出 RAII 与 copy-and-swap 各自对应/实现哪一级。","opts":[],"ans":"基本保证：不泄漏资源、对象保持有效且不变式不破坏，但具体值可能变。强保证：要么成功要么完全回滚（commit-or-rollback，类似事务）。不抛保证（nothrow/noexcept）：函数绝不抛异常。RAII 通过析构确定性释放资源，天然提供基本保证；copy-and-swap / move-and-swap…","why":"等级：不抛 ⊃ 强 ⊃ 基本。RAII 给基本保证；强保证靠「先构造临时、再 noexcept swap 提交」；函数整体等级等于最弱操作的等级。"},{"kind":"coding","q":"实现 noexcept 移动构造与移动赋值","stem":"给定管理 int 缓冲的类 Buf，请实现不抛的移动构造与移动赋值（使用 noexcept），使该类型能被 std::vector 在扩容时高效移动而非拷贝。已给出析构。","opts":[],"ans":"class Buf { int p_ = nullptr; size_t n_ = 0; public: ~Buf() { delete[] p_; } Buf(Buf&& o) noexcept : p_(o.p_), n_(o.n_) { o.p_ = nullptr; o.n_ = 0; } // 窃取并置空源…","why":"移动构造/赋值标记为 noexcept 是关键：std::vector 仅在元素移动为 noexcept 时才在扩容时移动，否则退化为拷贝。移动后源对象须保持可析构（置空 p_）。"},{"kind":"design","q":"实现强异常安全的 push_back（copy-and-swap）","stem":"设计一个动态数组 Vec，其 push_back 在扩容失败时保持原对象不变（强保证）。请用 copy-and-swap / 先建副本再不抛交换 的思路给出核心实现，并说明为何要先把新缓冲建好再提交。","opts":[],"ans":"void push_back(const T& v) { if (size_ == cap_) { size_t nc = cap_ ? cap_ 2 : 1; auto np = std::make_unique<T[]>(nc); // 先建新缓冲（可能抛，但只影响 np） for (size_t i = 0; i…","why":"「先分配新缓冲并拷贝，最后用 noexcept 的 unique_ptr 移动替换」保证：若任何一步抛异常，原 data_ 与 size_ 完全没动 → 强保证（回滚）。这正是标准容器 push_back 的强保证实现思路。"},{"kind":"coding","q":"用 RAII 把会泄漏的裸指针代码改写为异常安全","stem":"下面代码在 use() 抛异常时会泄漏 p。请用 RAII（自定义 Guard 或 std::unique_ptr）改写，使无论正常还是异常退出都释放资源。","opts":[],"ans":"#include <memory> void f() { auto p = std::make_unique<int>(42); // RAII：离开作用域必释放 use(p); // 若 use 抛异常，p 的析构仍运行 }","why":"裸指针 + 手动 delete 在异常路径下极易泄漏；交给 unique_ptr/作用域 Guard 后，析构的确定性调用（基本保证）自动覆盖异常路径。"}],"works":[{"h":"在析构函数里抛异常 —— 可能导致 std::terminate","d":"若析构在栈展开期间被调用（即已有一个异常正在传播），此时析构再抛异常，运行时会立即 std::terminate。即使不在展开期，析构抛异常也会让调用方被迫处理\"清理失败\"，非常危险。 析构函数一律标 noexcept（默认即如此），内部任何可能失败的操作要吞掉并记录日志，绝不向外 throw。"},{"h":"catch 按值捕获导致切片（slicing）","d":"catch (std::exception e) 会把派生异常对象按基类值拷贝，派生部分被切掉，e.what() 可能丢失派生类的重写，甚至行为变化。 永远 catch (const std::exception& e)（引用捕获，零拷贝、保留动态类型）。"},{"h":"catch(...) 或空 catch 静默吞掉异常","d":"cpp try { risky(); } catch (...) {} // 异常消失了，问题被掩盖，事后极难排查 至少要记录日志再决定；若确实要忽略，写明注释说明\"此异常已知且安全\"。更常见的是捕获后做清理再 throw; 重抛。"},{"h":"noexcept 函数内仍抛异常 → 直接 std::terminate","d":"标了 noexcept 是给编译器的契约：一旦内部 throw（含调用了会抛的函数且未捕获），进程直接终止，不会展开恢复。 cpp void boom() noexcept { throw 1; } // 调用即 terminate！ 只在\"确实绝不抛\"时标 noexcept；标准库特殊成员函数在满足条件时自动 noexcept，勿破…"},{"h":"异常穿越 C 接口 / extern \"C\" / 跨模块边界","d":"C 函数（如 qsort 的比较回调、pthread 的入口）不知道 C++ 异常；异常从 C 帧\"漏过去\"会绕过 C++ 栈展开，导致对象不析构、资源泄漏，甚至直接 std::terminate。 在调用 C 接口前捕获所有异常并转为错误码/返回状态；跨 .so/.dll 抛异常也要谨慎（不同模块可能用不同 unwind 运行时）。"},{"h":"catch 顺序写反：基类在前、派生类在后","d":"匹配按第一个可转换的子句进行；基类写在前面会把所有派生异常\"吃掉\"。 cpp catch (const std::exception&) { ... } // 写在前面 catch (const std::runtime_error&) { ... } // 永远到不了！ 派生类 catch 必须写在基类 catch 之前。"},{"h":"用 assert 代替错误处理（Release 下失效）","d":"assert(p != nullptr) 在定义 NDEBUG（Release）后被整体删除，等于没有任何检查；若 p 真为空，Release 下直接 UB。 用户/外部可触发的错误用异常或错误码处理；assert 只用于\"开发期捕捉本不该发生的程序员错误\"。"},{"h":"异常对象用 throw new MyErr()（抛指针）","d":"抛指针后必须 catch (MyErr) 且调用方负责 delete，极易泄漏，且与标准体系（catch (const std::exception&)）不兼容。 抛值或引用指向的栈对象（如 throw std::runtime_error(\"...\")），catch 用 const 引用接。"}],"asks":[{"q":"C++ 异常的「零开销原则（zero-overhead principle）」到底指什么？它真的不开销吗？","a":"准确说法是「不为不使用的功能付费，且尽量不为使用的功能付出额外代价」。具体到异常： 1. 正常（不抛）路径零运行期开销：基于表的异常处理（unwind table）让 try 块在 -O2 下几乎不产生任何异常检测指令；开销被转移到了代码体积（每个函数要生成展开表）和编译/链接复杂度上，而不是运行期指令。 2. 异常路径确实有成本：throw 触发时要查 unwind table、逐帧展开、调用析…","fu":["那为什么有些嵌入式/游戏项目用 -fno-exceptions 关掉异常？","异常和错误码在热路径上的性能差异主要来源是什么？"],"tag":"通用/字节"},{"q":"为什么析构函数不应该抛异常？如果必须在析构里做可能失败的事怎么办？","a":"核心原因有两个： 1. 栈展开期间若析构再抛，直接 std::terminate。当已有异常在传播、运行时会逐帧调用析构来清理；若某个析构又抛异常且没被接住，程序无法决定「恢复哪个」，标准规定立即终止。 2. 破坏 RAII 与强保证：析构是资源释放的兜底，抛异常会让调用方被迫处理「清理失败」，语义混乱。 实践上： - 析构函数默认就是 noexcept，内部任何可能失败的操作都要吞掉（try/c…","fu":["std::vector 的析构会抛异常吗？为什么？","C++11 起析构默认 noexcept，这带来什么约束？"],"tag":"通用/美团"},{"q":"noexcept 有什么用？为什么移动构造函数几乎总是要标 noexcept？","a":"noexcept 是函数对调用者的契约：我绝不抛异常；若我内部还是抛了，进程直接 std::terminate。它的实际作用： 1. 让编译器/标准库做优化与决策。最经典的例子是 std::vector 扩容：它优先用移动把旧元素搬到新缓冲，但只有元素的移动构造是 noexcept 时才敢用移动——因为移动若中途抛异常，旧缓冲已部分搬空、无法回滚，强保证（commit-or-rollback）会被…","fu":["把 noexcept 函数改成可能抛，为什么是破坏性 API 变更？","怎么用 noexcept 运算符在模板里做分支（if constexpr）？"],"tag":"通用/谷歌"},{"q":"C++ 异常与 Rust 的 Result / 错误码相比，各自的取舍是什么？","a":"三种范式的核心权衡： - 错误码（C / 返回 std::error_code）：零隐式开销、调用点显式、易漏判；跨函数传播冗长（层层 if (rc) return rc）。适合系统编程、热路径。 - C++ 异常：错误传播自动、与返回值解耦、强保证靠 RAII 易实现；但异常路径贵、二进制体积增大、控制流隐式难追踪，且跨 ABI / 析构有坑。 - Rust Result<T, E>：把错误类型…","fu":["std::expected 是什么？它和异常的关系？","什么时候该用异常、什么时候该用错误码？"],"tag":"通用/字节"}]},{"id":"cpp-ch12","subj":"cpp","title":"现代 C++ 特性：auto/移动语义/范围 for/emplace","summary":"auto 与 decltype；右值引用与移动语义；std::move/forward；emplace 避免拷贝；结构化绑定；if constexpr；折叠表达式。","concepts":[{"id":"cpp-ch12/01-auto-deduction","file":"01-auto-deduction.md","title":"01 · auto 的类型推导规则（与模板推导一致）","kind":"flow","secs":[{"h":"一、理论根基：为什么 auto 的推导规则就是模板推导规则","s":"C++11 引入 auto 作为「类型占位符」：编译器在初始化时根据 = 右侧的表达式推导出类型。","c":{"lang":"cpp","code":"auto x = expr;      // 等价于把 expr 作为实参传给模板 void f(T param); 推导 T\nauto& y = expr;     // 等价于模板 void f(T& param);"}},{"h":"二、实现机制：auto / auto& / const auto& / decltype(a…","s":"","c":{"lang":"cpp","code":"int   n = 0;\nint&  r = n;\nconst int c = 1;\n\nauto a = r;          // a 是 int（引用被丢掉，得到副本）\nauto b = c;          // b 是 int（顶层 const 被丢掉）\nauto& br = r;        // br 是 int&（保留）"}},{"h":"三、工程实践：什么时候该/不该用 auto","s":"","c":null},{"h":"四、边界与陷阱","s":"1. auto 在列表初始化时会推导成 std::initializer_list（C++11）：","c":null},{"h":"五、可运行示例（见 examples/ex01.json、ex02.json、ex03.js…","s":"","c":null}]},{"id":"cpp-ch12/02-move-semantics","file":"02-move-semantics.md","title":"02 · 移动语义的本质：值类别、右值引用与 std::move","kind":"flow","secs":[{"h":"一、理论根基：为什么要「移动」","s":"拷贝大对象（长字符串、大 vector）代价高。很多场景下，源对象在「交出资源」后就不再被使用——例如函数返回一个局部 vector、把一个临时对象存进容器。移动语义让这种场景从「深拷贝整块资源」变成「把指针/句柄从源偷给目标」，代价是…","c":null},{"h":"二、值类别（Value Categories）：理解移动的前提","s":"C++11 把表达式按「是否拥有身份（identity）」与「是否可被移动」分为三类：","c":{"lang":"text","code":"        可移动(move) ──┐\n                       │\n   lvalue ──── xvalue ─┤── 泛左值 glvalue（有身份）\n                       │\n   prvalue ───────────┘\n\n  lvalue  : 有身份、通常不可移动（如变量名、*p、++i 的结果）\n  prvalue  : 无身份、可移动（如 42、T() 临时量、a+b 的结果）—— 纯右值\n  xvalue  : 有身份、但可被移动（eXpiring value，如 std::move(x) 的结果）—— 将亡值"}},{"h":"三、实现机制：std::move 只是一次无条件 cast","s":"std::move(x) 不做任何运行期动作，它只是把 x 无条件转换为右值引用（static_cast<T&&>），告诉编译器「我允许你移动它」。真正的资源转移发生在移动构造函数 / 移动赋值运算符里。","c":{"lang":"cpp","code":"template<class T>\nconstexpr remove_reference_t<T>&& move(T&& arg) noexcept {\n    return static_cast<remove_reference_t<T>&&>(arg);   // 仅类型转换，零开销\n}"}},{"h":"四、实现机制：为什么移动构造要标 noexcept","s":"std::vector 在 push_back 触发扩容时，需要把旧元素搬到新内存。搬完之后旧内存要释放——若移动过程中抛异常，标准库必须保证「强异常安全」：要么全部成功，要么原状。","c":{"lang":"cpp","code":"Buffer(Buffer&& o) noexcept : p(o.p) { o.p = nullptr; }   // noexcept 让 vector 扩容走移动"}},{"h":"五、工程实践","s":"","c":null},{"h":"六、边界与陷阱","s":"1. std::move 不移动任何东西，只是 cast；实体移动在构造/赋值里发生。","c":null},{"h":"七、可运行示例（见 examples/ex04.json、ex05.json）","s":"","c":null}]},{"id":"cpp-ch12/03-range-for-and-emplace","file":"03-range-for-and-emplace.md","title":"03 · 范围 for 与 emplace：遍历、迭代器失效与原地构造","kind":"compare","secs":[{"h":"一、范围 for 的展开（编译器到底做了什么）","s":"for (auto x : range) 不是新语法糖的魔法，标准规定它等价于如下迭代器循环（[stmt.ranged]）：","c":{"lang":"cpp","code":"{\n    auto && __range = range;                 // 绑定整个 range（延长临时生命）\n    for (auto __begin = begin(__range),\n              __end   = end(__range);        // 只求值一次！__end 在循环外固定\n         __begin != __end; ++__begin) {\n        auto x = *__begin;                   // 每次解引用，按值拷贝给 x\n        // 循环体\n    }\n}"}},{"h":"二、迭代器失效（范围 for 的致命陷阱）","s":"范围 for 本质是「begin…end 的迭代器遍历」。对 vector/string/deque：","c":{"lang":"cpp","code":"for (auto& x : v) {\n    if (x == 0) v.erase(...);   // ❌ 迭代器失效，UB\n}"}},{"h":"三、emplace_back vs push_back：构造次数差异","s":"push_back 的参数是一个已构造好的元素（左值或右值）：","c":{"lang":"text","code":"push_back(临时):   [调用处构造临时] --> (移动/拷贝) --> [容器内存]\nemplace_back(args):                     [容器内存中原地构造]   ← 少一次移动/拷贝"}},{"h":"四、转发引用参数的陷阱（emplace/make_unique 的坑）","s":"emplace_back 的参数类型是转发引用（forwarding reference） T&&... args，内部用 std::forward<Args>(args)... 完美转发。陷阱：","c":null},{"h":"五、工程实践","s":"","c":null},{"h":"六、可运行示例（见 examples/ex06.json、ex07.json、ex08.js…","s":"","c":null}]},{"id":"cpp-ch12/04-structured-binding-optional-stringview","file":"04-structured-binding-optional-stringview.md","title":"04 · 结构化绑定、std::optional 与 std::string_view","kind":"flow","secs":[{"h":"一、结构化绑定（Structured Bindings，C++17）","s":"语法 auto [a, b, c] = e; 把 e 的「成员/元素」绑定到一组名字上。可用于：","c":{"lang":"cpp","code":"std::map<int, std::string> m{{1,\"one\"},{2,\"two\"}};\nfor (const auto& [key, val] : m) { /* key、val 是引用别名 */ }"}},{"h":"二、std::optional<T>：可能有也可能没有的值","s":"表示一个「可能为空」的值，比「用特殊哨兵值（如 -1、nullptr）」更安全、更自文档化：","c":{"lang":"cpp","code":"std::optional<int> find_even(int n) {\n    if (n % 2 == 0) return n;     // 隐式构造 optional（有值）\n    return std::nullopt;          // 明确表示「无值」\n}\nif (auto r = find_even(4); r) std::cout << *r;   // 用 bool 转换判断，用 * 取值"}},{"h":"三、std::string_view：零拷贝字符串视图","s":"std::string_view 只是 {const char ptr, size_t len} 两个字的非拥有视图，不分配内存、不拷贝字符：","c":{"lang":"cpp","code":"std::string_view sv = \"hello\";\nauto sub = sv.substr(0, 3);   // O(1)：只调指针与长度，不拷贝 \"hel\""}},{"h":"四、工程实践小结","s":"","c":null},{"h":"五、可运行示例（见 examples/ex09.json、ex10.json）","s":"","c":null}]},{"id":"cpp-ch12/05-modern-cpp-practical-recipes","file":"05-modern-cpp-practical-recipes.md","title":"凯喵实战手记 · 现代 C++ 的「性能与陷阱」","kind":"flow","secs":[{"h":"现场 1：auto 推论出引用还是值？","s":"auto 永远按值拷贝（除非你显式加 &）。凯喵规矩：遍历大容器用 const auto& 或 auto&，只读别拷贝；需要修改元素用 auto&；否则一个 auto 默默拷贝了整个大对象。","c":{"lang":"cpp","code":"std::vector<int> v{1,2,3};\nauto x = v[0];      // int，拷贝\nauto& y = v[0];     // int&，引用原元素\nconst auto& z = v;  // const vector&，避免拷贝大对象"}},{"h":"现场 2：返回值误用 std::move 抑制 RVO","s":"命名返回值优化（NRVO）在有名局部对象上直接原地构造，比移动还快。凯喵：直接 return v;，让编译器自己优化；std::move 只在「返回值本身不会再被使用」且是函数参数/成员时才用。","c":{"lang":"cpp","code":"std::vector<int> make() {\n    std::vector<int> v(1000);\n    return std::move(v); // 反模式！阻止 NRVO，还多一次移动\n}"}},{"h":"现场 3：std::string_view 悬垂","s":"view 不拥有数据，指向临时 string 立刻失效。凯喵：view 适合做「函数参数/局部切片」，绝不跨函数边界返回指向局部/临时的 view。要返回就返回 string。","c":{"lang":"cpp","code":"auto f() { std::string s = \"hi\"; return std::string_view(s); } // 返回悬垂 view"}},{"h":"现场 4：emplace_back 比 push_back 少一次拷贝","s":"emplace_back(args...) 把参数完美转发给元素构造器。凯喵：能 emplace 就 emplace，尤其是不可/难移动的重对象，省一次构造。但注意 emplace 不会替换 push_back(T&&) 的移动语义优势…","c":{"lang":"cpp","code":"std::vector<std::string> v;\nv.push_back(std::string(\"x\")); // 构造临时 + 移动\nv.emplace_back(\"x\");           // 直接在容器内存里构造，零临时"}},{"h":"现场 5：范围 for 里的 auto& 与 auto","s":"想修改元素必须 auto&。凯喵：只读大对象 const auto&，要改 auto&，小值类型（int）auto 也无妨。","c":{"lang":"cpp","code":"for (auto x : vec) x = 0;        // 改的是副本，原 vec 没变\nfor (auto& x : vec) x = 0;       // 改的是引用，原 vec 变了"}},{"h":"现场 6：auto&& 的误解","s":"auto&& 是「转发引用」，能接左值也能接右值，常用于泛型 for (auto&& x : range) 保留元素值类别。但新手常以为它「总是右值引用」——其实对左值它推导出左值引用。凯喵：模板/泛型里用 auto&& 接值最通用，普…","c":null},{"h":"现场 7：emplace 的歧义与 initializer_list","s":"emplace 会把花括号当作「转发给构造器」的参数，有时意外命中 initializer_list 构造。凯喵：遇到诡异行为，显式构造再传，别迷信 emplace 万能。","c":{"lang":"cpp","code":"std::vector<std::vector<int>> v;\nv.push_back({1,2});    // OK\nv.emplace_back({1,2}); // 可能匹配 initializer_list 重载，行为不同"}},{"h":"现场 8：结构化绑定解包 tuple / pair","s":"结构化绑定让多返回值可读性大增。凯喵：绑定到 auto& 可修改原 tuple 元素；注意绑定的是「引用别名」，对 const 成员要 const auto&。","c":{"lang":"cpp","code":"auto [ok, value] = tryParse(s); // ok:bool, value:int\nif (ok) use(value);"}},{"h":"现场 9：std::optional 替代「哨兵值」","s":"用 optional 表达「可能有值」，比返回 -1/nullptr 哨兵清晰且类型安全。凯喵：别再用魔法数表示「没找到」，optional 让调用方被迫处理空情况。","c":{"lang":"cpp","code":"std::optional<int> findId(const std::string& name); // 找不到返回 nullopt\nif (auto id = findId(\"kai\"); id) use(*id);"}},{"h":"现场 10：移动后对象处于「有效但未指定状态」","s":"标准只保证移动后对象可安全析构/赋值，不保证是空。凯喵：移动后别读 a 的内容，把它当成「待重新初始化」的壳。","c":{"lang":"cpp","code":"std::string a = \"hello\";\nstd::string b = std::move(a);\n// a 现在合法但内容不确定，只能赋值/析构，不能假设为空"}},{"h":"现场 11：std::move 只是类型转换，不真移动","s":"std::move(x) 本身不做任何移动，只是把 x 变成右值引用，真正的移动发生在接收端的移动构造/赋值里。凯喵：看到 move 要想到「下一步必须有能吃掉右值的操作」，否则它啥也没干。","c":null},{"h":"现场 12：emplace 在 map/set 里更香","s":"关联容器的 emplace/try_emplace 避免先构造再拷贝/移动 value。凯喵：C++17 的 try_emplace 还能避免键已存在时白构造值对象，是首选。","c":{"lang":"cpp","code":"std::map<int, Big> m;\nm.emplace(1, Big{...}); // 直接在表里构造 pair<Key,Big>"}},{"h":"凯喵复盘：性能优化的第一原则——先确认它真的更快","s":"现代 C++ 给了一堆「看起来更快」的写法，但凯喵见过太多人机械地把 push_back 全换成 emplace_back、把每个返回值都 std::move，结果性能没提升、Bug 反而多了。真相是：这些特性只有在「确实避免了一次拷贝…","c":null},{"h":"凯喵速记：现代 C++ 的三条红线","s":"只记三句也能避掉大部分坑：第一，看到 auto 想「它是按值拷贝还是引用」，大对象只读就 const auto&；第二，看到 std::move/emplace 想「到底省了哪次拷贝」，别为了写而写，尤其 return std::mov…","c":null},{"h":"🧑‍💻 程序员视角","s":"return std::move(x) 是典型的「帮忙帮倒忙」：它把返回值变成右值引用，抑制了 NRVO（具名返回值优化），反而多一次移动。string_view 不拥有内存，指向临时 string 时立刻悬垂——它的正确用法是「函数参…","c":null},{"h":"🎓 博士生视角","s":"C++11 之后的核心变化是「值类别」成为一等公民：左值/右值/将亡值的区分让移动语义与完美转发成为可能。std::move 本身不移动，只是把左值转成右值引用；真正的移动发生在移动构造/赋值里。RVO 与 NRVO 是编译器的「复制消…","c":null},{"h":"📚 考研者视角","s":"面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"auto 推导会保留什么","stem":"对于 int n = 0; int& r = n; const int c = 1;，下列哪项正确？ A. auto a = r; 之后 a 是 int& B. auto b = c; 之后 b 是 const int C. auto& x = r; 之后 x 是 int&（引用被保留） D. decltype(auto) y = r; 会丢失引用、得到 int 副本","opts":[{"k":"A","t":"auto a = r; 之后 a 是 int&"},{"k":"B","t":"auto b = c; 之后 b 是 const int"},{"k":"C","t":"auto& x = r; 之后 x 是 int&（引用被保留）"},{"k":"D","t":"decltype(auto) y = r; 会丢失引用、得到 int 副本"}],"ans":"C","why":"auto 按值推导会丢弃引用与顶层 const，所以 a/b 都是 int；auto& 保留引用，x 是 int&；decltype(auto) 用 decltype 规则，会完整保留引用（y 是 int&）。见 concept/01 与 ex02、ex03。"},{"kind":"fix_error","q":"修复 auto 导致的意外拷贝","stem":"下面代码意图「通过 g 修改全局的 conf 向量」，但 g 只改了副本。请改正（保留原语义，让 g 真实引用 conf）： cpp std::vector<int> conf = {1, 2, 3}; void g() { auto x = conf; // 拿到了副本 x.push_back(99); }","opts":[],"ans":"void g() { auto& x = conf; // 改成引用，绑定到 conf 本身 x.push_back(99); // 现在会修改 conf }","why":"auto 按值推导得到 vector 的副本，push_back 只改副本。改成 auto&（或 vector<int>&）即可让其成为 conf 的别名。这是 auto 丢失引用的典型坑（见 pitfalls #1、ex02）。"},{"kind":"output","q":"移动构造 noexcept 对 vector 扩容的影响","stem":"容器 M 的移动构造标了 noexcept，容器 C 的移动构造未标 noexcept。各自 reserve(1) 后依次 push_back(M(1..3)) 与 push_back(C(1..3))。扩容重分配时分别发生什么？请选择最贴切的描述。 A. 两者都走拷贝，因为 push_back 永远优先拷贝 B. M 走移动、C 退化拷贝（M 的 noexcept 让 vector 敢移动） C…","opts":[{"k":"A","t":"两者都走拷贝"},{"k":"B","t":"M 走移动、C 退化拷贝（noexcept 决定）"},{"k":"C","t":"两者都走移动"},{"k":"D","t":"C 走移动、M 退化拷贝"}],"ans":"B","why":"vector 扩容需保证强异常安全：只有移动构造 noexcept 才敢用移动，否则回退拷贝。因此 M 全程 move、C 退化为 copy（见 concept/02、ex05 实测输出差异巨大）。"},{"kind":"choice","q":"范围 for 中等价展开与迭代器失效","stem":"关于范围 for，哪项正确？ A. 范围 for 等价于每次判断都重新调用 end() B. for (auto& x : v) 中在循环体里调用 v.push_back(...) 总是安全的 C. 范围 for 把整个 range 绑定到 __range（auto&&），__end 只在循环前求值一次 D. 范围 for 只能用于数组，不能用于 std::vector","opts":[{"k":"A","t":"每次判断都重新调用 end()"},{"k":"B","t":"循环体里 push_back 总是安全的"},{"k":"C","t":"range 绑定到 auto&&，__end 只求值一次"},{"k":"D","t":"只能用于数组"}],"ans":"C","why":"范围 for 等价于 auto&& __range = range; for (auto b=begin,e=end; b!=e; ++b)，__end 只算一次。因此在循环内增删 vector 会令已持有的迭代器失效（UB）。删除应改用迭代器循环 + erase 返回值（见 concept/03、ex07）。"},{"kind":"coding","q":"用 emplace_back 与范围 for 统计词频","stem":"给定一个 std::vector<std::string> 的单词列表，统计每个单词出现次数（用 std::map 或 std::unordered_map），并以「word:count」逐行输出（顺序不限）。要求：遍历用范围 for，插入计数用 emplace/operator[]，避免无谓拷贝。请写出 count_words 函数。","opts":[],"ans":"#include <iostream> #include <vector> #include <string> #include <map> #include <utility> std::map<std::string, int> count_words(const std::vector<std::string>&…","why":"范围 for 用 const auto& 遍历；map::operator[] 在键不存在时原地构造（等价于 emplace），计数后返回引用自增；输出用结构化绑定 const auto& [w,c]。"},{"kind":"design","q":"LeetCode 146 · LRU 缓存","stem":"设计并实现一个满足 LRU（最近最少使用）淘汰策略的缓存，支持 O(1) 查询与更新。建议用 std::list 维护使用序 + std::unordered_map<key, list::iterator> 定位，移动/插入时利用现代 C++ 的移动语义与 emplace（题面详见 external_url，不在此复述）。","opts":[],"ans":"// 结构：list<pair<key,value>> 维护「最近使用在前」；unordered_map<key, list iterator> O(1) 定位。 // get 命中：把节点 splice 到表头（O(1) 移动，无需拷贝）；put 超容量：erase 表尾并同步删 map。 // 完整实现见 exte…","why":"核心是「哈希 O(1) 定位 + 双向链表维护冷热序」。list 的 splice 是移动节点（常数时间、不拷贝），正契合移动语义思想；用 emplace 原地构造节点减少分配。"},{"kind":"design","q":"LeetCode 380 · 常数时间插入删除随机访问","stem":"实现 RandomizedSet：支持平均 O(1) 的插入、删除、随机返回。建议用 vector 存元素 + unordered_map<value, index> 定位；删除时用「与末尾交换 + pop_back」配合移动语义，避免 O(n) 搬移（题面详见 external_url，不在此复述）。","opts":[],"ans":"// vector<T> vals 存元素，unordered_map<T,size_t> pos 记录下标。 // 删除 x：idx=pos[x]; 与 vals.back() 交换; pop_back(); 更新 pos[vals[idx]]=idx; erase pos[x]。 // 完整实现见 external…","why":"「末尾交换 + pop_back」把删除从 O(n) 降到 O(1)；交换/构造元素时利用移动语义减少拷贝。emplace_back 用于插入新元素。"}],"works":[{"h":"auto 丢失引用/const 导致意外拷贝","d":"auto a = getVec(); 拿到的是副本而非引用；若想避免大拷贝或要改原对象，应写 auto& / const auto&。decltype(auto) 才能完整保留表达式的引用与 const。 只读大对象用 const auto&，要改原对象用 auto&，转发返回值用 decltype(auto)。"},{"h":"std::move 之后继续使用源对象的值","d":"std::move(x) 只是把 x 当右值，真正的资源转移发生在移动构造/赋值里，移动后 x 处于「有效但未指定状态」。再读 x.someField() 可能得到空/垃圾。 移动后只允许「重新赋值 / 析构 / 判空」；不要依赖其值。"},{"h":"移动构造未标 noexcept 导致 vector 扩容退化成拷贝","d":"std::vector 重分配时，只有移动构造是 noexcept 才敢用移动；否则为保证强异常安全回退到拷贝构造，性能翻倍损失。 写移动构造/移动赋值一律加 noexcept（只要内部不抛）。"},{"h":"在范围 for 中修改容器导致迭代器失效","d":"范围 for 等价于「begin…end 的迭代器循环」，__end 只求值一次；循环内对 vector 做 push_back/erase/insert 会让 ++__begin/解引用成为 UB。 删除用显式迭代器循环 + it = v.erase(it) 推进；新增用 push_back 后重新取迭代器。"},{"h":"emplace_back 传入已存在的对象反而多一次拷贝","d":"emplace_back(existingObj) 用 existingObj 拷贝构造新元素（ forwarding 把它当左值），并没有「移动」效果，还多了一次构造。 要搬走已有对象用 push_back(std::move(existingObj))；emplace_back 只用于「直接传构造参数原地造」。"},{"h":"auto&& 的误解","d":"auto&& 是转发引用（不是「万能引用」的别名），它既能绑左值也能绑右值：auto&& x = 左值→T&，auto&& x = 临时→T&&（并延长临时生命）。常见误用是以为 auto&& 一定产生右值引用。 写泛型转发/要在循环里延长临时生命时用 auto&&，理解它落入左值时就是左值引用。"},{"h":"std::string_view 悬垂","d":"string_view 不拥有内存，返回局部 string 的视图、或绑定到临时 string 后再用，都是 UB（悬垂）。 仅在被引用字符串「确定比视图活得久」时用 string_view；需长期持有就转 std::string。"},{"h":"返回值误用 std::move 抑制 RVO","d":"return std::move(local); 把局部变量变成右值，反而阻止命名返回值优化（NRVO），还多一次移动。 直接 return local;，让编译器优先 RVO，失败再走移动。"}],"asks":[{"q":"std::move 到底做了什么？它真的「移动」了对象吗？","a":"std::move 本身不做任何运行期动作，它只是一个无条件的类型转换：把实参无条件转换为右值引用（本质是 static_cast<remove_reference_t<T>&&>(arg)），相当于告诉编译器「我允许你把这个对象当作右值来移动」。 真正的「资源转移」发生在移动构造函数 / 移动赋值运算符内部（把源对象的指针/句柄偷过来，并把源置空）。所以「move 不移动，移动发生在构造里」。此…","fu":["被 std::move 之后的源对象处于什么状态？还能再用吗？","为什么返回值不要写 std::move(res)？"],"tag":"通用/字节"},{"q":"移动构造为什么通常应该标 noexcept？","a":"这关系到 std::vector 等标准容器在重分配（扩容）时的异常安全策略。扩容时需要把旧元素搬到新内存，搬完旧内存要释放。为保证「强异常安全」（要么全成功、要么原状），标准库的规则是： - 若元素的移动构造是 noexcept，库确认移动不会抛异常 → 放心使用移动（O(1) 偷资源）。 - 若移动构造可能抛异常，库不敢用移动（否则搬到一半抛异常，新旧都没建好会损坏数据）→ 回退到拷贝构造（拷…","fu":["强异常安全和基本异常安全有什么区别？","如果不标 noexcept，什么操作会退化？"],"tag":"腾讯/美团"},{"q":"auto&& 是什么？它和 auto&、const auto& 有什么差别？","a":"auto&& 是转发引用（forwarding reference）在局部变量上的形式：它既能绑定左值也能绑定右值，具体类型由初始化表达式决定： - 绑定到左值：推导为 T&（左值引用）。 - 绑定到右值/临时量：推导为 T&&（右值引用），并且 auto&& 会延长临时对象的生命到整个作用域（这是范围 for 绑定 range 的写法 auto&& __range = range;）。 对比：…","fu":["为什么范围 for 用 auto&& 绑定 range？","decltype(auto) 和 auto&& 怎么选？"],"tag":"通用/字节"},{"q":"emplace_back 和 push_back 有什么本质区别？为什么说传入已存在对象反而可能多一次拷贝？","a":"push_back 接收一个已构造好的元素（左值或右值临时），把它移动/拷贝进容器尾部，因此至少有「构造临时 + 移动/拷贝」两次动作。emplace_back 接收构造函数的参数包 T&&... args，用 std::forward 完美转发后在容器预留内存里原地构造，省去了「先构造临时再搬」中的临时构造，通常少一次移动/拷贝（ex08 实测对比）。 但它有两个常见误解： 1. 传入已存在的左…","fu":["完美转发是怎么实现的？","什么情况下 emplace 不如 push_back？"],"tag":"美团/阿里"}]},{"id":"cpp-ch13","subj":"cpp","title":"输入/输出与文件：iostream、fstream 与格式化","summary":"iostream 体系；格式化输出与操纵符；文件流 fstream 读写；字符串流 stringstream；二进制 IO；错误状态位。","concepts":[{"id":"cpp-ch13/01-stream-state-and-sync","file":"01-stream-state-and-sync.md","title":"01 · 流的状态位与性能本质：从 streambuf 到 sync_with_stdio","kind":"flow","secs":[{"h":"一、理论根基：iostream 是「分层抽象」而非单块黑箱","s":"从软件工程的视角，C++ IO 之所以复杂，是因为它把「设备/缓冲」与「类型化读写」分成了两层：","c":null},{"h":"二、实现机制：四个状态位与失效恢复","s":"每个流对象内部维护一组状态位（std::ios_base::iostate），它们不是独立布尔，而是位标志，可用 rdstate() 整体读取，或用下列谓词查询：","c":{"lang":"cpp","code":"int x;\nstd::cin >> x;          // 若输入 \"abc\"，failbit 置位\nstd::cout << std::cin.fail();  // 输出 1\n// 此时后续 cin >> y 直接失败，y 保持未定义\nstd::cin.clear();       // 必须：清掉错误位\nstd::cin.ignore(...);   // 再丢弃造成错误的坏字符，否则会再次触发"}},{"h":"三、性能本质：sync_with_stdio 与 tie 的加速原理","s":"std::cin 默认与 C 标准库的 stdin 保持同步（sync_with_stdio(true)），目的是让混用 cin 与 scanf 时顺序正确。同步意味着：每次 C++ 操作都要与 C 的缓冲对齐，这通常通过加锁 + 双缓…","c":null},{"h":"四、边界与陷阱","s":"1. good() 为 true 仅表示「无错误位」；到达 EOF 时 eof() 和 fail() 常同时为真（读到末尾且提取失败），所以「用 eof() 当循环条件」是错误的——应循环内先提取再判断。","c":null},{"h":"五、可运行示例：状态位与 clear 恢复","s":"","c":{"lang":"cpp","code":"#include <iostream>\nint main() {\n    int x = -1;\n    std::cout << \"输入一个整数（可故意输入字母）: \";\n    if (!(std::cin >> x)) {               // 提取失败，failbit 置位\n        std::cout << \"failbit=\" << std::cin.fail() << ' ';\n        std::cin.clear();                 // 恢复流\n        std::cin.ignore(1024, '\\n');      // 丢弃坏行\n        std::cout << \"已恢复 good=\" << std::cin.good() << '\\n';\n…"}}]},{"id":"cpp-ch13/02-formatting","file":"02-formatting.md","title":"02 · 格式化控制：操纵符、浮点精度与对齐","kind":"stack","secs":[{"h":"一、理论根基：格式化是「状态 + 一次性修饰符」的混合模型","s":"iostream 的格式控制有两类：","c":null},{"h":"二、实现机制：locale 与 facet 的代价","s":"默认 locale（通常是 \"C\" 或系统本地化）里包含 numpunct、ctype 等 facet（方面）。每次格式化一个数字，都要经过 facet 的虚函数调用做「千位分隔符」「小数点字符」等处理。这正是 iostream 慢于…","c":null},{"h":"三、工程实践：对齐表格与浮点","s":"常用操纵符（需 #include <iomanip>）：","c":{"lang":"cpp","code":"std::cout << std::left << std::setfill('.') << std::setw(12) << \"Name\"\n          << std::right << std::setw(8) << std::fixed << std::setprecision(2) << 3.14159 << '\\n';\n// 输出：Name........    3.14"}},{"h":"四、边界与陷阱","s":"1. setw 只管下一个输出，链式写多个字段时每个都要单独 setw。","c":null},{"h":"五、可运行示例：浮点与对齐","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <iomanip>\nint main() {\n    double pi = 3.14159265358979;\n    std::cout << \"默认: \" << pi << '\\n';                  // 6 位有效数字\n    std::cout << \"定点2位: \" << std::fixed << std::setprecision(2) << pi << '\\n';\n    std::cout << \"科学3位: \" << std::scientific << std::setprecision(3) << pi << '\\n';\n\n    std::cout << std::defaultfloat;                       // 恢复默认\n…"}}]},{"id":"cpp-ch13/03-fstream","file":"03-fstream.md","title":"03 · 文件流 fstream：打开模式、文件位置与文本/二进制","kind":"flow","secs":[{"h":"一、理论根基：fstream 是「流 + 文件缓冲区」的组合","s":"std::fstream 继承自 iostream，底层绑定一个 filebuf（文件缓冲区）。它同时具备 istream 与 ostream 能力，打开模式决定其行为：","c":null},{"h":"二、实现机制：文件位置指针与文本/二进制差异","s":"每个文件流有两个独立的位置指针：","c":null},{"h":"三、工程实践：健壮的文件读写","s":"1. 永远先 is_open() 再操作：打开失败（权限/路径不存在）时流进入 fail 状态，盲目操作会静默失败。","c":null},{"h":"四、边界与陷阱","s":"1. 忘记 is_open() 检查 → 打开失败后程序继续跑，得到空/错误结果。","c":null},{"h":"五、可运行示例：文本与二进制对比","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <fstream>\n#include <string>\nint main() {\n    // 文本写读\n    {\n        std::ofstream out(\"demo.txt\");\n        out << \"hello\\nworld\\n\";           // 文本模式\n    }\n…"}}]},{"id":"cpp-ch13/04-stringstream-and-format","file":"04-stringstream-and-format.md","title":"04 · stringstream 与 std::format：字符串的解析与格式化","kind":"stack","secs":[{"h":"一、理论根基：内存中的「流」","s":"std::stringstream（及 istringstream/ostringstream）把内存字符串当作流缓冲区，于是在「字符串 ↔ 类型化数据」之间架起桥梁：","c":null},{"h":"二、实现机制：stringstream 为什么慢","s":"stringstream 内部持有一块 stringbuf，每次 << 都走 ostream 的虚调用 + locale facet，最后还要把内部缓冲区拷贝出来（C++11 起可用 std::move(ss).str() 减少一次拷贝…","c":null},{"h":"三、std::format（C++20）的设计动机","s":"std::format（源自开源库 {fmt}）的设计动机正是同时拿到 printf 的速度与 iostream 的类型安全：","c":{"lang":"cpp","code":"// C++20\n#include <format>\nstd::string s = std::format(\"pi={:.3f}, n={:>5}\", 3.14159, 42); // \"pi=3.142, n=   42\""}},{"h":"四、工程实践：CSV 行解析","s":"istringstream 是解析结构化文本（CSV、日志）的利器——按空白或自定义分隔切分：","c":{"lang":"cpp","code":"std::istringstream iss(\"alice,23,98.5\");\nstd::string name; int age; double score;\nstd::getline(iss, name, ',');   // 用 ',' 作分隔\niss >> age; iss.ignore();       // 跳过 ','\niss >> score;"}},{"h":"五、边界与陷阱","s":"1. stringstream 复用时要 ss.str(\"\") + ss.clear() 双清：前者清内容，后者清状态位（否则上次读到的 eof/fail 会让新操作失效）。","c":null},{"h":"六、可运行示例：stringstream 解析与格式化","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <sstream>\n#include <string>\nint main() {\n    // 解析 CSV 行\n    std::istringstream iss(\"alice,23,98.5\");\n    std::string name; int age; double score;\n    std::getline(iss, name, ',');\n    iss >> age; iss.ignore(); iss >> score;\n…"}}]},{"id":"cpp-ch13/05-stream-practical-recipes","file":"05-stream-practical-recipes.md","title":"凯喵实战手记 · 流、格式化与文件的「IO 陷阱」","kind":"flow","secs":[{"h":"现场 1：ofstream 默认截断清空文件","s":"想追加必须显式 std::ofstream f(\"log.txt\", std::ios::app)；想读写不破坏原内容用 std::ios::in | std::ios::out（别带 trunc）。凯喵铁律：打开文件前想清楚意图，默认…","c":{"lang":"cpp","code":"std::ofstream f(\"log.txt\"); // 等价于 ios::out | ios::trunc，原内容被清空"}},{"h":"现场 2：fstream 同时读写未 seek 就换向","s":"读写切换前必须 seek（哪怕 seekp(0, std::ios::cur) 原位 seek）来清空状态。凯喵：每次「读→写」或「写→读」前都 seek 一下，这是标准要求的同步点。","c":{"lang":"cpp","code":"std::fstream f(\"data.bin\", std::ios::in | std::ios::out);\nint x; f >> x;          // 读\nf << 42;                // 直接写——UB！读写切换必须先 f.seekp(...)"}},{"h":"现场 3：文本模式读写二进制数据","s":"在 Windows 下，文本模式会把 \\n 转 \\r\\n、碰到 0x1A 当 EOF。用 std::ifstream f(path, std::ios::binary) 读图片/二进制必须用 binary 标志，否则数据被悄悄篡改。凯喵…","c":null},{"h":"现场 4：流状态位 failbit/badbit 不清除就卡死","s":"读失败后置位 failbit，后续所有操作被忽略。凯喵：读前/读后检查 if (stream) 或 stream.good()，出错 stream.clear() 再 ignore 丢弃坏输入，才能继续。","c":{"lang":"cpp","code":"int x; cin >> x; // 用户输入 \"abc\"，failbit 置位\ncin >> y;        // 直接跳过，流已坏"}},{"h":"现场 5：getline 与 >> 混用的换行残留","s":"> 不消费换行符，getline 立刻遇到它返回空。凯喵：混用前先 cin.ignore() 丢掉残留换行，或用 getline 后手动解析数字。","c":{"lang":"cpp","code":"int n; cin >> n;              // 读完数字，留下 '\\n' 在缓冲区\nstd::string s; std::getline(cin, s); // 读到空行（只读到那个 '\\n'）"}},{"h":"现场 6：浮点格式化精度陷阱","s":"默认 setprecision 是「有效数字」，加 std::fixed 才是「小数点后位数」。凯喵：要固定小数位就 << std::fixed << std::setprecision(n)，别让精度含义和你想象的不一样。","c":{"lang":"cpp","code":"std::cout << std::setprecision(2) << 3.14159; // 输出 \"3.1\"？取决于 fixed"}},{"h":"现场 7：stringstream 复用前要 clear() + str(\"\")","s":"ss.str(\"\") 清空内容，ss.clear() 清状态位，两者都做才能干净复用。凯喵：把 stringstream 当临时缓冲区时，每次用前双清。","c":{"lang":"cpp","code":"std::stringstream ss;\nss << 1; std::string s1 = ss.str();\nss.str(\"\"); ss.clear(); // 不清 str 会保留旧内容，不 clear 状态位可能坏了\nss << 2; std::string s2 = ss.str();"}},{"h":"现场 8：std::endl 每次都 flush，拖慢 IO","s":"std::endl = 输出换行 + 强制 flush，频繁调用（尤其大循环）会让 IO 慢几十倍。凯喵：普通换行用 '\\n'，只有需要立刻落盘（日志、崩溃前）才用 endl 或 flush。","c":null},{"h":"现场 9：本地化（locale）影响数字/日期格式","s":"流的 imbue(locale) 会改变千位分隔符、小数点字符（, vs .）。读外部数据时被 locale 偷偷改格式，解析全错。凯喵：处理机器生成的数据用 std::locale::classic()（C locale），别被用户环…","c":null},{"h":"现场 10：宽字符流 wcout 与窄字符混用","s":"std::wcout 输出 wstring，和 cout 混用且涉及中文/UTF-8 时容易乱码或只输出部分。凯喵：现代项目统一窄字符 UTF-8 + cout，避免宽窄流混搭；必须宽字符时全程一致。","c":null},{"h":"现场 11：文件打开失败不检查就写","s":"打开后立刻 if (!f) { / 报错 / }。凯喵：任何文件 IO 第一件事就是检查流是否真的打开了，别假设路径一定存在可写。","c":{"lang":"cpp","code":"std::ofstream f(\"C:/no/such/dir/out.txt\");\nf << \"data\"; // 目录不存在，流 quietly 失败，数据静默丢失"}},{"h":"现场 12：读整个文件的高效写法","s":"用 istreambuf_iterator 或 C++17 std::filesystem + std::ifstream 一次性读。凯喵：别用 while (!f.eof()) 逐字符读——eof() 在读完最后一个字符后才置位，容易…","c":{"lang":"cpp","code":"std::ifstream f(path, std::ios::binary);\nstd::string content((std::istreambuf_iterator<char>(f)),\n                    std::istreambuf_iterator<char>());"}},{"h":"凯喵复盘：把 IO 当成「会出错的外部系统」来对待","s":"这 12 个现场的共性，是很多人把流当成「写进去就读得出来」的魔法通道，结果在二进制、追加、状态位、本地化这些细节上翻车。凯喵的经验是：永远把文件/网络 IO 当成不可信的外部系统——打开要检查、读写要检查返回值、用完要关闭、出错要恢复…","c":null},{"h":"凯喵速记：IO 的三条保命习惯","s":"只记三句也能躲开绝大多数事故：第一，打开文件立刻 if (!f) 检查，别假设路径一定可写；第二，读写切换前先 seek、读失败先 clear() 再 ignore，流是有状态机器，一步坏步步坏；第三，二进制必开 binary、换行用…","c":null},{"h":"🧑‍💻 程序员视角","s":"ofstream 默认以 ios::trunc 打开，第二次打开同一文件会把内容清空——追加必须显式加 ios::app。fstream 同时读写时，从写切到读之前必须 seekp/seekg 或 flush，否则读到的位置不对。文本模…","c":null},{"h":"🎓 博士生视角","s":"iostream 的设计是「流缓冲 + 状态机 + 格式化层」三层：streambuf 负责底层读写与缓冲，ios_base 维护状态位（good/eof/fail/bad），格式化层处理精度、宽度、进制。状态位的语义差异很关键：fai…","c":null},{"h":"📚 考研者视角","s":"面试与实战：","c":null}]}],"exams":[{"kind":"choice","q":"关于 sync_with_stdio 与流状态，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"std::ios::sync_with_stdio(false) 之后仍可安全混用 cin 与 scanf"},{"k":"B","t":"cin 提取失败后，若不 clear()，后续 cin 操作会继续失败"},{"k":"C","t":"good() 返回 true 代表一定还没读到文件末尾"},{"k":"D","t":"setw 是持久状态，设置一次对后续所有字段都生效"}],"ans":"B","why":"sync_with_stdio(false) 解除 C++ 流与 C stdio 的同步，之后混用顺序无保证，故 A 错；failbit 置位后该流后续提取/插入均为 no-op，必须 clear() 才能恢复，B 对；到达 EOF 时 eof() 与 fail() 常同时为真，good() 为假，C 错；setw 只影响下一次字段，是一次性操纵符，D 错。"},{"kind":"fix_error","q":"修复读取失败后未恢复流的问题","stem":"下面程序在用户输入非数字时会进入死循环（failbit 置位后 cin >> x 一直失败）。请修复，使其在读取失败后清状态并丢弃坏字符，然后继续提示。 cpp int x; while (true) { if (!(std::cin >> x)) { / 缺失恢复逻辑 / continue; } std::cout << x << '\\n'; }","opts":[],"ans":"int x; while (true) { if (!(std::cin >> x)) { if (std::cin.eof()) break; // 真正到末尾则退出 std::cin.clear(); // 清掉 failbit std::cin.ignore(1024, '\\n'); // 丢弃造成失败的整行坏字…","why":"失败时必须先 clear() 清状态位，再用 ignore() 跳过坏字符，否则下一次 >> 仍是 no-op 导致死循环；同时用 eof() 区分「真到末尾」与「格式错误」。"},{"kind":"output","q":"读代码写输出（浮点默认精度）","stem":"cpp #include <iostream> int main() { double x = 0.123456789; std::cout << x << '\\n'; std::cout << std::fixed << std::setprecision(3) << x << '\\n'; }","opts":[],"ans":"0.123457 0.123","why":"默认（非 fixed/scientific）下 setprecision 表示有效数字，默认 6 位，故 0.123456789 显示 0.123457（四舍五入）；fixed+setprecision(3) 表示小数点后 3 位，显示 0.123。"},{"kind":"coding","q":"用 stringstream 解析一行逗号分隔的数据","stem":"给定一行形如 名字,年龄,分数 的字符串，用 istringstream + getline(..., ',') + ignore() 解析出 name(string)、age(int)、score(double)，并输出 name age score。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行形如 名字,年龄,分…","opts":[],"ans":"#include <iostream> #include <sstream> #include <string> int main() { std::string line; std::getline(std::cin, line); std::istringstream iss(line); std::string…","why":"getline 第三参指定分隔符 ',' 切出名字；>> 读整数后必须 ignore() 跳过逗号，再 >> 读浮点；混用 >> 与 getline 时务必注意残留分隔符。"},{"kind":"design","q":"LeetCode 157 · Read N Characters Given Read4","stem":"实现带缓冲区的字符读取：给定只可调用一次的 read4(char buf)（从文件读至多 4 字符），实现 read(char buf, int n) 正好读入 n 个字符。重点在于维护跨调用的内部缓冲与指针（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 维护一个 4 字节内部缓冲 buf4_、读入计数 i_ 与有效长度 n4_； // 每次 read 先从 buf4_ 吐出剩余字符，不够再调用 read4 补足，最后截断到 n。 // 完整接口与样例见 external_url 原题。","why":"这是 IO 缓冲的经典模型：内核/文件以块（4）为单位供给，用户以任意 n 消费，必须用内部缓冲 + 双指针衔接，避免重复/丢失字符。"},{"kind":"design","q":"LeetCode 158 · Read N Characters Given Read4 II（多次调用）","stem":"在 157 基础上，read 会被多次调用，需保证跨调用的状态正确：已读但未消费的缓冲字符必须在下一次调用时先返回。注意处理 EOF 与不足 n 的情况（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 用成员变量保存 buf4_、i_、n4_；read 先吐内部剩余再 read4 补充， // 当 read4 返回 0（EOF）且内部缓冲耗尽时停止，不得多读。 // 完整接口与样例见 external_url 原题。","why":"多次调用场景把「缓冲区残留」从一次性问题变成状态持久问题，必须在类对象中保存读指针；EOF 后不得再调用 read4 制造多余字符。"}],"works":[{"h":"输入失败后不 clear() 导致后续读取全废","d":"cin >> x 遇非法输入会置 failbit，此后所有 cin >> 都变成 no-op，x 保持旧值或不确定。 先 cin.clear() 清状态位，再 cin.ignore(n, '\\n') 丢弃坏字符后才能继续读取。"},{"h":"误用 eof() 作为循环条件","d":"while (!cin.eof()) { cin >> x; ... } 会在读到末尾那次提取失败后仍进入循环体，处理一次脏数据。 写成 while (cin >> x) { ... }：提取成功才进循环，到 EOF 自然终止。"},{"h":"getline 与 >> 混用留下换行","d":"先 cin >> n; 读整数，缓冲区残留 '\\n'，紧接着 getline(cin, s) 会立刻读到空行。 在 >> 之后、getline 之前调用 cin.ignore() 吃掉换行；或统一用 getline + istringstream 解析。"},{"h":"浮点默认精度丢失的错觉","d":"cout << 0.123456789; 默认只打印 6 位有效数字，看起来「丢精度」，实际值未变。 用 cout << fixed << setprecision(n) 显式控制位数；注意 setprecision 在默认模式下表示有效数字。"},{"h":"忘记检查 is_open()","d":"打开文件失败（权限/路径错误）时流进入 fail 状态，后续读写全部静默失败，得到空结果。 打开后立即 if (!f.is_open()) { / 报错处理 / }，再做读写。"},{"h":"用文本模式读写二进制数据","d":"ofstream/ifstream 默认文本模式，Windows 上 '\\n' ↔ '\\r\\n' 会被翻译，含 0x0A/0x0D 或 0x1A 的字节会被篡改，文件损坏。 读写结构化数据必须用 ios::binary 模式（write/read）。"},{"h":"fstream 同时读写未 seek 就换向","d":"在读写混合的 fstream 中，从读切到写（或反之）前若未 seek/flush，行为未定义，可能读到旧缓冲或写入丢失。 每次切换方向前调用一次 seekg/seekp（哪怕偏移到原位）以隔断。"},{"h":"ofstream 默认截断清空文件","d":"ofstream f(\"log.txt\") 等价于 ios::out | ios::trunc，会直接清空已有文件；误以为「打开即可追加」。 需要追加用 ios::app；需要读写不破坏用 ios::in | ios::out（不要加 trunc）。"}],"asks":[{"q":"为什么 std::ios::sync_with_stdio(false) 能显著加速 cin/cout？它有什么代价？","a":"默认情况下 std::cin/std::cout 与 C 标准库的 stdin/stdout 保持同步（sync_with_stdio(true)），目的是让混用 cin 与 scanf 时顺序依然正确。同步意味着每次 C++ 流操作都要与 C 的缓冲对齐，通常带来额外的加锁与双缓冲拷贝开销。调用 sync_with_stdio(false) 后，C++ 流拥有独立且更大的缓冲区，不再为每个字符与…","fu":["tie(nullptr) 解决的是什么问题？","为什么大数据读入时 endl 比 \\n 慢很多？"],"tag":"通用/字节"},{"q":"iostream 相比 printf 慢在哪里？什么时候该改用 std::format 或 printf？","a":"iostream 的慢主要来自两点： 1. 虚函数派发：operator<< 最终落到 streambuf 的虚函数（如 sputc），每次字符/字段处理都走虚调用，难以被内联与向量化。 2. locale 与 facet：默认 locale 在处理每个数字时都要经过 numpunct/ctype 等 facet 的虚调用做本地化（千位分隔、小数点字符等）。 printf 的格式串在运行期解析、直…","fu":["std::format 为什么能在编译期检查格式串？","{fmt} 是怎么绕过 locale facet 开销的？"],"tag":"通用/阿里"},{"q":"输入失败后为什么要 clear()？goodbit/eofbit/failbit/badbit 各自含义与区别？","a":"流内部维护一组位标志（std::ios_base::iostate）： - goodbit（值为 0）：无任何错误位，表示「一切正常」。good() 是「所有错误位都为 0」的合取，不是单独一位。 - eofbit：已到达输入末尾（读到 EOF）。常与 failbit 同时置位（读到末尾且最后一次提取失败）。 - failbit：逻辑错误（格式不匹配、期望 int 却读到字母）。流仍可恢复——cl…","fu":["为什么不能用 eof() 当循环条件？","clear() 会丢弃坏字符吗？"],"tag":"通用/美团"}]},{"id":"cpp-ch14","subj":"cpp","title":"预处理与宏：include/define/条件编译/头文件守卫","summary":"翻译单元与编译流程；#include 守卫与 #pragma once；宏 vs 常量/模板；条件编译；__FILE__/__LINE__；避免宏陷阱。","concepts":[{"id":"cpp-ch14/01-translation-phases-include","file":"01-translation-phases-include.md","title":"01 · 翻译阶段与 #include：预处理在编译流程中的位置","kind":"timeline","secs":[{"h":"一、理论根基：预处理是「编译之前的纯文本变换」","s":"C/C++ 的「翻译（translation）」被标准划分为若干翻译阶段（translation phases），其中预处理（阶段 1-4）发生在真正的语法/语义分析之前，且完全不理解 C++ 的类型系统：","c":null},{"h":"二、实现机制：#include 的「文本包含」语义","s":"#include <header> 或 #include \"header\" 的语义是：用被包含文件的全部预处理 token 原样替换这一行。它是递归的——被包含文件里的 #include 会继续展开，因此头文件之间可能互相包含、甚至同一…","c":null},{"h":"三、#pragma once 与其局限","s":"#pragma once 是编译器提供的「本文件只展开一次」指令，省去了手写守卫的样板，且（理论上）更快（编译器可直接按物理文件去重，无需反复打开/扫描）。","c":null},{"h":"四、边界与陷阱","s":"1. 头文件守卫宏名要足够唯一（常带项目/路径前缀），否则不同头文件撞名会导致「本该包含的内容被跳过」。","c":null},{"h":"五、可运行示例：守卫防重定义","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#define INCLUDED_ONCE            // 模拟首次包含已定义守卫\n#ifndef INCLUDED_ONCE\n#define INCLUDED_ONCE\nint helper() { return 1; }\n#endif\n#ifndef INCLUDED_ONCE           // 第二次「包含」被跳过\n#define INCLUDED_ONCE\nint helper() { return 2; }      // 若没有守卫会重复定义，编译失败\n…"}}]},{"id":"cpp-ch14/02-macro-hygiene","file":"02-macro-hygiene.md","title":"02 · 宏的卫生问题：括号、多重求值与 do-while(0)","kind":"flow","secs":[{"h":"一、理论根基：宏是「无类型、无作用域的 token 替换」","s":"因为宏在预处理阶段（语法分析之前）发生，它看不到类型、也看不到运算符优先级。于是「看起来像函数」的宏，实则只是把实参 token 序列塞进形参位置再整体替换。这带来三类经典卫生问题。","c":null},{"h":"二、实现机制与坑","s":"✅ 每个参数与整体都加括号：#define SQUARE(x) ((x)(x))。","c":{"lang":"cpp","code":"#define SQUARE(x) x*x\nSQUARE(1+2)   // 替换为 1+2*1+2 = 5，而非期望的 9"}},{"h":"三、# 与 ## 运算符","s":"","c":null},{"h":"四、工程实践：宏与 inline 的取舍","s":"","c":null},{"h":"五、可运行示例：括号、多重求值、do-while","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#define SQUARE(x) x*x\n#define SAFE(x) ((x)*(x))\n#define LOG() do { std::cout << \"a\\n\"; std::cout << \"b\\n\"; } while(0)\nint main() {\n    std::cout << SQUARE(1+2) << '\\n';     // 5（优先级错）\n    std::cout << SAFE(1+2) << '\\n';       // 9（正确）\n    int x = 2;\n    std::cout << \"m=\" << SAFE(x++) << \" x=\" << x << '\\n';  // 副作用两次\n…"}}]},{"id":"cpp-ch14/03-conditional-compilation-xmacro","file":"03-conditional-compilation-xmacro.md","title":"03 · 条件编译、X-Macro 与 static_assert 替代宏","kind":"flow","secs":[{"h":"一、理论根基：条件编译是「编译期的 if」","s":"#if / #ifdef / #ifndef / #elif / #else / #endif 在预处理阶段根据常量表达式（或宏是否定义）决定哪些代码进入翻译单元。它处理的是「同一份源码在不同平台/配置下编译出不同产物」的需求，与运行期…","c":null},{"h":"二、X-Macro：用一张表驱动「枚举 + 字符串 + 分支」","s":"重复维护「枚举值」与「对应的字符串/分支」是典型痛点（漏改一处就错位）。X-Macro 用一个宏列表作为单一事实来源，靠 #define X(...) 在不同位置「展开同一张表」生成多份代码：","c":{"lang":"cpp","code":"#define COLORS \\\n    X(Red,   1) \\\n    X(Green, 2) \\\n    X(Blue,  4)\nenum class Color { #define X(n,v) n = v, COLORS #undef X };\nconst char* name(int v){ switch(v){\n    #define X(n,v) case v: return #n; COLORS #undef X\n    default: return \"Unknown\"; } }"}},{"h":"三、用 static_assert / constexpr 替代「可编译期计算」的宏","s":"传统 C 用宏表达「编译期常量与断言」：","c":{"lang":"cpp","code":"#define SIZE 1024\n#define ASSERT(c) typedef char _a[(c)?1:-1]   // 丑陋的编译期断言"}},{"h":"四、边界与陷阱","s":"1. #if 中未定义的宏名视为 0（不会报错），容易把拼写错误的宏名静默当成 false —— 可改用 #ifdef + 显式定义提升可读性。","c":null},{"h":"五、可运行示例：X-Macro 与 static_assert","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#define COLORS X(Red,1) X(Green,2) X(Blue,4)\nenum class Color { #define X(n,v) n = v, COLORS #undef X };\nconst char* colorName(int v){\n    switch(v){ #define X(n,v) case v: return #n; COLORS #undef X\n        default: return \"Unknown\"; }\n}\nint main(){\n    static_assert(sizeof(int)==4, \"int must be 4 bytes\");\n…"}}]},{"id":"cpp-ch14/04-predefined-macros-log","file":"04-predefined-macros-log.md","title":"04 · 预定义宏与日志：__FILE__/__LINE__ 的工程用法","kind":"flow","secs":[{"h":"一、理论根基：预定义宏是编译器注入的「编译期常量」","s":"C/C++ 标准与实现定义了一组预定义宏（predefined macros），由编译器在预处理阶段直接提供，无需 #define：","c":null},{"h":"二、实现机制：日志宏如何「携带位置信息」","s":"把 __FILE__ 与 __LINE__ 包进一个宏，就能在任何调用点自动记录「这条日志来自哪个文件哪一行」，这是几乎所有 C/C++ 日志库（spdlog、glog）的基础：","c":{"lang":"cpp","code":"#define LOG(msg) \\\n    std::cout << __FILE__ << \":\" << __LINE__ << \" \" << msg << '\\n'"}},{"h":"三、工程实践：调试开关与版本信息","s":"","c":null},{"h":"四、边界与陷阱","s":"1. __FILE__ 带路径，日志可能泄露绝对路径（安全/隐私考量）。","c":null},{"h":"五、可运行示例：位置感知日志宏","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#define LOG(msg) std::cout << __FILE__ << \":\" << __LINE__ << \" \" << msg << '\\n'\nint main() {\n    LOG(\"start\");\n    LOG(\"done\");\n}"}}]},{"id":"cpp-ch14/05-preprocessor-practical-recipes","file":"05-preprocessor-practical-recipes.md","title":"凯喵实战手记 · 预处理器：编译之前那场「文本手术」","kind":"flow","secs":[{"h":"现场 1：预处理是编译的第一道工序","s":"编译器并不是直接读你的 .cpp。它先跑预处理器，把 #include 的内容整段贴进来、把宏全部展开、把条件编译不成立的分支删掉，生成一个「纯净」的翻译单元，再交给真正的编译阶段。凯喵提醒：理解这个顺序，你才能解释为什么「宏展开后报错…","c":{"lang":"bash","code":"g++ -E main.cpp -o main.i   # 只看预处理结果"}},{"h":"现场 2：#include 是文本替换，不是模块导入","s":"#include \"x.h\" 的语义就是把那个文件的全部内容原样粘贴到这一行。它没有命名空间、没有作用域、没有可见性控制。凯喵：所以头文件里出现的每一样东西都会进入包含它的每个源文件，这也是「头文件污染」的根源。想清楚这一点，你就不会再…","c":null},{"h":"现场 3：头文件守卫防止重复包含","s":"同一个头文件被间接包含两次，里面的类定义就出现两次，编译报重定义。传统用 #ifndef/#define/#endif 包裹，现代可用 #pragma once。凯喵：两者都要有意识地用，别指望编译器宽容；漏了守卫的工程，随着依赖变复杂…","c":{"lang":"cpp","code":"#ifndef MY_HEADER_H\n#define MY_HEADER_H\n// 声明...\n#endif"}},{"h":"现场 4：宏参数不加括号，优先级被重写","s":"#define SQUARE(x) xx 看起来人畜无害，但 SQUARE(1+2) 展开成 1+21+2 等于 5，不是 9。凯喵：宏参数和整体都要加括号，写成 #define SQUARE(x) ((x)(x))。这是预处理最经典的…","c":{"lang":"cpp","code":"#define SQUARE(x) ((x)*(x))   // 两个括号都不能省"}},{"h":"现场 5：多语句宏要用 do { } while(0)","s":"#define LOG(x) f(x); g(x); 放进 if (c) LOG(x); 里，g(x) 会跑到 if 外面。凯喵：多语句宏统一包成 do { ... } while(0)，这样它在语法上表现得像一条语句，放在任何位置都安…","c":{"lang":"cpp","code":"#define LOG(x) do { f(x); g(x); } while (0)"}},{"h":"现场 6：宏没有类型检查，优先 inline 与 constexpr","s":"宏只是文本替换，不做类型检查，出错时报错位置还乱七八糟。凯喵：能用 constexpr 常量、inline 函数、模板解决的事，就别用宏。现代 C++ 里宏应该只保留它真正不可替代的场景，比如条件编译和字符串化。","c":null},{"h":"现场 7：# 字符串化与 ## 连接","s":"#x 把宏参数变成字符串，a##b 把两个记号粘成一个。凯喵：这是 X-Macro 和日志宏的基础。但注意 ## 拼接出来的可能不是合法标识符，调试时先用 -E 看展开结果，别靠脑补。","c":{"lang":"cpp","code":"#define STR(x) #x\n#define CAT(a, b) a##b\nSTR(hello)      // \"hello\"\nCAT(foo, bar)   // foobar"}},{"h":"现场 8：条件编译做平台与调试开关","s":"#ifdef _WIN32、#if DEBUG 这类条件编译，让同一份代码在不同平台或构建配置下走不同分支。凯喵：条件编译能解决平台差异，但滥用会让代码变得难以阅读和测试——每个分支都要单独编译验证，否则很容易出现「只在某个平台编不过」…","c":null},{"h":"现场 9：X-Macro 消除重复枚举与字符串表","s":"同一组名字既要定义枚举、又要生成字符串、还要写解析函数时，手写三遍必然不同步。X-Macro 把「名字列表」抽成一个宏，再用不同的 #define 展开三次。凯喵：这是预处理少数真正优雅的用法，维护成本能从三处降到一处。","c":{"lang":"cpp","code":"#define COLORS(X) X(RED) X(GREEN) X(BLUE)\n#define AS_ENUM(n) COLOR_##n,\nenum Color { COLORS(AS_ENUM) };"}},{"h":"现场 10：__FILE__ 与 __LINE__ 做精准日志","s":"__FILE__ 展开成当前文件名，__LINE__ 展开成行号。凯喵：写日志宏时带上这两个，出错时能直接定位到源文件与行，比只打印一句「出错了」有用一百倍。这也是宏在「无法被函数替代」的场景里的典型价值。","c":{"lang":"cpp","code":"#define LOG(msg) std::cerr << __FILE__ << \":\" << __LINE__ << \" \" << msg << \"\\n\""}},{"h":"现场 11：assert 在 NDEBUG 下整段消失","s":"发布构建定义 NDEBUG 后，assert 里的表达式根本不执行。凯喵：绝不要在 assert 里写有副作用的代码，比如 assert(init())——调试构建正常，发布构建直接跳过初始化，行为完全变样。这是「只在正式环境出问题」的…","c":null},{"h":"现场 12：宏会污染全局名字空间","s":"宏没有作用域，一旦定义就影响后面所有代码，可能和库里的同名函数冲突。凯喵：宏名用全大写加前缀，用完及时 #undef，尤其是那些只在单个源文件里用的小工具宏。命名空间管不住宏，这是它和普通标识符最大的区别。","c":null},{"h":"现场 13：可变参数宏与 __VA_ARGS__","s":"#define LOG(fmt, ...) printf(fmt, __VA_ARGS__) 支持变参。凯喵：注意参数为空时的逗号问题，C++20 的 __VA_OPT__ 能优雅处理；老标准则要靠 ##__VA_ARGS__ 这类编译…","c":{"lang":"cpp","code":"#define LOGF(fmt, ...) printf(fmt, ##__VA_ARGS__)"}},{"h":"现场 14：用 -E 看展开结果，别靠猜","s":"宏出问题时，最快的办法是 g++ -E 把预处理结果打出来，直接看它到底展开成了什么。凯喵：所有「宏看起来对、跑起来错」的谜题，-E 都能一秒破案。养成看展开结果的习惯，比背一百条宏规则都管用。","c":null},{"h":"凯喵叮嘱：能用语言特性就别用宏","s":"最后叮嘱一句：现代 C++ 已经用 constexpr、inline、模板、if constexpr 把宏的大部分用途接管了，而且带类型检查、报错清晰、可调试。凯喵的原则是：只有当「条件编译」「字符串化」「生成重复代码」这三类真正需要文…","c":null},{"h":"🧑‍💻 程序员视角","s":"宏参数不加括号是经典事故：#define SQ(x) xx 在 SQ(a+1) 上展开成 a+1a+1，结果完全错。头文件守卫漏写会导致重复定义，而 #pragma once 虽被广泛支持但不是标准。#include 是纯文本替换：把头…","c":null},{"h":"🎓 博士生视角","s":"预处理器是独立于编译器的「文本变换阶段」，它不理解类型与作用域，只做宏替换、条件编译与文件包含。这解释了为什么宏容易出错：没有类型检查、没有作用域、没有调试信息。现代 C++ 用 constexpr 函数、inline 变量、模板替代了…","c":null},{"h":"📚 考研者视角","s":"面试常考：","c":null}]}],"exams":[{"kind":"choice","q":"关于头文件守卫与 #pragma once，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"#pragma once 由 C++ 标准规定，所有编译器必须支持"},{"k":"B","t":"头文件守卫靠宏名判重，宏名冲突可能导致该包含的内容被错误跳过"},{"k":"C","t":"#include 会做类型检查后再插入头文件内容"},{"k":"D","t":"#pragma once 按宏名判重，与 #ifndef 守卫机制相同"}],"ans":"B","why":"#pragma once 非标准，靠「同一物理文件」判重（A 错）；#include 是预处理期的纯文本替换，不做类型检查（C 错）；#pragma once 按物理文件去重，与传统 #ifndef 按宏名去重不同（D 错）；守卫宏名若与其他头文件撞名，会错误地跳过本该包含的内容（B 对）。"},{"kind":"fix_error","q":"修复多语句宏在 if/else 中导致的编译错误","stem":"下面宏用于 if (cond) DBG(); else other(); 时会编译失败（else 悬空）。请修复，使宏在任何语句上下文中都表现为单条语句。 cpp #define DBG() std::cout << \"a\\n\"; std::cout << \"b\\n\"","opts":[],"ans":"#define DBG() do { std::cout << \"a\\n\"; std::cout << \"b\\n\"; } while(0)","why":"多语句宏必须用 do{}while(0) 包裹成一条复合语句，否则展开后分号与 else 配合会悬空；do-while(0) 末尾需要调用处写分号，语义也自然。"},{"kind":"output","q":"读代码写输出（宏括号陷阱）","stem":"cpp #include <iostream> #define SQUARE(x) xx int main() { std::cout << SQUARE(1+2) << '\\n'; std::cout << SQUARE(3) << '\\n'; }","opts":[],"ans":"5 9","why":"SQUARE(1+2) 展开为 1+21+2 = 5（缺少括号导致优先级错）；SQUARE(3) 展开为 33 = 9。这正是宏参数必须加括号的原因。"},{"kind":"coding","q":"用 inline 函数替代宏实现 square 并避免副作用","stem":"把「像函数」的宏 SQUARE(x) 改写为类型安全、参数只求值一次的 inline 函数（或函数模板），使其在 square(x++) 场景下只自增一次。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行一个整数 x。 输出三行：第一行 square(x)；第二行 square(y++) 的结果；第三行自增后的 y（第二…","opts":[],"ans":"#include <iostream> template <typename T> inline T square(T x) { return x x; } int main() { long long x; std::cin >> x; std::cout << square(x) << \"\\n\"; long lon…","why":"inline 函数的形参是真正的变量，实参只求值一次；相比宏既消除多重求值副作用，又获得类型检查与可调试性（可设断点）。"},{"kind":"design","q":"LeetCode 191 · Number of 1 Bits","stem":"编写一个函数返回无符号整数的二进制表示中「1」的个数。可借助位运算与掩码（与用宏定义标志位的位操作一脉相承）。注意 n 可能为 0 或全 1（补码）（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 经典做法：n &= (n-1) 每次消去最低位的 1，计数直到 n 为 0； // 或用查表/并行位计数。完整接口与样例见 external_url 原题。","why":"位运算（与、移位、n&(n-1)）是底层标志位处理的基础，与用宏做位开关/标志判断的思维方式一致；注意无符号类型与边界。"},{"kind":"design","q":"LeetCode 78 · Subsets（二进制枚举子集）","stem":"给定不含重复元素的整数数组，返回其所有子集（幂集）。常用「二进制枚举」：对每个元素用 0/1 表示是否在子集中，共 2^n 种组合——这与条件编译按位开关的思想相通（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 外层 i 从 0 到 (1<<n)-1，内层按 i 的每一位决定是否纳入 nums[j]； // 共枚举 2^n 个掩码，每个掩码对应一个子集。完整接口与样例见 external_url 原题。","why":"二进制枚举把「选/不选」映射为位 0/1，是条件编译开关思想在算法中的对应物；注意时间复杂度 O(n·2^n) 与空集的处理。"}],"works":[{"h":"宏参数不加括号导致优先级错乱","d":"#define SQUARE(x) xx，SQUARE(1+2) 展开为 1+21+2=5，而非 9。 每个参数与整体都加括号：#define SQUARE(x) ((x)(x))。"},{"h":"宏参数的多重求值副作用","d":"即便写成 ((x)(x))，SQUARE(x++) 中 x++ 仍会被求值两次，产生意料之外的多次自增。函数 f(x++) 只求值一次。 带副作用的实参或「像函数」的逻辑，改用 inline 函数或模板，保证单次求值与类型检查。"},{"h":"多语句宏未用 do-while(0) 包裹","d":"#define F() a(); b(); 用于 if (c) F(); else g(); 时，展开后 else 悬空编译失败。 用 do { ... } while(0) 把多语句包成单条复合语句，分号语义也正确。"},{"h":"头文件缺少守卫导致重定义","d":"同一头文件被多条包含路径间接包含多次，类/函数声明重复 → 编译报 redefinition。 每个头文件顶部加 #ifndef HEADER_H / #define HEADER_H / #endif，或与 #pragma once 并用。"},{"h":"#pragma once 的局限","d":"它依赖「同一物理文件」判重：符号链接、文件副本、不同包含路径可能让编译器误判为不同文件，守卫失效。 对强可移植性或多副本风险场景，优先传统 #ifndef 守卫；二者可并存。"},{"h":"宏名与变量名/类型名冲突","d":"宏是全局文本替换，若 #define max 之类覆盖了标准库或你自己用的名字，所有 max 都会被替换，引发诡异错误。 宏名用全大写 + 项目前缀（如 MYLIB_MAX）；避免定义过于通用的短名；头文件里的宏用完及时 #undef。"},{"h":"在头文件中写 using namespace std;","d":"头文件经 #include 被多处包含，using namespace std; 会把 std 名字注入所有包含者的全局命名空间，造成名字冲突且难以定位。 头文件中绝不放 using namespace；源文件里也尽量只 using 具体名字。"},{"h":"宏参数不加括号 → 优先级被重写","d":"cpp #define SQR(x) x x SQR(1 + 2) // 展开成 1 + 2 1 + 2 == 5，不是 9 宏是纯文本替换，运算符优先级由调用点决定，不会因为你「想的是先加再乘」而保护你。 每个参数和整体都加括号：#define SQR(x) ((x) (x))；能量化成 constexpr 函数/模板就别用宏。"}],"asks":[{"q":"宏和 inline 函数怎么选？各自适合什么场景？","a":"总原则：能用 inline/模板/constexpr 解决的，就不要写宏。区别如下： - 类型与求值：宏是预处理期的纯文本替换，无类型检查、参数可能多次求值（带副作用的实参会出错）；inline 函数是真正的函数，形参只求值一次、有类型检查、可重载、可设断点调试。 - 能力边界：宏能做的事函数做不到——字符串化 #、记号拼接 ##、条件编译相关的 __FILE__/__LINE__ 日志、#if…","fu":["为什么 SQUARE(x++) 会出错而 square(x++) 不会？","constexpr 函数能否完全取代对象宏常量？"],"tag":"通用/字节"},{"q":"#pragma once 有什么坑？它和传统头文件守卫（#ifndef 守卫）该选哪个？","a":"传统守卫靠宏名判重：第一次包含时宏未定义 → 定义宏并展开文件体；后续包含因宏已定义而跳过。它标准、可移植、不依赖文件路径。缺点是样板冗长，且守卫宏名必须全局唯一——若两个不同头文件撞名，会导致本该包含的内容被错误跳过。 #pragma once 靠物理文件身份判重：同一文件只展开一次，省样板、理论上更快。坑在于： 1. 非标准（虽主流编译器都支持）； 2. 若同一头文件通过不同路径（符号链接、副…","fu":["为什么守卫宏名冲突会「跳过」而非报错？","同一文件不同路径包含为什么会让 pragma once 失效？"],"tag":"通用/阿里"},{"q":"为什么多语句宏要用 do { ... } while(0) 包裹？还有别的方式吗？","a":"问题根源：宏是文本替换，多语句宏（如 a(); b();）展开后若直接用于 if (c) M(); else g();，会变成 if(c) a(); b(); else g();，else 与 if 不匹配 → 编译失败；即使用花括号 {a(); b();}，在 if(c) M(); 后面也会被误认为多了一条语句（多余分号问题），且在 if/else 链中仍可能出错。 do { ... } whi…","fu":["为什么不用裸的 { } 块？","do-while(0) 在运行期真的零开销吗？"],"tag":"通用/华为"}]},{"id":"cpp-ch15","subj":"cpp","title":"命名空间与模块化：namespace/inline namespace/C++20 模块","summary":"namespace 与 using；匿名命名空间；inline namespace 版本控制；ADL；C++20 module 替代头文件包含；避免using namespace std 进头文件。","concepts":[{"id":"cpp-ch15/01-namespace-basics","file":"01-namespace-basics.md","title":"01 · 命名空间基础：作用域、查找与 ADL","kind":"compare","secs":[{"h":"一、理论根基：命名空间是为了解决什么","s":"C 语言只有「全局 + 文件静态 + 块」三层作用域，项目一大就不可避免名字冲突——两个库都定义了 list、max、error。C++ 的 namespace 提供用户可控的命名作用域，把名字关进一个「名字盒子」，用 Namespac…","c":null},{"h":"二、实现机制：名字查找到底怎么走","s":"C++ 的名字解析分两条腿：","c":{"lang":"cpp","code":"namespace geom {\n    struct Point { int x, y; };\n    void draw(const Point&) { /* ... */ }\n}\nint main() {\n    geom::Point p{1, 2};\n    draw(p);   // 未限定，但因为实参 p 的类型在 geom，ADL 把 geom::draw 拉进来 → OK\n}"}},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例：眼见为实（见 examples/ex02-adl.md 对应 ex02）","s":"","c":{"lang":"cpp","code":"#include <iostream>\nnamespace lib {\n    struct Widget {};\n    void inspect(const Widget&) { std::cout << \"lib::inspect(Widget)\\n\"; }\n}\nvoid inspect(int) { std::cout << \"global::inspect(int)\\n\"; }\n\nint main() {\n    lib::Widget w;\n…"}}]},{"id":"cpp-ch15/02-anonymous-namespace","file":"02-anonymous-namespace.md","title":"02 · 匿名命名空间：内部链接与「翻译单元私有」","kind":"compare","secs":[{"h":"一、理论根基：从「外部链接」到「内部链接」","s":"C 时代用 static 把文件级函数/变量限制为内部链接（internal linkage）——即只在本翻译单元（.cpp）可见，不会被链接器暴露成全局符号。C++ 引入匿名命名空间（unnamed namespace）作为更优替代：","c":{"lang":"cpp","code":"namespace {\n    int helper() { return 42; }   // 内部链接：等价「static」语义\n}"}},{"h":"二、实现机制：编译器做了什么","s":"匿名命名空间在语义上等同于：","c":{"lang":"cpp","code":"namespace __unique_1234 { int x; }\nusing namespace __unique_1234;"}},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例（见 examples/ex03-anonymous.md 对应 ex03）","s":"","c":{"lang":"cpp","code":"#include <iostream>\nnamespace {\n    int secret = 7;        // 本 TU 私有\n}\nint main() {\n    std::cout << \"secret=\" << secret << '\\n';\n}"}}]},{"id":"cpp-ch15/03-inline-namespace","file":"03-inline-namespace.md","title":"03 · inline namespace：版本化、ABI 兼容与别名","kind":"compare","secs":[{"h":"一、理论根基：为什么需要「inline namespace」","s":"库的演进常面临两难：改了 API 想要新名字空间隔离（v1/v2），又不想让老用户每次都写 mylib::v2::foo。C++11 的 inline namespace 让某个命名空间「透明」——其内部的名字可被外层命名空间直接看到（…","c":{"lang":"cpp","code":"namespace mylib {\n    inline namespace v2 {\n        void f() { /* 新实现 */ }\n    }\n    namespace v1 {\n        void f() { /* 旧实现 */ }\n    }\n}\n// 调用方写 mylib::f() 默认选中 v2；需要时显式 mylib::v1::f()"}},{"h":"二、实现机制：透明性从何而来","s":"inline namespace 的名字在未限定查找时会自动「穿透」到外层命名空间——等价于编译器在外层「自动 using 了它」。因此：","c":null},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例（见 examples/ex04-inline-version.md 对应 e…","s":"","c":{"lang":"cpp","code":"#include <iostream>\nnamespace mylib {\n    inline namespace v2 { const char* who() { return \"v2\"; } }\n    namespace v1       { const char* who() { return \"v1\"; } }\n}\nint main() {\n    std::cout << mylib::who() << ' ' << mylib::v1::who() << '\\n';\n}"}}]},{"id":"cpp-ch15/04-modules-cpp20","file":"04-modules-cpp20.md","title":"04 · C++20 模块：import / export 与头文件文本包含的终结","kind":"compare","secs":[{"h":"一、理论根基：头文件到底有什么病","s":"传统 #include 是文本包含：预处理期把整个头文件原样拼进翻译单元。这带来三类顽疾：","c":null},{"h":"二、实现机制：import / export 怎么工作","s":"","c":{"lang":"cpp","code":"// math.ixx（模块接口单元，C++20）\nexport module math;\nexport int add(int a, int b) { return a + b; }\nexport namespace math { double pi = 3.14; }"}},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例（见 examples/ex09-module-vs-header.md 对应…","s":"","c":{"lang":"cpp","code":"// 本示例在单一 TU 内模拟「模块私有 vs 模块接口」的可见性思路：\n// 用未导出的匿名命名空间模拟模块内部实现，用命名空间模拟对外接口。\n#include <iostream>\nnamespace math_impl {            // 模拟「模块内部」：不 export\n    int slow_add(int a, int b) { return a + b; }\n}\nnamespace math {                 // 模拟「模块接口」：export 的符号\n    int add(int a, int b) { return math_impl::slow_add(a, b); }\n}\n…"}}]},{"id":"cpp-ch15/05-namespace-modules-practical-recipes","file":"05-namespace-modules-practical-recipes.md","title":"凯喵实战手记 · 命名空间与模块：链接错误的「寻根指南」","kind":"flow","secs":[{"h":"现场 1：命名空间不是「访问控制」，只是「防重名」","s":"命名空间把名字分组，避免不同库的同名符号冲突，但它不阻止别人访问，也不做权限控制。凯喵：真正的封装靠类和 static/匿名命名空间，命名空间只解决「名字撞车」。别指望它藏住实现细节。","c":{"lang":"cpp","code":"namespace math {\n    int add(int a, int b) { return a + b; }\n}\nmath::add(1, 2);"}},{"h":"现场 2：using namespace 在头文件里是灾难","s":"头文件里写 using namespace std;，所有包含它的源文件都被污染，可能和自己定义的同名符号冲突。凯喵的铁律：头文件绝不 using namespace，只在源文件或函数内部小范围使用，或者干脆用完整限定名。","c":null},{"h":"现场 3：匿名命名空间等价于「内部链接」","s":"匿名命名空间里的符号只在本翻译单元可见，等价于给每个符号加 static。凯喵：源文件里只想内部用的辅助函数、常量，放进匿名命名空间，既不污染外部链接，又比 static 更现代、更统一。","c":{"lang":"cpp","code":"namespace {\n    int helper(int x) { return x * 2; }  // 仅本文件可见\n}"}},{"h":"现场 4：匿名命名空间放进头文件会「每文件一份」","s":"匿名命名空间的定义在每个包含它的翻译单元里都是独立的。凯喵：把头文件里的类型放进匿名命名空间，每个源文件都会得到一份「不同的类型」，链接时可能莫名冲突或行为不一致。头文件里别用匿名命名空间。","c":null},{"h":"现场 5：内联命名空间做版本管理","s":"内联命名空间的成员会被「提升」到外层命名空间，可以一边保留 v1、v2，一边让用户默认访问最新版。凯喵：库做 ABI 版本演进时，内联命名空间是标准手法，既能保持源码兼容，又能区分不同版本的符号。","c":{"lang":"cpp","code":"namespace lib {\n    inline namespace v2 {\n        void f();   // 用户直接写 lib::f() 就能调用 v2\n    }\n}"}},{"h":"现场 6：inline namespace 不是「内联函数」","s":"名字里都有 inline，但内联命名空间和内联函数毫无关系。凯喵：前者是命名空间的版本机制，后者是链接与优化提示。初学者常把两者混为一谈，看到 inline namespace 就以为跟性能有关，其实完全无关。","c":null},{"h":"现场 7：嵌套命名空间的 C++17 简写","s":"namespace a::b::c {} 是 C++17 起的简写，等价于三层嵌套。凯喵：老代码里还常见 namespace a { namespace b { ... } } 的写法，读的时候知道它们是同一回事即可。简写更清爽，新代码…","c":null},{"h":"现场 8：ADL 让运算符找对命名空间","s":"参数依赖查找（ADL）会根据实参类型所在的命名空间去找函数，所以 std::cout << x 不需要写全限定。凯喵：自定义类型重载运算符时，把它放在类型所在的命名空间里，ADL 才能找到；放错地方就报「找不到匹配的 operator」…","c":{"lang":"cpp","code":"namespace geo {\n    struct Point { int x, y; };\n    std::ostream& operator<<(std::ostream& os, const Point& p) {\n        return os << \"(\" << p.x << \",\" << p.y << \")\";\n    }\n}"}},{"h":"现场 9：头文件守卫与 #pragma once","s":"传统用 #ifndef/#define/#endif 做包含守卫，现代编译器普遍支持 #pragma once。凯喵：两种都行，但别混用；#pragma once 更简洁，ifndef 可移植性更广。关键是每个头文件都要有，否则重复包含…","c":null},{"h":"现场 10：ODR：同一定义只能出现一次","s":"一个实体（函数、类、变量）在整个程序里只能有一份定义。凯喵：把非 inline 函数或全局变量定义在头文件里，被多个源文件包含就违反 ODR，链接报 multiple definition。头文件只放声明，定义放源文件，或用 inlin…","c":null},{"h":"现场 11：模块用 export 控制可见性","s":"C++20 模块里，只有被 export 的实体才对导入方可见，其余都是模块内部实现。凯喵：这比头文件的「全暴露」更干净，能真正隐藏实现细节、加快编译。但要注意：#include 进来的内容默认不导出，需要显式处理。","c":{"lang":"cpp","code":"export module math;\nexport int add(int a, int b) { return a + b; }\nint internal_helper() { return 0; }  // 不导出"}},{"h":"现场 12：模块与头文件的混用边界","s":"老代码大量用头文件，新代码想用模块，混用时最容易踩「同一实体既被 include 又被 import」。凯喵：迁移期用「头单元」过渡，把常用头文件包成模块再 import；不要一边 #include 一边 import 同一个东西，容易…","c":null},{"h":"现场 13：import <vector>; 是头单元，不是模块","s":"标准库目前多以「头单元」形式提供，import <vector>; 导入的是被模块化的头文件，语义上接近 #include <vector>，但不进全局宏空间。凯喵：这能减少宏污染和编译时间，但标准库模块化还在演进，跨编译器支持不一，生…","c":null},{"h":"现场 14：链接错误的排查顺序","s":"遇到 undefined reference，凯喵的顺序是：先确认声明与定义签名一致，再看定义所在源文件是否参与编译，然后看命名空间是否写错，最后看链接顺序与库是否缺失。按这个顺序走，绝大多数链接错误十分钟内能定位，而不是靠随机改代码碰…","c":null},{"h":"凯喵叮嘱：链接阶段的问题，八成在头文件","s":"最后叮嘱一句：遇到「重定义」「未定义引用」这类链接错误，先别急着改代码，先把头文件的边界检查一遍——有没有放非内联函数、有没有放全局变量、有没有把实现写进头文件、有没有漏包含守卫。凯喵的经验是，链接错误八成能在头文件这一层找到根，剩下两…","c":null},{"h":"🧑‍💻 程序员视角","s":"using namespace std; 写在头文件里，会污染每一个包含它的翻译单元，轻则名字冲突，重则选错重载——头文件里应只在函数内部用 using，或使用完整限定名。匿名命名空间等价于 static，给内部链接，但放进头文件会让每…","c":null},{"h":"🎓 博士生视角","s":"命名空间解决的是「名字查找与链接」两个层面的问题：它影响非限定查找的顺序（ADL 让参数类型所在命名空间参与查找），也影响符号的修饰名（mangling）从而决定链接行为。匿名命名空间与 static 的等价性来自「内部链接」这一语言机…","c":null},{"h":"📚 考研者视角","s":"面试与实战：","c":null}]}],"exams":[{"kind":"choice","q":"关于命名空间与 ADL，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"命名空间改变符号的外部链接属性"},{"k":"B","t":"函数调用实参为用户自定义类型时，编译器会把该类型所在命名空间也纳入候选（ADL）"},{"k":"C","t":"匿名命名空间的符号具有外部链接，可跨翻译单元共享"},{"k":"D","t":"头文件中写 using namespace std; 是推荐做法"}],"ans":"B","why":"ADL 会依据实参类型把对应命名空间拉入候选集；命名空间本身不改变链接（匿名除外）；匿名命名空间是内部链接；头文件禁用 using namespace。"},{"kind":"fix_error","q":"修复头文件中的 using namespace 污染","stem":"某头文件 util.h 直接写了 using namespace std;，导致包含它的所有翻译单元都把 std 名字暴露出来，与项目里的 count/equal 等名字冲突。请写出「头文件里正确的写法」替换它。","opts":[],"ans":"// 头文件中：禁用 using namespace，改用限定名或点名引入 #include <vector> std::vector<int> make_vec(); // 用限定名 std::vector // 或仅引入需要的名字： // using std::size_t;","why":"头文件应避免整桶引入；用 std:: 限定或局部 using 声明（点名）即可，且不污染包含方作用域。"},{"kind":"output","q":"读代码写输出（ADL 选中）","stem":"cpp #include <iostream> namespace lib { struct W {}; void f(const W&) { std::cout << \"lib::f\\n\"; } } void f(int) { std::cout << \"int::f\\n\"; } int main() { lib::W w; f(w); }","opts":[],"ans":"lib::f","why":"实参 w 的类型在 lib，ADL 把 lib::f 拉入候选并因更匹配（W 参数）而胜出。"},{"kind":"coding","q":"用 inline namespace 实现库版本切换","stem":"实现一个 mylib，用 inline namespace 默认导出 v2 的 greet()（返回 『v2』），并保留 v1 的 greet()（返回 『v1』）可通过 mylib::v1::greet() 显式调用。主函数输出 mylib::greet() 与 mylib::v1::greet()。","opts":[],"ans":"#include <iostream> namespace mylib { inline namespace v2 { const char greet() { return \"v2\"; } } namespace v1 { const char greet() { return \"v1\"; } } } int mai…","why":"inline 让 v2 透明穿透到 mylib，故 mylib::greet 命中 v2；v1 需显式限定。注意返回字符串用转义双引号 \"v2\"。"},{"kind":"explain","q":"匿名命名空间与 static 的区别与联系","stem":"解释：匿名命名空间 namespace { ... } 与给变量/函数加 static 在链接属性上有何相同与不同？为何现代 C++ 更推荐匿名命名空间？","opts":[],"ans":"两者都赋予内部链接（仅本翻译单元可见）。区别在于：匿名命名空间可作用于类型与一组名字，且语义统一；static 在 C++ 中用于类成员时是「静态成员」语义，易混淆。现代 C++ 推荐匿名命名空间来替代文件级 static，表达「本 TU 私有」更清晰。","why":"核心是内部链接语义一致；匿名命名空间适用范围更广、意图更明确，且避免 static 多义。"},{"kind":"design","q":"用命名空间与模块化组织一个多模块库","stem":"设计一个分为「核心 core / 算法 algo / IO io」三层的库接口，要求：用命名空间分层、用 inline namespace 做版本化、说明头文件与 C++20 模块如何取舍（详见 external_url 仓库的模块化实践，不在此复述）。","opts":[],"ans":"// 分层：namespace mylib { inline namespace v1 { namespace core {...} namespace algo {...} namespace io {...} } } // 迁移到模块：export module mylib; export namespace my…","why":"核心是「按职责分层命名空间 + inline 版本默认导出 + 模块迁移时整库切换避免 ODR」，与 LLVM 的模块化思路一致。"}],"works":[{"h":"头文件里写 using namespace std; 污染全局","d":"在 .h 中 using namespace std; 会把整个 std 的名字注入每一个包含该头的翻译单元，极易与用户/第三方名字冲突，且名字冲突可能在远离头文件处才爆发，极难定位。 头文件中只用限定名（std::vector）或局部 using 声明（如只 using std::size_t;）；using namespace 仅…"},{"h":"ADL 意外选中别处的重载","d":"当函数调用实参含用户自定义类型，编译器会把该类型所在命名空间也拉进候选集。若你在本地定义了同名函数，却因实参类型在别处而被「别人家」的重载抢先匹配，结果出乎意料。 调用库函数时尽量显式限定（ns::foo(x)）；或为自定义类型提供同命名空间的友元/自由函数，让 ADL 可控。"},{"h":"匿名命名空间误当「全局可见」","d":"namespace { ... } 内的符号是内部链接，只在当前 TU 存在；想跨文件共享却放进匿名命名空间，链接期会报「未定义引用」，或各 TU 各有一份、互不相等。 仅本文件私有逻辑才用匿名命名空间；跨 TU 共享必须放头文件 + inline/普通定义。"},{"h":"using namespace std; 进头文件（同一坑的极端版）","d":"不仅污染，还可能让某次升级 std 新增同名模板后悄然改变你代码的重载决议，导致「没改代码却编译不过/行为变了」。 严守「头文件禁用 using namespace」铁律；代码评审把这当红线。"},{"h":"模块与头文件混用导致 ODR 问题","d":"同一实体（函数/变量）若既以 #include 头文件形式、又以模块 export 形式各定义一次，会触发单一定义规则（ODR）违反，链接期或运行期出现重复符号/未定义行为。 一个符号「只走一边」：要么全部进模块 export，要么全部走头文件 + inline；迁移时整库切换，避免半模块半头。"},{"h":"using 指令掩盖了名字来源，制造「幽灵冲突」","d":"using namespace A; using namespace B; 后，A::x 与 B::x 同时存在且都是候选，后续看似无害的 x 会触发歧义错误，且错误位置远离引入点。 优先 using A::x;（点名引入，可快速暴露冲突）；多命名空间并存时尽量保留限定名。"},{"h":"在头文件里写 using namespace std;","d":"它会把「包含该头文件的所有翻译单元」的 std 全部打开，count / distance / size / data 这类同名函数立刻出现二义性，而且报错位置与包含顺序有关，极难复现。 头文件里用完全限定名或只引入单个名字（using std::string;）；using namespace 只放在 .cpp 的局部作用域或函数体…"},{"h":"把类型定义在匿名 namespace 里却放进头文件","d":"匿名 namespace 的实质是「每个翻译单元一份唯一命名」，同一头文件被多个 TU 包含会得到互不相同的类型。一旦被 inline 函数或模板跨 TU 使用，就违反 ODR，链接期可能静默选中其中一份，行为随构建顺序变化。 头文件里用具名 namespace（必要时 inline namespace）或 inline 变量/函数…"}],"asks":[{"q":"ADL（参数依赖查找）有什么用，又有什么坑？","a":"用处：让运算符与泛型库「跟着类型走」。例如 std::swap(a,b)、流输出 operator<<、自定义类型的 ==，只要实参类型在对应命名空间，无需 using 即可被选中，这是泛型代码能统一调用用户特化版本的基础。 坑：未限定调用时，实参类型所在命名空间的自由函数会绕过本地同名函数被优先匹配，造成「调用了意想不到的重载」；在泛型模板里尤甚（模板参数类型未知，ADL 行为更难预测）。 应对…","fu":["为什么 std 的 swap 要配合 using std::swap 才能正确选中特化？","模板里调用未限定函数时，ADL 与未限定查找的优先级如何？"],"tag":"通用/字节"},{"q":"C++20 模块（module）能解决传统头文件的哪些问题？代价是什么？","a":"解决三件事：1) 编译时间：头文件是文本包含，声明在每个翻译单元被重复解析；模块编译成 BMI，只编译一次按符号导入。2) 宏泄漏：头文件的 #define 无差别污染后续代码；模块不导出宏。3) 接口/实现边界与 ODR：模块首次在语言层面提供「未 export 即私有」，且按模块单元定义，缓解头文件多包含导致的 ODR 压力。 代价/边界：纯 C 接口仍需头文件；工具链与构建系统（CMake）…","fu":["import <header>; 和 #include 在宏泄漏上有何区别？","模块如何解决 ODR，头文件为什么做不到？"],"tag":"腾讯/美团"},{"q":"inline namespace 如何实现库的版本化与 ABI 兼容？","a":"把当前默认版本标为 inline namespace，其名字会透明穿透到外层命名空间——调用方写 mylib::f() 即选中该版本，且 mangling 中版本前缀被抹平，使得二进制符号名稳定（ABI 兼容：老二进制无需重编）。 破坏性变更则新建非 inline 的 v3，保留旧 v2 不被 inline，让旧符号继续存在。 对比：匿名命名空间是内部链接（每 TU 一份），inline 是外部链…","fu":["inline namespace 的符号 mangling 与普通命名空间有何不同？","为什么破坏性 API 变更不能继续用 inline？"],"tag":"通用/阿里"}]},{"id":"cpp-ch16","subj":"cpp","title":"并发与多线程：thread/mutex/atomic/async","summary":"std::thread 创建与 join/detach；互斥量 mutex/lock_guard；原子操作 atomic；条件变量；std::async 与 future；数据竞争与死锁规避。","concepts":[{"id":"cpp-ch16/01-thread-basics","file":"01-thread-basics.md","title":"01 · std::thread：启动、join/detach 与数据竞争","kind":"compare","secs":[{"h":"一、理论根基：线程到底是什么，为什么要它","s":"线程是操作系统调度的最小执行单元，同一进程内多个线程共享地址空间（堆、全局、打开的文件），但各有独立栈。多核时代，线程是榨干硬件并行度的唯一手段。","c":null},{"h":"二、实现机制：std::thread 背后发生了什么","s":"","c":{"lang":"cpp","code":"std::thread t(f, arg);   // 1) 构造即启动（不像 pthread_create 分开）；2) 把 arg 按值拷贝进线程\nt.join();                // 阻塞当前线程，等待 t 结束并回收资源\n// 或 t.detach();        // 脱离：t 在后台自生自灭，结束后由 runtime 回收"}},{"h":"三、工程实践：程序员视角的取舍","s":"","c":null},{"h":"四、边界与陷阱","s":"","c":null},{"h":"五、可运行示例（见 examples/ex01-thread-join.md 对应 ex01…","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <thread>\n#include <vector>\n\nint main() {\n    std::vector<std::thread> ts;\n    for (int i = 0; i < 3; ++i)\n        ts.emplace_back([i]{ /* 各自独立工作，无共享 */ });\n    for (auto& t : ts) t.join();   // 必须 join，否则 terminate\n…"}}]},{"id":"cpp-ch16/02-mutex-raii","file":"02-mutex-raii.md","title":"02 · mutex 与 RAII 锁：lock_guard / unique_lock / scoped_lock","kind":"flow","secs":[{"h":"一、理论根基：互斥为何能消除数据竞争","s":"互斥量（mutex）把「读-改-写」临界区变成串行：同一时刻只有一个线程持有锁，从而在被保护的操作之间建立 happens-before（释放锁 happens-before 后续获取锁）。数据竞争因此消除。","c":null},{"h":"二、实现机制：三种 RAII 锁的差异","s":"","c":null},{"h":"三、死锁：四个必要条件与系统性避免","s":"死锁需同时满足：互斥、持有并等待、不可剥夺、循环等待。","c":null},{"h":"四、可运行示例（见 examples/ex03-scoped-lock.md 对应 ex03…","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <mutex>\n#include <thread>\n\nstd::mutex m1, m2;\n\nvoid worker() {\n    std::scoped_lock lk(m1, m2);   // 一次性安全锁两把，不死锁\n}\n…"}}]},{"id":"cpp-ch16/03-atomic-memory-order","file":"03-atomic-memory-order.md","title":"03 · atomic 与内存序：无锁编程的边界","kind":"stack","secs":[{"h":"一、理论根基：原子操作解决什么","s":"std::atomic<T> 保证对它的操作是不可分割的（读-改-写一步完成，不被其他线程插入），从而无数据竞争。它比 mutex 轻：通常是单条 CPU 指令（lock xadd 等），且不会阻塞线程。","c":null},{"h":"二、实现机制：三种内存序","s":"1. memory_order_relaxed：只保证原子性，不保证顺序/可见性——只适合「纯计数器」，不能用来同步其他内存。","c":null},{"h":"三、无锁编程的边界","s":"","c":null},{"h":"四、可运行示例（见 examples/ex05-atomic-fetch-add.md 对应…","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <atomic>\n#include <thread>\n#include <vector>\n\nstd::atomic<int> cnt{0};\n\nint main() {\n    std::vector<std::thread> ts;\n…"}}]},{"id":"cpp-ch16/04-condition-variable","file":"04-condition-variable.md","title":"04 · 条件变量与虚假唤醒","kind":"flow","secs":[{"h":"一、理论根基：为什么需要条件变量","s":"mutex 只能「互斥」，不能「等待某条件成立」。条件变量（condition_variable）让线程阻塞等待直到被通知「条件可能变了」，配合 mutex 实现「生产者-消费者」「信号量」等同步。","c":null},{"h":"二、实现机制：wait 的三件事","s":"wait(lk, pred) 原子地做：释放锁 → 阻塞 → 被唤醒后重新加锁 → 检查 pred。","c":{"lang":"cpp","code":"std::unique_lock<std::mutex> lk(m);\ncv.wait(lk, []{ return ready; });   // 等价：while(!ready){ cv.wait(lk); }"}},{"h":"三、工程实践","s":"","c":null},{"h":"四、可运行示例（见 examples/ex04-condvar-pc.md 对应 ex04）","s":"","c":{"lang":"cpp","code":"// 生产者-消费者：生产者放入 5 个，消费者取 5 个，最终汇总总数（确定性）\n#include <iostream>\n#include <mutex>\n#include <condition_variable>\n#include <queue>\n#include <thread>\n\nstd::mutex m; std::condition_variable cv; std::queue<int> q; bool done = false;\nint consumed = 0;\n…"}}]},{"id":"cpp-ch16/05-async-future-pool-jthread","file":"05-async-future-pool-jthread.md","title":"05 · async / future / 线程池 与 jthread","kind":"timeline","secs":[{"h":"一、理论根基：高层并发抽象","s":"std::async 把「跑一个任务 + 取结果」封装成 future，比手动 thread+共享变量优雅；promise/future 是一次性单向通道，用来在线程间传递值或异常。","c":null},{"h":"二、实现机制：async 的启动策略","s":"","c":{"lang":"cpp","code":"std::future<int> f = std::async(std::launch::async, task);  // 真开新线程\n// std::async(std::launch::deferred, task);                  // 惰性：get() 时才在调用线程同步执行\n// std::async(task);                                         // 默认 = async|deferred，由实现决定！"}},{"h":"三、线程池：为什么必要","s":"每次 std::thread 创建都有内核开销（栈分配、调度注册）；高并发短任务场景下，「来一个建一个线程」成本高且易耗尽资源。线程池预先建 N 个常驻线程，任务提交到队列，线程复用——控制并发度、降开销。","c":null},{"h":"四、可运行示例（见 examples/ex06-async-future.md、ex07-j…","s":"","c":{"lang":"cpp","code":"#include <iostream>\n#include <future>\n\nint main() {\n    auto f = std::async(std::launch::async, []{ return 6 * 7; });\n    std::cout << \"answer=\" << f.get() << '\\n';   // 阻塞取结果，异常也会在此重抛\n}"}}]},{"id":"cpp-ch16/06-concurrency-practical-recipes","file":"06-concurrency-practical-recipes.md","title":"凯喵实战手记 · C++ 并发：那些只在压力下才现形的 Bug","kind":"flow","secs":[{"h":"现场 1：joinable 线程析构直接 terminate","s":"创建了 std::thread 却没有 join() 或 detach()，线程对象析构时如果仍是 joinable，程序直接调用 std::terminate。这是 C++ 并发最经典的「程序莫名退出」。凯喵的规矩：线程对象要么交给…","c":{"lang":"cpp","code":"std::thread t(work);\nt.join();   // 或者 t.detach()，二选一，别都不做"}},{"h":"现场 2：detach 后的对象生命周期","s":"detach() 让线程脱离管理，但如果它捕获了局部变量的引用，函数返回后引用悬垂，线程读写的是垃圾内存。凯喵见过太多「detach 后 crash」。正确做法：要么传值捕获，要么用 shared_ptr 共享所有权，要么干脆别 det…","c":null},{"h":"现场 3：mutex 忘了 unlock 的死锁","s":"手写 lock()/unlock() 时，中途 return 或抛异常就漏掉解锁，下一次同线程再锁就是死锁。凯喵：一律用 std::lock_guard 或 std::unique_lock，让 RAII 保证解锁，永远不手写配对。这一…","c":{"lang":"cpp","code":"{\n    std::lock_guard<std::mutex> lk(m);\n    // 离开作用域自动解锁\n}"}},{"h":"现场 4：两个锁的加锁顺序不一致","s":"线程 A 先锁 m1 再锁 m2，线程 B 先锁 m2 再锁 m1，双方各持一把等对方，死锁。凯喵的修法：全局约定加锁顺序，或者用 std::scoped_lock 一次锁多把（内部用死锁避免算法）。只要涉及多把锁，顺序就是纪律。","c":{"lang":"cpp","code":"std::scoped_lock lk(m1, m2);   // 一次锁两把，避免顺序死锁"}},{"h":"现场 5：条件变量必须配谓词，防虚假唤醒","s":"cv.wait(lk) 可能被虚假唤醒，醒来时条件未必满足。凯喵：永远写成 cv.wait(lk, [&]{ return ready; })，带谓词的版本会在唤醒后重新检查，避免「醒了但没数据」的经典 Bug。这是条件变量的正确姿势…","c":{"lang":"cpp","code":"std::unique_lock<std::mutex> lk(m);\ncv.wait(lk, [&]{ return !queue.empty(); });"}},{"h":"现场 6：忘记 notify 导致永久等待","s":"改了共享状态却忘了 cv.notify_one()/notify_all()，等待方永远睡着。凯喵的现场经验：把「改状态」和「通知」当成一个原子操作来写，改完立刻通知，别让它们分散在代码两端。等待方超时机制可以作为兜底，但不能替代正确通…","c":null},{"h":"现场 7：atomic 不等于「整段线程安全」","s":"std::atomic<int> 保证单个变量的读写原子，但多个原子变量的组合操作并不原子。凯喵见过「两个 atomic 标志位一起判断」的代码，以为安全，其实中间状态能被别的线程看到。多变量需要一致时，用锁保护整段；单变量计数才用 a…","c":{"lang":"cpp","code":"// 错误：两个 atomic 的组合不原子\nif (a.load() && b.load()) { ... }"}},{"h":"现场 8：内存序用错，编译器重排让你怀疑人生","s":"默认的 seq_cst 最安全但最慢，relaxed 最快但不保证顺序。凯喵：初学者一律先用默认顺序，确认无竞争后再考虑放宽；需要「写后读可见」时用 release/acquire 配对。凭直觉乱写内存序，是并发 Bug 的高发区。","c":{"lang":"cpp","code":"flag.store(true, std::memory_order_release);\nwhile (!flag.load(std::memory_order_acquire)) {}"}},{"h":"现场 9：伪共享让多核性能骤降","s":"两个线程频繁写同一缓存行里的不同变量，会导致缓存行来回失效，性能比单线程还差。凯喵：高频写的计数器之间加填充，或用 alignas(64) 让它们落在不同缓存行。这个坑不报错，只表现为「多核没加速」。","c":{"lang":"cpp","code":"struct alignas(64) PaddedCounter { std::atomic<long> v{0}; };"}},{"h":"现场 10：future 的异常被静默吞掉","s":"std::async 返回的 future 如果抛了异常，只有在你调用 get() 时才重新抛出；不 get 就永远看不到。凯喵：异步任务要么 get 取结果，要么显式处理异常，别 fire-and-forget 后不管。否则线上出错你…","c":null},{"h":"现场 11：线程池任务里的引用捕获","s":"把任务丢进线程池时用 [&] 捕获局部变量，任务真正执行时局部变量可能已经销毁。凯喵：线程池任务一律按值捕获或 shared_ptr 捕获，绝不用引用捕获栈上对象。这是「任务延迟执行」带来的生命周期错配。","c":null},{"h":"现场 12：jthread 的自动 join 与停止令牌","s":"C++20 的 std::jthread 析构时自动请求停止并 join，比 std::thread 安全得多。凯喵：新项目优先用 jthread 配合 stop_token，把「停止」变成协作式协议，避免粗暴 detach 带来的悬垂…","c":{"lang":"cpp","code":"std::jthread t([](std::stop_token st){\n    while (!st.stop_requested()) { /* work */ }\n});"}},{"h":"现场 13：锁的粒度：太粗慢、太细乱","s":"锁保护的范围太大，并发度低；太小，容易漏保护共享数据。凯喵的经验：先按「数据」划分锁，同一份数据用同一把锁，别让一把锁管太多不相关的东西；优化时再用性能工具确认热点，而不是拍脑袋拆锁。","c":null},{"h":"现场 14：用工具而不是肉眼找竞争","s":"数据竞争靠看代码很难稳，凯喵的建议是上 ThreadSanitizer，跑一遍压测，它会直接告诉你哪两行发生了竞争。与其在线上猜，不如在开发阶段让工具替你把关。并发正确性，工具永远比直觉可靠。","c":null},{"h":"凯喵叮嘱：把并发当架构问题，而不是语法问题","s":"最后说三句工程纪律。第一，任何共享数据都要问自己「谁写、谁读、用什么保护」，答不上来就先加锁，别赌编译器和处理器不重排。第二，锁的临界区尽量短，文件读写、日志、回调一律挪到锁外，否则并发度会被一把锁吃干。第三，上线前跑一遍线程检测工具…","c":null},{"h":"🧑‍💻 程序员视角","s":"std::thread 在析构时若仍 joinable 会直接 terminate——必须显式 join 或 detach，或包一层 RAII 的 jthread（C++20）。detach 后的线程若捕获了局部对象的引用，对象销毁后就…","c":null},{"h":"🎓 博士生视角","s":"C++ 内存模型定义了「先行发生」（happens-before）关系：没有同步的跨线程读写是数据竞争（UB），mutex、atomic、condition_variable 建立同步边。六种内存序中，seq_cst 最强最直观，rel…","c":null},{"h":"📚 考研者视角","s":"面试必问：","c":null}]}],"exams":[{"kind":"choice","q":"关于 std::thread 与数据竞争，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"std::thread 析构时若仍 joinable 会自动后台运行"},{"k":"B","t":"没有同步原语的两个线程访问同一变量，读写顺序由编译器保证一致"},{"k":"C","t":"counter++ 在多线程下可能因读-改-写非原子而丢失更新"},{"k":"D","t":"volatile 能提供线程间的原子性与 happens-before"}],"ans":"C","why":"counter++ 非原子；thread 析构仍 joinable 会 terminate；无同步即数据竞争（UB）；volatile 不提供同步语义。"},{"kind":"fix_error","q":"修复两把锁顺序不一致导致的死锁","stem":"下面代码两线程以相反顺序加锁 m1/m2，可能死锁。请用 std::scoped_lock（或 std::lock）一次性安全获取两把锁来修复： cpp std::mutex m1, m2; void worker_a() { std::lock_guard<std::mutex> a(m1); std::lock_guard<std::mutex> b(m2); / ... / } void w…","opts":[],"ans":"std::mutex m1, m2; void worker() { std::scoped_lock lk(m1, m2); // 一次性锁两把，标准保证不死锁 // ... }","why":"scoped_lock/std::lock 内部用回退算法一次性获取多锁，从根上消除「循环等待」，无需程序员手动约定锁序。"},{"kind":"output","q":"读代码写输出（atomic 确定性总数）","stem":"cpp #include <iostream> #include <atomic> #include <thread> #include <vector> std::atomic<int> c{0}; int main() { std::vector<std::thread> v; for(int i=0;i<2;++i) v.emplace_back([]{ for(int k=0;k<500;…","opts":[],"ans":"c=1000","why":"原子 fetch_add 保证总数不丢，2500=1000 确定性。"},{"kind":"coding","q":"实现一个线程安全的计数器","stem":"用 std::mutex + std::lock_guard 实现一个 SafeCounter，支持 increment()（线程安全自增）与 get()（取当前值）。启动 4 个线程各自增 2500 次，主线程 join 后输出总数应为 10000。","opts":[],"ans":"#include <iostream> #include <mutex> #include <thread> #include <vector> struct SafeCounter { std::mutex m; long v = 0; void increment() { std::lock_guard<std::…","why":"lock_guard 在作用域进出时自动加解锁，临界区受保护，总数确定性为 10000。"},{"kind":"explain","q":"volatile 与 std::atomic 的区别","stem":"解释：为什么 C++ 里 volatile 不能用来做线程同步？std::atomic 提供了哪些 volatile 没有的保证？","opts":[],"ans":"volatile 只禁止编译器对变量的优化重排与寄存器缓存，不提供原子性、也不建立线程间 happens-before。atomic 保证操作不可分割（无撕裂）、无数据竞争，并可通过内存序建立同步关系。两者目的完全不同，切勿混用。","why":"核心是「volatile 管编译器优化，atomic 管并发正确性」；C++ 的 volatile 不等同于 Java 的 volatile。"},{"kind":"design","q":"LeetCode 1114 · 按序打印","stem":"三个线程分别打印 first / second / third，要求严格按 first→second→third 顺序各执行一次。请用互斥量或条件变量（或信号量）控制执行序（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 思路：用两个 atomic<bool> 标志或 condition_variable 做「门闩」： // second 等待 first 完成；third 等待 second 完成。主线程 join 三个线程。 // 具体实现见 external_url 原题要求。","why":"核心是「用同步原语把并行执行强制串成确定顺序」；条件变量需带谓词防虚假唤醒。"},{"kind":"design","q":"LeetCode 1226 · 哲学家进餐","stem":"5 位哲学家交替「思考」与「进餐」，每人需同时拿左右两根筷子。请用资源分级（给筷子编号、总是先拿小号再拿大号）或 std::lock 避免死锁（详见 external_url，不在此复述题面）。","opts":[],"ans":"// 思路：把 5 根筷子编号为 0..4；每位哲学家总是先锁编号小的筷子、再锁大的， // 破坏循环等待从而避免死锁；或用 std::scoped_lock 一次性取两根。 // 具体实现见 external_url 原题要求。","why":"经典死锁案例；固定锁序 / 一次性取多锁是系统性避免死锁的标准解法。"}],"works":[{"h":"忘记 join/detach 导致 terminate","d":"std::thread 析构时若仍 joinable()（既没 join 也没 detach），标准规定调用 std::terminate() 直接崩溃。常见诱因：线程对象在作用域末尾析构前忘了处理。 启动线程后立刻规划生命周期：要么 join，要么 detach（并确保引用对象活得够久）；或直接用 std::jthread（析构自动…"},{"h":"按值捕获/传引用导致悬垂","d":"std::thread t([&]{ use(local); }); 或把局部变量引用传进线程，若线程晚于 local 析构才运行，访问已销毁对象是 UB；async 的 lambda 同理。 用 std::ref 时需确保生命周期覆盖线程；更稳妥是按值捕获或 std::move 所有权（如 shared_ptr）。"},{"h":"死锁：两把锁顺序不一致","d":"线程 A 先锁 m1 再锁 m2，线程 B 先锁 m2 再锁 m1，形成循环等待，双双卡死。 所有线程按同一顺序加锁；或用 std::lock(m1, m2) / std::scoped_lock（一次性安全获取多锁，标准保证不死锁）。"},{"h":"volatile 误当同步原语","d":"volatile 只禁止编译器优化重排/缓存到寄存器，不提供线程间原子性与 happens-before，不能替代 atomic/mutex。在 C++ 里 volatile 不等于 Java 的 volatile。 多线程共享变量一律用 std::atomic 或 mutex 保护；volatile 只用于内存映射 IO 等场景。"},{"h":"condition_variable 未用谓词导致虚假唤醒 bug","d":"cv.wait(lk); 醒来后不验证条件就继续，一旦遭遇虚假唤醒或「被 notify 但条件仍未真」，就读到未就绪状态 → 逻辑错乱。 永远用带谓词的 cv.wait(lk, pred)，或 while(!pred) cv.wait(lk);。"},{"h":"数据竞争：未加保护地 ++ 共享计数","d":"counter++ 是「读-改-写」三步，非原子；多线程并发会丢失更新，结果不确定（每次运行可能不同）。 用 std::atomic<int> 的 fetch_add，或用 mutex 保护临界区。"},{"h":"std::async 默认策略的意外同步执行","d":"std::async(task) 默认策略是 async | deferred，实现可能选择 deferred——get() 时就在调用线程同步执行，根本没有并行。依赖并行提速的代码会「看起来没并发」。 需要真并行时显式写 std::async(std::launch::async, task)。"},{"h":"std::thread 析构时仍 joinable → 直接 std::terminate","d":"线程对象析构前若既没 join() 也没 detach()，标准要求调用 std::terminate()——程序立刻终止，抛不出也捕不到任何异常，栈上清理逻辑全部跳过。 用 RAII 包装线程（C++20 std::jthread 析构自动 join）；每个 thread 变量都要有明确归宿，不要「创建后就忘」。"}],"asks":[{"q":"内存序 relaxed 和 seq_cst 差在哪？什么时候该用 relaxed？","a":"seq_cst（默认）：对所有原子操作建立单一全局顺序，最强、最易推理，但可能插入内存屏障、刷 store buffer，开销最高。 relaxed：只保证单个原子变量自身的原子性，不保证跨变量的顺序与跨线程的可见性顺序——适合「纯计数器/统计」，不能用来同步其他内存。 acquire/release：介于两者之间，建立成对的同步关系（release 前的写对 acquire 后可见），是构建无锁…","fu":["为什么 relaxed 计数器结果仍然确定，但关联数据会不一致？","CAS（compare_exchange）通常配合哪种内存序？"],"tag":"通用/字节"},{"q":"死锁怎么系统性地避免？给出具体手段。","a":"死锁需同时满足四条件：互斥、持有并等待、不可剥夺、循环等待。破坏任一即可避免，工程上最常用： 1. 固定锁序：所有线程按同一顺序获取多把锁，破坏循环等待（如给锁编号，总是先小后大）。 2. 一次性取多锁：用 std::lock(m1,m2) 或 std::scoped_lock，标准内部回退算法保证不死锁。 3. 超时获取：try_lock_for，拿不到就释放已持有的、退避重试，避免无限等待…","fu":["std::lock 内部如何做到不死锁？","哲学家进餐问题除了锁序还有什么解法（如仲裁者）？"],"tag":"腾讯/阿里"},{"q":"std::async 的默认启动策略有什么坑？为什么强调显式 std::launch::async？","a":"std::async(f) 默认策略是 std::launch::async | std::launch::deferred，由实现自行选择。实现可能选 deferred：此时任务不在新线程跑，而是等到你 get() 时在调用线程同步执行——于是「本想并行加速」的代码实际是串行的，且若调用线程自己也被阻塞，还可能和预期完全相反。 强调显式 std::launch::async 才能确保「真开新线程…","fu":["deferred 策略在什么场景下反而有用？","async 返回 future 的生命周期与任务线程如何绑定？"],"tag":"美团/通用"},{"q":"条件变量的虚假唤醒是什么？为什么必须带谓词？","a":"虚假唤醒：即使没有线程调用 notify_，等待的线程也可能被系统/实现唤醒（pthread 规范允许）。若只写 cv.wait(lk); 醒来后不验证条件就继续，就会在「条件其实还没成立」时错误推进。 必须带谓词：cv.wait(lk, pred) 内部等价 while(!pred) wait(lk);——每次唤醒都重新检查条件，把「虚假唤醒」和「被 notify 但条件仍假」一并挡在门外。谓词…","fu":["notify_one 和 notify_all 分别在什么场景用？","为什么修改谓词与 notify 要放在同一把锁下？"],"tag":"通用/百度"}]},{"id":"cpp-ch17","subj":"cpp","title":"元编程与类型萃取：type_traits/constexpr/SFINAE/concept","summary":"编译期计算 constexpr；type_traits 与 enable_if；SFINAE；C++20 concept 与 requires；编译期 if；traits 类设计。","concepts":[{"id":"cpp-ch17/01-type-traits-specialization","file":"01-type-traits-specialization.md","title":"01 · 类型萃取 type_traits 与模板特化/偏特化","kind":"flow","secs":[{"h":"一、<type_traits>：编译期的「类型查询与变换」","s":"<type_traits> 提供一组编译期常量/类型别名，用于在编译期询问或变换类型。","c":{"lang":"cpp","code":"static_assert(std::is_same_v<std::remove_reference_t<int&>, int>);\nstatic_assert(std::is_same_v<std::decay_t<int[3]>, int*>);\nstatic_assert(std::is_destructible_v<int>);"}},{"h":"二、模板特化与偏特化","s":"特化允许为特定类型定制实现：","c":null},{"h":"三、is_destructible 与「类型是否可销毁」","s":"is_destructible_v<T> 在编译期回答「T 的对象能否被销毁」（析构函数可访问且未被删除）。","c":{"lang":"cpp","code":"struct NoDtor { ~NoDtor() = delete; };\nstatic_assert(std::is_destructible_v<int>);\nstatic_assert(!std::is_destructible_v<NoDtor>);"}}]},{"id":"cpp-ch17/02-constexpr-ifconstexpr","file":"02-constexpr-ifconstexpr.md","title":"02 · constexpr 编译期计算 与 if constexpr 分支裁剪","kind":"flow","secs":[{"h":"一、constexpr：把计算搬进编译期","s":"constexpr 函数/变量表示「可以在编译期求值」。编译期计算带来：零运行时开销、可用于需要编译期常量的语境（数组大小、static_assert、模板非类型参数）。","c":{"lang":"cpp","code":"constexpr int fib(int n) {\n    return n <= 1 ? n : fib(n - 1) + fib(n - 2);\n}\nstatic_assert(fib(10) == 55);   // 证明计算发生在编译期"}},{"h":"二、if constexpr：模板内的编译期分支","s":"if constexpr(cond) 中 cond 必须是编译期 bool 常量；不满足的分支不会被实例化，因此可以对不适用类型写「看似非法实则被裁剪」的代码。","c":{"lang":"cpp","code":"template <typename T>\nvoid log(T v) {\n    if constexpr (std::is_pointer_v<T>)\n        std::cout << *v;     // 仅当 T 是指针才实例化\n    else\n        std::cout << v;\n}"}},{"h":"三、static_assert 与编译期契约","s":"static_assert(常量表达式, 可选消息) 在编译期检查；C++17 起消息可省。它常用于给模板加「前置约束」，把难懂的实例化错误转成人话。","c":null}]},{"id":"cpp-ch17/03-sfinae-enableif-concept","file":"03-sfinae-enableif-concept.md","title":"03 · SFINAE / enable_if 与 C++20 concept","kind":"flow","secs":[{"h":"一、SFINAE：替换失败不是错误","s":"SFINAE（Substitution Failure Is Not An Error）指：在模板实参替换过程中发生的失败不视为硬错误，而是简单地把该模板从重载候选集中移除。利用这一点，可以「按类型特征挑选重载」。","c":{"lang":"cpp","code":"template <typename T>\nstd::enable_if_t<std::is_integral_v<T>, int> dispatch(T) { return 1; }\ntemplate <typename T>\nstd::enable_if_t<!std::is_integral_v<T>, int> dispatch(T) { return 2; }"}},{"h":"二、C++20 concept：可读的约束","s":"concept 把「类型必须满足的一组要求」命名并复用；requires 子句直接表达约束，重载决议时约束不满足的版本被丢弃——意图比 SFINAE 清晰得多。","c":{"lang":"cpp","code":"template <typename T>\nconcept Integral = std::is_integral_v<T>;\ntemplate <typename T> requires Integral<T> int f(T) { return 1; }\ntemplate <typename T> requires (!Integral<T>) int f(T) { return 2; }"}},{"h":"三、requires 表达式与约束组合","s":"requires 既能做简单约束（requires Integral<T>），也能做复合约束（requires { {expr} -> concept; }），检查某个表达式是否良构、返回类型是否满足 concept。","c":null}]},{"id":"cpp-ch17/04-variadic-fold-forward","file":"04-variadic-fold-forward.md","title":"04 · 变参模板/折叠表达式 与 完美转发","kind":"flow","secs":[{"h":"一、变参模板与折叠表达式","s":"变参模板接受任意数量/类型的模板参数 template<typename... Ts>；C++17 折叠表达式 (pack op ...) 把二元运算符规约到整个参数包，省去递归展开。","c":{"lang":"cpp","code":"template <typename... Ts>\nauto sum(Ts... ts) { return (ts + ... + 0); }   // 左折叠，初值 0"}},{"h":"二、完美转发","s":"std::forward<T>(x) 在「引用折叠」配合下，把 T&& 参数原始的「左值/右值」值类别还原后转发给下游，实现「转发不丢类别」。","c":{"lang":"cpp","code":"template <typename T>\nvoid wrapper(T&& x) { callee(std::forward<T>(x)); }  // 不写 forward 会永远当左值"}},{"h":"三、实现变参的「类型安全打印」","s":"用 if constexpr + 折叠可写通用打印，避免 SFINAE/递归：","c":{"lang":"cpp","code":"template <typename... Ts>\nvoid print_all(Ts&&... ts) {\n    ((std::cout << std::forward<Ts>(ts) << ' '), ...);\n}"}}]},{"id":"cpp-ch17/05-template-meta-practical-recipes","file":"05-template-meta-practical-recipes.md","title":"模板元编程实战手记：凯喵的十二次「报错三百行，源码一行」","kind":"flow","secs":[{"h":"开场：为什么模板错误这么难读","s":"普通函数出错，报错指向一行代码。模板出错，编译器要告诉你「实例化 A 导致实例化 B 导致实例化 C 导致 D 里有个类型不对」，于是回溯链长得吓人。","c":{"lang":"cpp","code":"#include <type_traits>\n\ntemplate <typename T>\nvoid process(T&& v) {\n    if constexpr (std::is_integral_v<std::remove_reference_t<T>>) {\n        // 整数走这条路\n    } else if constexpr (std::is_floating_point_v<std::remove_reference_t<T>>) {\n        // 浮点走这条\n    } else {\n…"}},{"h":"收尾：模板元编程的本质是「让编译器替你写代码」","s":"凯喵最后总结：模板元编程看起来是一堆晦涩的语法，但它的目标很朴素——把「对每种类型都写一遍」变成「写一遍，让编译器生成其余」。","c":null}]}],"exams":[{"kind":"choice","q":"关于 SFINAE，下列说法正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"SFINAE 能把函数体内的任何错误都变成软失败"},{"k":"B","t":"模板参数替换阶段发生的失败会被忽略，该模板从候选集移除"},{"k":"C","t":"enable_if 的条件不必互斥，编译器会自动补全"},{"k":"D","t":"函数模板支持偏特化来模拟约束"}],"ans":"B","why":"SFINAE 仅作用于替换阶段；函数体错误是硬错误。enable_if 条件需互斥且完备；函数模板不支持偏特化（只能重载/全特化）。"},{"kind":"output","q":"读代码写输出（type_traits 萃取）","stem":"cpp #include <iostream> #include <type_traits> int main() { bool a = std::is_same_v<std::remove_reference_t<int&>, int>; bool b = std::is_same_v<std::decay_t<int[3]>, int>; std::cout << std::boolalpha…","opts":[],"ans":"truetrue","why":"remove_reference_t<int&> 为 int；decay_t<int[3]> 退化为 int，两者均 true。"},{"kind":"fix_error","q":"修复完美转发丢失值类别","stem":"下面 wrapper 直接把 x 传给 callee，右值性会丢失。请用 std::forward 修复（保留值类别）： cpp template <typename T> void wrapper(T&& x) { callee(x); }","opts":[],"ans":"template <typename T> void wrapper(T&& x) { callee(std::forward<T>(x)); }","why":"具名转发引用 x 永远是左值；必须 std::forward<T>(x) 才能还原传入时的值类别（引用折叠在此生效）。"},{"kind":"explain","q":"constexpr 与 const 的区别；如何证明函数确在编译期执行","stem":"解释：constexpr 与 const 有何本质区别？如何证明一个 constexpr 函数真的在编译期求值？","opts":[],"ans":"const 只保证运行时不修改；constexpr 保证值可在编译期确定。证明方式：把结果用于需要编译期常量的语境，如 static_assert(f(10)==X) 或 constexpr int x = f(10); 或 int arr[f(5)];。若这些能编译通过，说明确在编译期求值。","why":"核心是「constexpr=编译期可知，const=运行时不改」；用 static_assert / 编译期数组大小强制编译期求值。"},{"kind":"design","q":"LeetCode 50 · Pow(x, n)（可用 constexpr 编译期预计算）","stem":"实现 double myPow(double x, int n) 计算 x 的 n 次幂，要求 O(log n)。可借 constexpr/模板元编程在编译期预计算查表以提速（详见 external_url，不在此搬运题面）。","opts":[],"ans":"// 思路：快速幂（二分）。若要求编译期：可用 constexpr 实现幂并 static_assert 校验； // 或模板元编程在编译期生成小指数查表。具体实现见 external_url 原题要求。","why":"快速幂是 constexpr 友好的经典场景；编译期预计算可把运行开销降为零（以编译时间为代价）。"},{"kind":"design","q":"牛客网 · C++ 模板/泛型专项（类型萃取与 SFINAE 实战）","stem":"此类题目要求用模板元编程/type_traits 实现类型安全的泛型工具（如根据类型选择不同实现）。请结合本章 SFINAE 与 concept 知识作答（详见 external_url，不在此搬运题面）。","opts":[],"ans":"// 思路：用 enable_if/if constexpr 按 type_traits 选择分支；C++20 用 concept 表达约束。 // 具体题目与实现见 external_url 专项练习要求。","why":"牛客 C++ 专项常考「泛型 + traits + 编译期约束」，是 SFINAE/concept 的标准应用场景。"}],"works":[{"h":"SFINAE 只发生在「模板参数替换」阶段","d":"仅当错误出现在模板实参推导/替换过程中（如 enable_if 的 ::type 不存在）时才会被视为「替换失败」而被忽略；替换完成后出现的语义错误仍是硬错误。常见误用：把「运行时才能发现的错误」期望被 SFINAE 吞掉。 约束表达式必须放在能参与替换的位置（返回类型、std::enable_if_t 默认模板参数、或函数参数），不…"},{"h":"enable_if 约束位置/条件写错导致两重载都匹配或都不匹配","d":"enable_if<false>::type 不存在，该重载即从候选集移除；若两个条件不互斥/不完备，会出现歧义或无候选。 用 std::enable_if_t<cond> 放在返回类型或最后一个默认模板参数，并保证条件互斥且完备（覆盖所有可能的类型）。"},{"h":"if constexpr 的条件必须是编译期常量，且被裁剪分支仍需语法合法","d":"if constexpr(cond) 中 cond 必须是常量表达式，否则编译失败；被丢弃的分支不会被实例化，但仍要求语法正确（只是类型不检查）。 用类型 trait（is_integral_v 等）作条件；不要把「另一分支类型非法」的代码放进被裁剪分支后还指望它能通过编译。"},{"h":"std::decay 会退化数组/函数/引用/const，与 remove_referenc…","d":"decay_t<int&>→int，decay_t<int[3]>→int，decay_t<const int>→int。若只想去引用却用了 decay，会把 cv 限定与数组也一起退化掉。 按意图选：仅去引用用 remove_reference / remove_cvref；「像按值传参一样退化」才用 decay。"},{"h":"完美转发丢失值类别：没有用 std::forward<T>(x)","d":"template<typename T> void f(T&& x){ g(x); } 中 x 是具名变量（永远是左值），直接 g(x) 会永远以左值转发，右值性丢失。 必须 g(std::forward<T>(x)) 才能还原 T 推导出的原始值类别（引用折叠在此发挥作用）。"},{"h":"把函数模板偏特化当类模板偏特化用","d":"C++ 不允许函数模板偏特化（只允许重载与全特化）；试图写 template<> void f<Widget>(Widget) 偏特化会编译报错。 函数用「重载 + enable_if」或「转发到类模板偏特化」来模拟偏特化；只有类/结构体支持偏特化。"},{"h":"constexpr 函数并非「一定在编译期执行」","d":"constexpr 表示「可以在编译期求值」；只有在需要编译期常量的语境（数组大小、static_assert、用 constexpr 变量接收、模板非类型参数）使用时才会真正编译期求值，普通运行时调用仍是运行时。 想强制编译期求值：用 constexpr 变量接收或放进 static_assert；C++20 可用 consteva…"},{"h":"把 enable_if 全塞进返回类型","d":"多个重载只在返回类型上有 enable_if 差异时，签名差异被埋进返回类型，模板实参推导与重载决议的报错会互相纠缠，错误信息动辄几百行、指向完全无关的行。 C++20 用 requires / concept 表达约束；C++17 及以前把条件放到模板参数默认值（typename = enable_if_t<...>），可读性差一个…"}],"asks":[{"q":"SFINAE 是什么？enable_if 怎么用来约束模板？concept 又解决了什么？","a":"SFINAE（Substitution Failure Is Not An Error）：模板实参替换过程中的失败不算错误，而是悄悄把该模板从重载候选中移除。 enable_if 约束：std::enable_if_t<Cond, T> 在 Cond 为真时提供 type，为假时无该成员，触发替换失败→重载被剔除。常用于「只对满足 trait 的类型启用函数」。 concept 的改进：SFINA…","fu":["两个 enable_if 重载的条件必须互斥且完备，为什么？","函数模板为什么不支持偏特化，怎么替代？"],"tag":"通用/字节"},{"q":"if constexpr 和普通 if 在模板里有什么区别？为什么需要它？","a":"普通 if：所有分支都会被实例化，对非适用类型会产生类型错误（如对非指针类型写 v）。 if constexpr(cond)：cond 必须是编译期常量；不满足的分支不被实例化——因此可以对不适用类型写「看似非法」的代码而安然通过，且零运行时分支开销。 它取代了大量「为区分类型而写的模板特化/重载集」，是泛型代码降复杂度的关键工具。注意被裁剪分支仍需语法合法（只是不做类型检查）。","fu":["被 if constexpr 裁剪的分支真的不检查类型吗？","if constexpr 能否用于非模板函数？"],"tag":"美团/阿里"},{"q":"std::move 和 std::forward 有什么区别？各自依赖什么机制？","a":"std::move：无条件把左值/右值转成右值引用（static_cast<remove_reference_t<T>&&>(t)），只是类型转换，不真正移动任何东西；用来「许可」移动语义。 std::forward<T>：有条件还原参数原始值类别——当 T 推导为左值引用时转左值、推导为右值引用时转右值。它依赖引用折叠与转发引用 T&&，用于泛型函数把参数「原样」转发给下游，避免右值退化成左值导…","fu":["引用折叠的四条规则是什么？","为什么具名 forwarding reference 永远是左值？"],"tag":"通用/百度"},{"q":"type_traits 在 STL 里有哪些典型应用？举一个你熟悉的例子。","a":"典型应用俯拾皆是： 1. std::move：核心是 remove_reference_t<T>&&，先去引用再转右值; 2. std::decay：std::function 参数类型归一（去引用/cv、数组退化指针）; 3. std::invoke / std::apply：用 is_member_function_pointer 等 traits 区分「成员函数指针」「可调用对象」走不同调用…","fu":["is_destructible 和 is_nothrow_destructible 差在哪？","为什么 vector 扩容关心 is_nothrow_move_constructible？"],"tag":"腾讯/通用"}]},{"id":"cpp-ch18","subj":"cpp","title":"性能与底层：内存对齐、缓存友好与内联","summary":"内存对齐 alignas/alignof；false sharing；缓存友好数据结构；内联与 devirtualization；简单 profiling；与 C 的 ABI 兼容。","concepts":[{"id":"cpp-ch18/01-alignment-and-layout","file":"01-alignment-and-layout.md","title":"01 · 内存对齐、填充与显式布局","kind":"stack","secs":[{"h":"一、对齐规则与填充（padding）","s":"一般是 2 的幂）。对象地址必须能被其对齐整除。结构体成员按声明顺序排布，每个成员的起始偏移","c":{"lang":"text","code":"偏移:  0        8               16             24\n      +--------+----------------+------+--------+\n      |  a(1)  | padding (7)    | b(8) | c(1)   |  padding(7)\n      +--------+----------------+------+--------+\n      sizeof(S) = 24, alignof(S) = 8"}},{"h":"二、显式对齐与协议布局：alignas / #pragma pack / 干扰尺寸","s":"（本机实测为 64），用于给热点变量做缓存行隔离。","c":{"lang":"cpp","code":"#include <cstddef>\n#include <cstdio>\n#include <new>\n\n#pragma pack(push, 1)\nstruct WireHeader { char tag; int len; double ts; };   // 紧凑协议头：1 + 4 + 8\n#pragma pack(pop)\n\nstruct alignas(64) HotCounter { long long v; };        // 独占一条缓存行的热点计数\n…"}}]},{"id":"cpp-ch18/02-false-sharing-and-cache","file":"02-false-sharing-and-cache.md","title":"02 · 缓存层次、局部性与 false sharing","kind":"flow","secs":[{"h":"一、缓存层次与局部性（locality）","s":"数据在层次间以缓存行（cache line，主流 64 字节）为单位搬运。程序若具备：","c":null},{"h":"二、false sharing：成因、复现与消除","s":"每次写都要把整行在所有核心间搬运以维持一致性，于是两个线程虽然不共享数据，却被迫竞争同一条行，","c":{"lang":"cpp","code":"#include <atomic>\n#include <chrono>\n#include <cstdio>\n#include <thread>\n\nstruct Together { std::atomic<long long> a{0}; std::atomic<long long> b{0}; };\nstruct Apart    { alignas(64) std::atomic<long long> a{0};\n                  alignas(64) std::atomic<long long> b{0}; };\n\n…"}}]},{"id":"cpp-ch18/03-cache-friendly-structures","file":"03-cache-friendly-structures.md","title":"03 · 缓存友好的数据结构","kind":"compare","secs":[{"h":"一、AoS vs SoA，行优先 vs 列优先","s":"当循环只需要一个场（如只更新 x）时，SoA 让每次缓存行取来的数据几乎全被用到；","c":{"lang":"cpp","code":"#include <chrono>\n#include <cstdio>\n#include <vector>\n\nconstexpr int M = 1024;\n\nvoid row_major(float* a) {                    // 内层步长 4B：连成一条缓存行\n    for (int i = 0; i < M; ++i)\n        for (int j = 0; j < M; ++j) a[i * M + j] += 1.0f;\n…"}},{"h":"二、链表 vs 数组，指针追逐与 std::vector 的连续性","s":"不产生额外访存；链表要顺着 next 指针逐步查找，每一步都是一次指针间接访问（pointer chasing），","c":null}]},{"id":"cpp-ch18/04-inline-devirt-abi","file":"04-inline-devirt-abi.md","title":"04 · 内联、去虚化与 ABI 边界","kind":"flow","secs":[{"h":"一、内联、条件提示与去虚化（devirtualization）","s":"（以及暗示编译器内联）；是否真正内联由优化器决定。","c":null},{"h":"二、与 C 的 ABI 兼容、名称修饰与 [[no_unique_address]] / E…","s":"（GCC 生成 _Z...），C 不做修饰。用 extern \"C\" 可关闭修饰，得到稳定符号名，","c":null}]},{"id":"cpp-ch18/05-alignment-cache-cookbook","file":"05-alignment-cache-cookbook.md","title":"性能速查：把「对齐 / 缓存 / 内联」写成能跑的代码","kind":"stack","secs":[{"h":"一、对齐与 padding：先把内存账算清楚","s":"结构体的每个成员按自身对齐要求（alignof）落在合适偏移上，成员之间会插 padding，","c":{"lang":"cpp","code":"#include <cstddef>\n#include <cstdio>\n\nstruct Plain {          // 三个 int：连续，没有 padding\n    int a, b, c;\n};\n\nstruct Mixed {          // char + int：中间要补 3 字节\n    char tag;\n…"}},{"h":"二、伪共享：两个计数器共处一条缓存行","s":"多核下缓存行（常见 64 字节）是一致性单位：两个线程各自改同一行里的不同变量，","c":{"lang":"cpp","code":"#include <cstdio>\n#include <thread>\n#include <vector>\n#include <chrono>\n\nstruct PaddedCounter {          // 独占一整条缓存行\n    long long value = 0;\n    char        pad[64 - sizeof(long long)];   // 典型 64B 对齐\n};\n…"}},{"h":"三、AoS 与 SoA：同样的算法，换个排布差几倍","s":"面向对象把\"每个对象的字段排在一起\"（AoS），数据分析却更吃\"同一种字段排在一起\"（SoA）：","c":{"lang":"cpp","code":"#include <cstdio>\n#include <vector>\n#include <chrono>\n\nstruct ParticleAoS { float x, y, z; float charge; };\n\nstruct ParticleSoA {\n    std::vector<float> x, y, z, charge;\n};\n…"}},{"h":"四、内联与去虚拟化：让「调用」不再是一笔开销","s":"inline 只是给编译器的建议：它把调用点直接展开成函数体，省掉压栈/跳转；","c":{"lang":"cpp","code":"#include <cstdio>\n#include <vector>\n\nstruct Shape {\n    virtual ~Shape() = default;\n    virtual double area() const = 0;\n};\nstruct Circle : Shape {\n    double r;\n…"}},{"h":"🧑‍💻 程序员视角","s":"两个线程各自频繁写一个计数器，即使它们毫无逻辑关系，只要这两个计数器落在同一条 64 字节缓存行上，就会因为缓存一致性协议反复失效对方的行——这叫伪共享，实测能差 5~10 倍。解法是加 alignas(64) 或用填充把二者分开。Ao…","c":null},{"h":"🎓 博士生视角","s":"伪共享的根因是「缓存一致性以行为单位」：MESI 协议下，一个核写某行会让其他核的副本失效，哪怕只改了一个字节。这使「逻辑上独立」的变量在物理上耦合。对齐（alignment/padding）是编译器按「最大成员对齐数」插入填充的结果…","c":null},{"h":"📚 考研者视角","s":"面试与实战：","c":null}]}],"exams":[{"kind":"choice","q":"关于内存对齐与填充，下列说法正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"alignas 可以把类型的对齐从 8 降低到 1"},{"k":"B","t":"结构体的 sizeof 一定是其 alignof 的整数倍"},{"k":"C","t":"把结构体 memcpy 到网络是安全且可移植的"},{"k":"D","t":"#pragma pack(1) 会抬高成员对齐"}],"ans":"B","why":"sizeof 必须是 alignof 的整数倍，否则数组遍历会破坏成员对齐（B 正确）。alignas 只能抬高对齐（A 错）；带填充的结构体 memcpy 会泄漏未初始化内存且不可移植（C 错）；pack(1) 是降低对齐（D 错）。"},{"kind":"output","q":"读代码写输出（结构体布局）","stem":"cpp #include <cstdio> #include <cstddef> struct T { char a; int b; char c; }; int main() { printf(\"%zu %zu %zu %zu\", sizeof(T), offsetof(T,a), offsetof(T,b), offsetof(T,c)); }","opts":[],"ans":"12 0 4 8","why":"a@0；b 需 4 字节对齐 → 补 3 字节，b@4；c@8；结构体对齐为 4 → 总大小向上取整到 4 → 12。故 sizeof=12，偏移依次 0/4/8。"},{"kind":"fix_error","q":"修复伪共享：让两个热点计数器分处不同缓存行","stem":"下面两个线程各写一个计数器，却因为落在同一条缓存行而互相拖累。请改造结构，使两个计数器分处不同缓存行（缓存行按 64 字节计，用 alignas 或填充）。 cpp struct Counters { std::atomic<long long> a{0}; std::atomic<long long> b{0}; }; Counters g;","opts":[],"ans":"struct alignas(64) Counters { std::atomic<long long> a{0}; char pad[64 - sizeof(std::atomic<long long>)]; // 把 b 推到偏移 64 std::atomic<long long> b{0}; }; Counter…","why":"伪共享的根源是「一致性以缓存行为单位，而程序语义以变量为单位」。把两个变量推到不同缓存行（偏移 0 与 64）即可消除：每个核心写自己的行，不再互相使对方副本失效。注意结构体整体 alignas(64) 才能保证偏移 0 恰好在行首。"},{"kind":"explain","q":"inline 是建议还是命令？final 如何帮助去虚化？","stem":"解释：inline 关键字到底保证什么？final 为什么能帮助编译器去虚化（devirtualization）？","opts":[],"ans":"inline 主要保证「允许多个翻译单元重复定义同一函数而不违反 ODR」，同时暗示内联；是否真正内联由优化器决定，编译器可拒绝（如递归、取函数地址、跨 TU 且无 LTO）。想强制内联需用 __attribute__((always_inline)) 等扩展。 final 让编译器确知「该类型不会被继承」。当静态类型…","why":"核心是「inline 的关键作用是 ODR 例外而非强制内联」与「final 提供类型唯一性信息，使虚调用可静态解析」。"},{"kind":"coding","q":"实现一个「缓存行隔离计数器」，并用确定性判据验证","stem":"实现 struct CacheAligned { std::atomic<long long> v; ... }，使多个这样的计数器互不共享缓存行。写一个 bool same_line(const void, const void) 判据（按 64 字节行），并验证两个计数器的地址不在同一行。不得使用墙钟时间。","opts":[],"ans":"struct alignas(64) Cell { std::atomic<long long> v{0}; char pad[64 - sizeof(std::atomic<long long>)]; }; bool same_line(const void p, const void q) { return (re…","why":"把每条缓存行封成一个 alignas(64) 且大小恰为 64 的 Cell，则相邻 Cell 必然落在不同行。用地址整除 64 的商判断是否同行，是确定性判据（不依赖机器速度）。"},{"kind":"design","q":"LeetCode 867 · Transpose Matrix（转置与访存局部性）","stem":"实现矩阵转置 transpose(matrix)。思考：行优先存储的矩阵，转置时读/写各自是「行优先」还是「列优先」，哪一种访存模式对缓存更友好？（详见 external_url，不在此搬运题面。）","opts":[],"ans":"// 思路：结果 res[j][i] = matrix[i][j]。 // 读方向沿 matrix[i][j]（j 连续）→ 顺序读，局部性好； // 写方向 res[j][i] 中 j 变化 → 跨行写，局部性差。 // 优化：分块（tile）转置，把读写工作集都压进缓存，减少缓存行未命中。 // 具体输入输出格式见…","why":"转置是「读写访存模式不匹配」的典型：即便都是 O(mn)，朴素实现的一方必然是跨行访问。分块转置是把工作集切到缓存装得下的经典手法，与本章的缓存局部性主线一致。"},{"kind":"design","q":"牛客网 · C++ 内存对齐 / 结构体专项","stem":"此类题要求给出结构体的 sizeof 与各成员偏移、判断对齐与填充，或要求用 alignas/#pragma pack 调整布局。请结合本章的对齐规则与 offsetof 实测方法作答（详见 external_url，不在此搬运题面）。","opts":[],"ans":"// 思路：① 逐成员按成员对齐排布并补填充； // ② 结构体对齐 = 最大成员对齐； // ③ sizeof 向上取整到结构体对齐。 // 可用 offsetof/sizeof 实测验证（见 examples/ex01~ex04）。 // 具体题目见 external_url 专项练习要求。","why":"牛客 C++ 专项常考「对齐与结构体布局」的计算题，是本章最直接的考点，标准解法是四步排布 + 实测验证。"},{"kind":"design","q":"GitHub · TheAlgorithms/C-Plus-Plus：把一个算法的访存模式改成缓存友好","stem":"在 TheAlgorithms/C-Plus-Plus 中选一个矩阵/数组算法，分析其访存模式，指出哪个循环破坏了空间局部性，并给出缓存友好改写（交换循环次序 / 分块 / SoA）。用操作计数或缓存行模型给出确定性对比（不得用耗时）。（详见 external_url 仓库，不在此搬运内容。）","opts":[],"ans":"// 思路： // ① 找出内层循环的地址步长；步长 > 缓存行（64B）即破坏局部性； // ② 改写：交换循环次序使内层沿连续维度推进；或分块把工作集压进缓存； // ③ 验证：自写直接映射缓存模型统计 miss，比较改前/改后（确定性判据）。 // 仓库见 external_url。","why":"把「读代码 → 判断访存模式 → 改写 → 用确定性计数验证」的闭环走通，是本章能力目标的综合检验。"}],"works":[{"h":"把带填充的结构体直接 memcpy/memcmp","d":"填充字节是未初始化内存，memcmp 结果不确定， memcpy 到网络会泄漏栈上残留数据且跨平台不可读。 显式逐字段序列化；或用 #pragma pack(1) 并固定字节序；比较时逐字段比较。"},{"h":"对含 std::atomic / SIMD / 指针的\"业务结构体\"用 #pragma pa…","d":"会把成员推到未对齐地址， 原子操作可能失效、SIMD 访存可能崩溃。 pack 只用于纯数据协议结构；对齐敏感的成员要么不 pack，要么逐字段拷贝进 packed 结构。"},{"h":"以为 alignas 可以降低对齐","d":"alignas(N) 只能抬高对齐（N 不小于自然对齐）； 想降低只能靠 #pragma pack 或改成员类型。 记住方向：alignas 抬、pack 降，二者作用于不同层级。"},{"h":"以为字段重排总能减小 sizeof","d":"重排只能消除内部/尾部填充；若成员本无填充（如全是 int）则毫无收益，还会破坏 ABI（已发布的二进制接口不能重排）。 先实测 sizeof 与偏移再决定；对外接口的结构体一旦发布就不许重排。"},{"h":"把 false sharing 当成数据竞争","d":"伪共享结果正确，只是性能问题；加锁/原子解决不了它。 对策是让变量分处不同缓存行（alignas(64) / 填充 / hardware_destructive_interference_size）。"},{"h":"给结构体加 alignas(64) 就以为两个成员分行了","d":"alignas 只管结构体起始地址， 成员间距要靠填充成员。实测：同一 alignas(64) 结构内偏移 0 与 8 的两个变量仍在同一行。 要分行就把后继成员推到偏移 ≥64（插 char pad[...]），并用地址判据验证。"},{"h":"用墙钟时间/耗时做性能断言","d":"本机 clock()/chrono 抖动极大，受频率调节与其它进程影响， 结论不可复现。 一律改用确定性判据：sizeof/offsetof、操作计数、缓存行未命中计数、布尔结论， 并注明「定性结论，具体数值依机器而定」。"},{"h":"以为 inline 是\"强制内联\"","d":"inline 的本义是允许多 TU 定义（ODR 例外）并暗示内联； 是否内联由优化器决定。想强制用 always_inline，但仍可能被拒绝。 想加速就开 -O2；inline 主要用于头文件里的函数定义。"}],"asks":[{"q":"什么是内存对齐？为什么结构体会产生填充？sizeof 怎么算？","a":"对齐：每个类型有对齐要求 alignof(T)，对象地址必须能被它整除。填充是为满足对齐在成员/结构体尾部插入的空洞。 规则：① 成员按声明顺序排布，偏移必须是该成员对齐的整数倍，不足补填充；② alignof(struct) = 最大成员对齐；③ sizeof 向上取整到 alignof(struct) 的整数倍（尾部填充）。 硬件动机：未对齐地址可能跨缓存行/页边界，一次访存被拆成两次总线事务…","fu":["为什么 sizeof 必须是 alignof 的整数倍？","alignas 和 #pragma pack 分别作用在哪一层？"],"tag":"通用/腾讯"},{"q":"什么是 false sharing（伪共享）？它是正确性问题还是性能问题？如何消除？","a":"伪共享：多个线程各自修改不同变量，但变量落在同一条缓存行上。一致性协议以行为单位（write-invalidate），导致每次写都要把整行在核心间搬运，吞吐骤降。 性质：纯粹的性能问题——结果完全正确，不是数据竞争（数据竞争是 UB）。所以对策不是加锁，而是让变量分行。 消除：① 每个热点变量 alignas(64)；② 用 std::hardware_destructive_interferen…","fu":["padding 消除伪共享的代价是什么？什么时候不值得？","volatile 能解决伪共享吗？"],"tag":"通用/字节"},{"q":"AoS 和 SoA 各适合什么场景？行优先/列优先遍历为什么差这么多？","a":"AoS（结构体数组）字段相邻，适合「整体处理一个对象」；SoA（数组结构体）每个场连续，适合「只处理一个字段」的大批量循环，且利于自动向量化（SIMD）。 判据：若循环只用到部分字段，AoS 会把用不到的字段一起拉进缓存行 → 有效带宽利用率低。实测（自写缓存模型）AoS 未命中 256、SoA 64，比值恰为「每行粒子数之比」。 矩阵遍历：行优先存储下，内层沿列推进（地址连续）具备完美空间局部性…","fu":["SoA 的工程代价是什么？","为什么大跨步访问还会触发冲突未命中？"],"tag":"通用/腾讯"},{"q":"inline 是强制内联吗？final 如何帮助去虚化？为什么说 ABI 边界就是优化边界？","a":"inline 主要作用是允许多个 TU 重复定义（ODR 例外）并暗示内联；是否内联由优化器决定，可被拒绝。强制内联用 __attribute__((always_inline))/__forceinline。 去虚化：编译器若能证明虚调用的动态类型唯一，就把它变成直接调用甚至内联。final 提供这一保证（类型不会被继承 ⇒ 静态类型即动态类型）。此外构造函数内、局部对象也可静态确定类型。 AB…","fu":["虚函数能被内联吗？","-O2 -flto 对去虚化/内联的影响？"],"tag":"通用/字节"}]},{"id":"cpp-ch19","subj":"cpp","title":"工程化与测试：CMake、单元测试与 CI","summary":"CMake 现代用法（target_/fetchContent）；单元测试 googletest/catch2；静态分析 clang-tidy；CI 流水线；头文件/源文件组织约定。","concepts":[{"id":"cpp-ch19/01-cmake-target-centric-usage-requirements","file":"01-cmake-target-centric-usage-requirements.md","title":"01 · 现代 CMake：target-centric 与 usage requirements 传播","kind":"compare","secs":[{"h":"一、从「目录级变量」到「目标级属性」：现代 CMake 的分水岭","s":"link_libraries()、add_definitions()、set(CMAKE_CXX_FLAGS ...)、set(CMAKE_CXX_STANDARD 17)。","c":{"lang":"cmake","code":"add_library(mylib src/a.cpp src/b.cpp)\n\ntarget_include_directories(mylib PUBLIC  include)   # 使用者也需要这个路径\ntarget_include_directories(mylib PRIVATE src)       # 仅内部实现用\ntarget_compile_features(mylib PUBLIC cxx_std_20)\ntarget_link_libraries(mylib PUBLIC fmt::fmt PRIVATE spdlog::spdlog)"}},{"h":"二、PUBLIC / PRIVATE / INTERFACE：使用要求的三种传播强度","s":"CMake 把「使用一个目标所需的一切」称为 usage requirements（使用要求），","c":null},{"h":"三、依赖获取与可重定位：find_package vs FetchContent，insta…","s":"拿到第三方依赖有两条路：","c":{"lang":"cmake","code":"install(TARGETS mylib EXPORT mylibTargets\n        ARCHIVE DESTINATION lib LIBRARY DESTINATION lib RUNTIME DESTINATION bin)\ninstall(DIRECTORY include/ DESTINATION include)\ninstall(EXPORT mylibTargets NAMESPACE mylib:: DESTINATION lib/cmake/mylib)"}}]},{"id":"cpp-ch19/02-unit-test-design-and-isolation","file":"02-unit-test-design-and-isolation.md","title":"02 · 单元测试：框架内核、用例设计与依赖隔离","kind":"flow","secs":[{"h":"一、测试框架的最小内核与退出码语义","s":"一个能接进 CI 的测试框架，最小实现只需四个部件（ex01）：","c":{"lang":"cpp","code":"struct Stats { int tests = 0, failed_tests = 0, checks = 0, failed_checks = 0; };\n// ① 注册：宏 + 全局注册表（静态对象构造期把用例塞进 vector）\n#define TEST(name) \\\n    static void name(); \\\n    static mini::Registrar mini_reg_##name(#name, name); \\\n    static void name()\n// ② 断言：计数 + 失败时用 __LINE__ 定位\n#define CHECK_EQ(a, b) mini::Registry::instance().eq((a), (b), __LINE__, #a, #b)\n// ③ 汇总：[SUMMARY] 用例=5 失败用例=0 断言=8 失败断言=0\n…"}},{"h":"二、用例设计：等价类、边界值、参数化与夹具隔离","s":"再取 12 个边界点（-1, 0, 59, 60, 69, 70, 79, 80, 89, 90, 100, 101），","c":null},{"h":"三、依赖注入、mock 与测试金字塔","s":"不可控依赖（时间、随机数、网络、文件系统、数据库）是「测试慢且不稳」的头号来源。","c":null}]},{"id":"cpp-ch19/03-static-analysis-warnings-sanitizer","file":"03-static-analysis-warnings-sanitizer.md","title":"03 · 静态分析与编译告警：让机器替你做代码审查","kind":"flow","secs":[{"h":"一、编译告警与 -Werror：把「建议」升级成「阻断」","s":"ex17 用同一份源码做了两次编译对照：","c":{"lang":"text","code":"[编译1] -Wall -Wextra            返回码=0 警告数=2\n[警告类别] -Wunused-parameter=1 -Wunused-variable=1\n[编译2] -Wall -Wextra -Werror    返回码=1 错误数=2\n[首条诊断] unused parameter 'factor'"}},{"h":"二、静态分析：clang-tidy / cppcheck / clang-format 与「…","s":"静态分析器不改代码行为，只按规则对源码（或 AST）做模式匹配与数据流分析。本章把它规则库化了，","c":null},{"h":"三、运行期防线：sanitizer 与三层门禁的排布","s":"编译期与静态分析都只看代码，看不到实际执行路径。sanitizer 是编译器插桩的运行期检测器：","c":{"lang":"bash","code":"# 三层门禁：编译告警 -> 静态分析 -> sanitizer\ng++ -std=c++20 -Wall -Wextra -Werror -c src/a.cpp -o /dev/null\n\nclang-tidy src/a.cpp -- -std=c++20 -Iinclude\n\n# ASan/UBSan 只在调试构建开：约 2x 内存、2-3x 时间\ng++ -std=c++20 -fsanitize=address,undefined -fno-omit-frame-pointer \\\n    -g src/a.cpp -o a_asan"}}]},{"id":"cpp-ch19/04-ci-pipeline-and-project-layout","file":"04-ci-pipeline-and-project-layout.md","title":"04 · CI 流水线与工程组织：从 workflow 结构到头文件/源文件约定","kind":"timeline","secs":[{"h":"一、workflow 的结构与 DAG：needs 决定一切","s":"一个 workflow 是若干 job 的集合。job 默认并行；一旦写了 needs: [build-and-test]，","c":{"lang":"text","code":"[拓扑序] build -> lint -> test -> package -> deploy\n[并行层] 层1=build,lint  层2=test  层3=package  层4=deploy\n[关键路径] 长度=4 路径=build -> test -> package -> deploy\n[环检测] 环形 workflow 拓扑序=None 环成员=['a', 'b', 'c'] -> workflow 非法"}},{"h":"二、矩阵构建、缓存与 artifact：用组合换覆盖，用指纹换正确性","s":"ex12 把矩阵展开的语义算清楚了。给定 os(3) × std(2) × build_type(2)：","c":{"lang":"text","code":"[基础组合] os(3) x std(2) x build_type(2) = 12 个\n[exclude] 命中 2 个组合 -> 剩 10 个\n[include] 合并进已有组合 0 个（新增键不改变组合数）\n[include] 与基础矩阵冲突、生成新组合 2 个\n[最终] 组合数=12\n[上限校验] 组合数 12 <= 256 = True"}},{"h":"三、头文件/源文件组织约定与 ODR","s":"流水线管的是「何时验证」，工程组织管的是「验证什么」。C++ 的两条硬约定：","c":{"lang":"text","code":"strong = 外部唯一 / weak = 可折叠 / inline = 多定义合法 / static = 内部链接\n用例1 正常：helper(strong,1处) inline_util(3处inline) local_only(2处static) tmpl_inst(2处weak) -> 违规数=0\n用例2 违规：format = x.cpp(strong) + y.cpp(inline) -> ODR 违规：强符号与 inline/weak 混用"}}]}],"exams":[{"kind":"choice","q":"PUBLIC / PRIVATE / INTERFACE 的传播判定","stem":"已知三个目标的关系如下（core 的公开头目录为 core/include）： cmake cmake_minimum_required(VERSION 3.20) project(demo LANGUAGES CXX) add_library(core STATIC src/core.cpp) target_include_directories(core PUBLIC ${CMAKE_CURR…","opts":[{"k":"A","t":"能编译通过：PRIVATE 只影响 core 自己，math 是 core 的使用者，使用要求照常传给 math，再由…"},{"k":"B","t":"编译失败：math 以 PRIVATE 链接 core，使用要求不再向 math 的消费者传播，app 的 includ…"},{"k":"C","t":"能编译通过：只要 install(EXPORT) 导出过 core，任何目标都能看到 core 的头文件"},{"k":"D","t":"取决于 app 是不是 STATIC 库：可执行文件看不到，静态库能看到"}],"ans":"B","why":"PRIVATE 的含义是「依赖只对自己可见，不作为使用要求导出」。因此 math 的 INTERFACE_INCLUDE_DIRECTORIES 为空，app 链接 math 时不会继承到 core/include，直接包含必然报 No such file or directory。这正是 ex10 图 B 的结论：把 PRIVATE 改回 PUBLIC，app 才能看到。A…"},{"kind":"fix_error","q":"把目录级 CMakeLists 改写成现代 target-centric 写法","stem":"下面这份 CMakeLists 在 ex09 的静态检查器里被判出 9 个问题（CM001–CM010 规则库）： cmake include_directories(${CMAKE_SOURCE_DIR}/include) link_libraries(pthread) set(CMAKE_CXX_FLAGS \"${CMAKE_CXX_FLAGS} -Wall\") add_executable(…","opts":[],"ans":"cmake_minimum_required(VERSION 3.20) project(cppmind_demo LANGUAGES CXX) # ① 目录级命令 -> 目标级命令 add_library(core STATIC src/core.cpp) target_include_directories(cor…","why":"四步改写对应四条规则：① include_directories/link_libraries 是目录级命令（CM001/CM002），include 与依赖都会泄漏给本目录全部目标 → 改成 target_include_directories / target_link_libraries；② 缺关键字（CM006/CM007）→ 显式写 PUBLIC/PRIVATE；③…"},{"kind":"output","q":"自研测试框架：断言计数、失败定位与退出码语义","stem":"下面是一个极简测试框架内核（本章 ex01 的精简版）。写出它运行后的标准输出全文，并说明进程的退出码是多少： cpp #include <cstdio> static int checks = 0; static int failed = 0; static void check(bool ok, int line) { ++checks; if (!ok) { ++failed; std::p…","opts":[],"ans":"[ ASSERT ] 第13行 [SUMMARY] 断言=3 失败断言=1 [CI] 退出码=1","why":"三条断言依次执行：1+1==2 通过、23==5 失败（实为 6）、4-1==3 通过，所以 checks=3、failed=1。失败断言打印 [ ASSERT ] 第13行——行号来自断言宏里的 __LINE__，这是「失败定位」的全部秘密。最后 main 返回 failed ? 1 : 0 = 1，CI 只认这个退出码：返回 0 会让流水线误判为通过，因此测试入口绝不能把返…"},{"kind":"coding","q":"用依赖注入让限流器摆脱真实时间","stem":"现有一个限流器直接调用 steady_clock::now() 取时间，导致测试必须 sleep，又慢又不稳。请完成改造： 1. 抽出 IClock 抽象接口（now_ms()），提供 FakeClock（时间可 advance）与 SystemClock 两个实现； 2. RateLimiter 通过构造函数接收 const IClock&，不再自己取系统时间； 3. 容量为 3、窗口 1000…","opts":[],"ans":"#include <chrono> #include <iostream> // ① 抽象接口：被测代码只认识它，从不自己取系统时间 struct IClock { virtual ~IClock() = default; virtual long long now_ms() const = 0; }; struct…","why":"关键是「隐藏输入显式化」：原来 now() 是被测函数内部的隐藏输入，测试无法控制；注入之后它变成构造参数，于是窗口边界可以被精确构造（advance(1000) 一步跨窗，无需等待）。这里用的是 stub（桩） 而非 mock：FakeClock 只按测试需要返回固定时刻，并不校验「是否被调用了几次」；只有当你需要断言调用行为（如重试 3 次）时才需要 mock/spy。注意…"},{"kind":"choice","q":"夹具隔离与静态状态泄漏","stem":"某同学写了两个「看起来一样」的用例： 写法甲（夹具）： cpp // 夹具：每个用例一个全新实例 struct CounterFixture { int value = -1; // 故意给个脏初值，验证 SetUp 一定被调用 void SetUp() { value = 0; } void TearDown() {} }; #define TEST_F(Fx, name) \\ static v…","opts":[{"k":"A","t":"甲中两个用例都会通过；乙中第二个断言失败，因为 static 变量的修改会跨用例保留"},{"k":"B","t":"甲中 add_twice 会失败，因为夹具实例在用例之间共享"},{"k":"C","t":"乙的问题只在于命名不规范，整包跑和单跑结果一致"},{"k":"D","t":"两种写法等价，只要测试框架按用例名排序执行就没有区别"}],"ans":"A","why":"TEST_F 宏在每次执行前构造一个全新的 CounterFixture 并调用 SetUp() 复位，所以两个用例各自从 0 开始、都通过（B 错）。乙的 static int shared_total 是跨用例存活的状态，第二次执行时读到的是上一次留下的值（10 而非 5），这就是典型的「单独跑通过、整包跑失败」（C 错）。这类假失败与执行顺序、用例名排序无关，只与「谁在用…"},{"kind":"fix_error","q":"修正一份跑不起来的 GitHub Actions workflow","stem":"下面这份 workflow 在 ex13 的校验器里会报出多条问题（WF001–WF007）： yaml name: ci jobs: build: steps: - uses: actions/checkout - run: cmake -S . -B build test: needs: [bulid] steps: [] deploy: needs: [release] steps: - r…","opts":[],"ans":"name: ci on: # WF001：缺 on 则 workflow 永远不会被触发 push: branches: [main] pull_request: jobs: build: runs-on: ubuntu-latest # WF003 timeout-minutes: 15 # WF007 steps:…","why":"四类问题逐一对应：① 缺 on（WF001）→ workflow 永远不会被触发；② 缺 runs-on（WF003）与 steps 为空（WF004）→ job 没地方跑、也没事可做；③ needs: [bulid] 是错别字导致的悬空引用（WF005）→ GitHub 直接拒绝该 workflow，deploy 的 needs: [release] 同理；④ uses: a…"},{"kind":"coding","q":"为开源算法实现补一套参数化 + 边界值测试","stem":"以 TheAlgorithms/C-Plus-Plus 里的查找类算法为对象（本章 _manifest.json 已收录该仓库），完成下列任务，不要照抄仓库代码，自己写一份实现再测： 1. 实现 binary_search_idx(const std::vector<int>&, int)：找到返回下标，找不到返回 -1， 搜索区间统一写成左闭右开 [lo, hi)，取中点用 lo + (hi -…","opts":[],"ans":"[SUMMARY] 断言=6 失败断言=0","why":"二分查找的 bug 几乎全在边界：左闭右开区间下 hi = a.size()（不能是 size()-1），循环条件是 lo < hi（不能是 lo <= hi），更新是 hi = mid（不能是 mid - 1，否则死循环或漏解）。用例设计上，空容器是一个独立等价类，最容易被漏掉；「小于最小 / 大于最大 / 中间不存在」三个点覆盖未命中的三种情形。参数化让新增一组数据只改表…"},{"kind":"coding","q":"LeetCode 20 · 用等价类与边界值驱动栈解法（仅元数据+链接）","stem":"合规提示：本题只保留元数据与链接，不搬运题面。请在 LeetCode 打开下方链接阅读题面后作答。 要求（本章视角）： 1. 用栈实现括号合法性判定：左括号入栈对应的右括号，遇右括号时比对栈顶； 2. 先列等价类：合法嵌套、合法并列、类型不匹配、顺序颠倒、多余左括号、多余右括号、空串； 再为每类取代表用例，用参数化方式组织； 3. 输出 [SUMMARY] 断言=N 失败断言=M，失败断言数为 0…","opts":[],"ans":"[SUMMARY] 断言=7 失败断言=0","why":"判定逻辑：遇左括号压入期望的右括号，遇其它字符时要求栈非空且栈顶等于该字符，全部扫描完后栈必须为空（否则有多余左括号）。等价类划分上，「空串」是边界等价类：它不含任何字符，循环一次都不执行，直接落到 return st.empty() 上，与「非空合法串」走的是完全不同的路径——漏掉它就漏掉了循环零次的边界情形，这正是边界值分析要求「取 0 个元素」的原因。类型不匹配（\"(]\"…"}],"works":[{"h":"用 include_directories() 做全局包含","d":"它是目录级命令，会把 include 路径泄漏给本目录及子目录的全部目标，第三方代码也被污染。 改用 target_include_directories(core PUBLIC ${CMAKE_CURRENT_SOURCE_DIR}/include)，把「谁能看到这个头」变成目标自己的属性（ex09 的 CM001）。"},{"h":"target_link_libraries() 漏写关键字","d":"写成 target_link_libraries(app core) 时依赖语义未声明，CMake 无法决定要不要传播使用要求，行为随策略版本漂移。 永远显式写 PUBLIC / PRIVATE / INTERFACE（ex09 的 CM006/CM007）。"},{"h":"把实现头写成 PUBLIC，把接口头写成 PRIVATE","d":"前者泄漏实现细节、拉长编译时间；后者让下游 #include 直接失败。 判据只有一条：这个头出现在我自己的公开头文件里吗？是 → PUBLIC，只在 .cpp 里用 → PRIVATE（ex10、ex15 的 HS001）。"},{"h":"用 set(CMAKE_CXX_STANDARD 17) 或 set(CMAKE_CXX_F…","d":"会污染 add_subdirectory 拉进来的第三方代码，且换编译器时 flag 直接失效。 用 target_compile_features(core PUBLIC cxx_std_17) 表达「我需要 C++17」，由构建系统挑 flag；编译选项用 target_compile_options(core PRIVATE .…"},{"h":"用 ${CMAKE_SOURCE_DIR} / ${PROJECT_SOURCE_DIR}…","d":"目标一旦被 install(EXPORT) 或被其它工程引用，绝对路径就失效。 一律用 ${CMAKE_CURRENT_SOURCE_DIR} + 相对路径，保证可重定位（ex09 的 CM008）。"},{"h":"file(GLOB) 收集源文件","d":"CMake 只在配置时展开一次，新增源文件不会触发重新配置，CI 上表现为「本地能编、CI 缺符号」。 显式列出源文件；确实要用 GLOB 就加 CONFIGURE_DEPENDS（ex09 的 CM005）。"},{"h":"测试只打印、不看退出码","d":"测试程序 return 0 写死，断言失败也照常「通过」，CI 永远绿。 测试入口必须返回「失败断言数 ? 1 : 0」，并让 CTest/流水线以该退出码为准（ex01/ex02 的 [CI] 退出码语义）。"},{"h":"用例之间共享静态/全局状态","d":"前一个用例写脏的状态被后一个用例读到，表现成「单独跑通过、整包跑失败」的假失败。 用夹具 SetUp/TearDown 给每个用例一个全新实例（ex05 的 shared_state_leak_demo）。"}],"asks":[{"q":"CMake 里 PUBLIC / PRIVATE / INTERFACE 到底有什么区别？什么时候用哪个？","a":"三个关键字控制的是使用要求（usage requirements）要不要向消费者传播，它们只影响 INTERFACE_ 那一批属性（INTERFACE_INCLUDE_DIRECTORIES、INTERFACE_COMPILE_DEFINITIONS、INTERFACE_COMPILE_FEATURES、INTERFACE_LINK_LIBRARIES）。 - PRIVATE：只有自己编译时可见…","fu":["为什么全局 set(CMAKE_CXX_STANDARD 17) 会污染 FetchContent 拉进来的第三方库？","INTERFACE 库不产生任何二进制产物，那 add_library(x INTERFACE) 的意义是什么？"],"tag":"通用/腾讯"},{"q":"为什么现代 CMake 不推荐 include_directories() / link_libraries()？它们到底错在哪？","a":"因为它们是目录级（directory-scope）命令，传播路径是目录树而不是依赖图。 - include_directories()：把 -I 加给当前目录及子目录里的全部目标，包括你 add_subdirectory 拉进来的第三方代码。 - link_libraries()：同理，把库链给全部目标。 - set(CMAKE_CXX_FLAGS ...) / set(CMAKE_CXX_STA…","fu":["target_compile_features 与直接加 -std=c++17 有什么本质区别？","如何验证你写的 install(EXPORT) 真的可用？"],"tag":"通用/华为"},{"q":"什么样的单元测试才算「好」？你的用例是怎么设计的？","a":"四个维度： ① 设计在前，编码在后。 先做等价类划分（有效/无效），再取边界值（正好边界、边界 ±1、以及 0 个元素这种空情形），最后才写代码。本章 ex03 的例子：6 个等价类、12 个边界点，用例数量由等价类决定而不是凭感觉凑。 ② 结构清晰（Arrange-Act-Assert）。 准备 → 执行 → 断言，一段用例里只做一次 Act，只断言可观察结果，不断言实现细节。用例名就是文档（s…","fu":["语句覆盖、判定覆盖、条件覆盖、路径覆盖，强度顺序是什么？100% 覆盖能说明没有 bug 吗？","整包跑失败、单独跑通过，你的排查顺序是什么？"],"tag":"通用/字节"},{"q":"时间、随机数、网络这类不可控依赖怎么测？stub、fake、mock 有什么区别？","a":"做法：不要在被测代码里直接取系统时间/随机数/网络，把它们抽成接口注入进来。 具体到时间：定义 IClock { virtual long long now_ms() const = 0; }，被测的 RateLimiter 只持有 const IClock&；生产注入 SystemClock（读 steady_clock），测试注入 FakeClock（advance(1000) 一步跨到下一个…","fu":["虚函数注入与模板注入怎么选？各自的代价是什么？","flaky test（偶发失败用例）你一般怎么处理？"],"tag":"通用/字节"}]},{"id":"cpp-ch20","subj":"cpp","title":"综合项目与面试冲刺：系统设计、代码规范与复盘","summary":"综合项目（如迷你 STL / 线程池 / HTTP 服务器）；代码规范与可读性；面试高频八股串讲；白板 coding 训练；学习路线复盘与进阶方向。","concepts":[{"id":"cpp-ch20/01-mini-stl-components","file":"01-mini-stl-components.md","title":"01 · 综合项目一：迷你 STL 组件（vector / shared_ptr / RAII）","kind":"flow","secs":[{"h":"一、迷你 vector：容量、移动与失效","s":"vector 的核心是连续内存 + 容量倍增。push_back 触发扩容时，新容量通常取 max(2old, need)，","c":null},{"h":"二、迷你 shared_ptr：控制块与循环引用","s":"shared_ptr 把对象与引用计数分开：对象在堆上，计数在独立的控制块里（见 ex03）。","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"cpp","code":"#include <iostream>\n#include <vector>\n#include <string>\n#include <memory>\n#include <atomic>\n#include <cstddef>\n#include <new>\n#include <utility>\n#include <type_traits>\n…"}}]},{"id":"cpp-ch20/02-concurrency-projects","file":"02-concurrency-projects.md","title":"02 · 综合项目二：线程池与简易 HTTP 服务器","kind":"timeline","secs":[{"h":"一、线程池：任务队列 + 条件变量 + 优雅关闭","s":"线程池 = 固定数量工作线程 + 一个线程安全任务队列（见 ex06）。提交任务即入队，空闲线程被","c":null},{"h":"可运行代码：线程池的三处关键细节","s":"线程池只有五十行，但锁外执行任务、锁外通知、析构时 notify_all 这三处任缺一个都会出问题：","c":{"lang":"cpp","code":"#include <condition_variable>\n#include <functional>\n#include <mutex>\n#include <queue>\n#include <stdexcept>\n#include <thread>\n#include <vector>\n\nclass ThreadPool {\n…"}},{"h":"二、简易 HTTP 请求行解析","s":"HTTP 请求行形如 METHOD SP URI SP HTTP/1.1 CRLF（见 ex07）。解析要做到确定性：只做字符串切分，","c":null}]},{"id":"cpp-ch20/03-code-style-and-exception-safety","file":"03-code-style-and-exception-safety.md","title":"03 · 代码规范与可读性：const 正确、RAII 与异常安全","kind":"flow","secs":[{"h":"一、异常安全等级（Basic / Strong / No-throw）","s":"异常安全有三档（见 ex08）：","c":null},{"h":"二、RAII 与所有权：把释放钉死在析构里","s":"RAII（Resource Acquisition Is Initialization）：资源在构造函数取得、在析构函数释放（见 ex05）。","c":null}]},{"id":"cpp-ch20/04-interview-cpp-fundamentals","file":"04-interview-cpp-fundamentals.md","title":"04 · 面试冲刺：C++ 高频八股串讲","kind":"stack","secs":[{"h":"一、虚函数表与对象模型（见 ex11）","s":"有虚函数的类，对象头部有一个 vptr 指向虚函数表（vtable）；调用虚函数经 vptr 间接寻址实现动态绑定。","c":null},{"h":"二、移动语义、RVO 与拷贝消除（见 ex09 / ex10）","s":"移动语义把资源所有权在拷贝成本高时转移而非复制（右值引用 + std::move）。","c":null},{"h":"三、STL 容器复杂度与迭代器失效（见 ex12）","s":"vector 随机访问 O(1)、尾部插入均摊 O(1)、中间插入 O(n)；list 插入删除 O(1) 但访问 O(n)。","c":null}]},{"id":"cpp-ch20/05-whiteboard-and-system-design","file":"05-whiteboard-and-system-design.md","title":"05 · 白板 coding 与系统设计题答法","kind":"flow","secs":[{"h":"一、白板 coding 训练法","s":"白板题（如 LRU Cache，见 ex13）的答法有固定套路：","c":null},{"h":"二、系统设计题答法","s":"C++ 岗的系统设计题通常偏高性能组件而非分布式架构，答法六步：","c":null}]},{"id":"cpp-ch20/06-project-interview-practical-recipes","file":"06-project-interview-practical-recipes.md","title":"综合项目与面试冲刺实战手记：凯喵带人做完 mini-STL 后总结的十二个现场","kind":"flow","secs":[{"h":"开场：会写代码和能交付代码之间的三道坎","s":"凯喵带过不少人做 mini-STL，发现卡点非常一致，都是三道：","c":{"lang":"cpp","code":"template <typename T>\nvoid Vector<T>::push_back(const T& v) {\n    if (size_ == cap_) {\n        T* p = allocator_.allocate(cap_ ? cap_ * 2 : 1);\n        for (size_t i = 0; i < size_; ++i) p[i] = std::move(data_[i]);  // ← 可能抛异常\n        allocator_.deallocate(data_, cap_);\n        data_ = p;\n        cap_ = cap_ ? cap_ * 2 : 1;\n    }\n…"}},{"h":"收尾：凯喵的收口三清单","s":"从\"会写\"到\"能交付\"，做三件事就够：","c":{"lang":"text","code":"故事一（深度）：mini-STL 里的异常安全\n  这是最能体现 C++ 功底的一个，因为它逼你面对「分配失败怎么办」这种真实问题\n\n故事二（广度）：并发任务池\n  体现你能把锁、条件变量、原子量组合成一个可用的东西，而不是只会背概念\n\n故事三（工程）：一次线上问题的完整排查\n  从现象、到定位工具（gdb / perf / sanitizer）、到根因、到修复与回归验证\n  这个故事的价值在于证明你「能独立负责一件事」"}}]}],"exams":[{"kind":"choice","q":"对 std::vector 调用 reserve(n) 之后，下列哪项一定成立？","stem":"已知 std::vector<int> v; v.reserve(100);，随后 auto p = v.data(); 并执行若干次 push_back。关于 p 与 capacity，哪项正确？","opts":[{"k":"A","t":"capacity() 恒为 100，p 始终有效"},{"k":"B","t":"size() 不超过 100 时 p 有效；一旦扩容，旧内存被释放，p 悬空"},{"k":"C","t":"reserve 之后 p 永远有效，因为 vector 不再搬移内存"},{"k":"D","t":"reserve(n) 会把 size() 也设为 n，因此 p 指向已构造的元素"}],"ans":"B","why":"reserve(n) 只保证 capacity()>=n，不保证地址不变；一旦 size 超过已分配容量触发扩容，data() 指向的旧内存被释放，p 悬空。对应 ex01。"},{"kind":"choice","q":"两个对象互相持有对方的 std::shared_ptr，会导致什么？","stem":"对象 A 持有 shared_ptr<B>，对象 B 持有 shared_ptr<A>，二者无其他外部引用。","opts":[{"k":"A","t":"引用计数仍能归零，两个对象都正常析构"},{"k":"B","t":"引用计数无法归零，两个对象都不析构，内存泄漏"},{"k":"C","t":"编译期报错，因为 shared_ptr 不允许互相持有"},{"k":"D","t":"只有先构造的那个对象泄漏，另一个正常析构"}],"ans":"B","why":"循环引用使双方 use_count 都 >=1，控制块引用计数无法归零，析构不被调用，内存泄漏。打破手段是改用 weak_ptr。对应 ex04。"},{"kind":"fix_error","q":"修复 shared_ptr 循环引用导致的内存泄漏","stem":"下列代码存在循环引用，请指出如何修改使其能正确析构。 cpp struct B; struct A { std::shared_ptr<B> b; ~A(){} }; struct B { std::shared_ptr<A> a; ~B(){} }; auto a = std::make_shared<A>(); auto b = std::make_shared<B>(); a->b = b;…","opts":[],"ans":"C","why":"只要环上有一方改成 weak_ptr（只观察、不增加强引用），环即被打破，控制块引用计数可归零。选项 C 描述最准确。对应 ex04。"},{"kind":"choice","q":"关于返回局部对象，下列哪种写法最推荐？","stem":"函数需要返回一个局部构造的大对象 obj。","opts":[{"k":"A","t":"return std::move(obj);"},{"k":"B","t":"return obj;"},{"k":"C","t":"return std::ref(obj);"},{"k":"D","t":"return new Obj(obj);"}],"ans":"B","why":"return obj;（有名局部对象）允许 NRVO/复制消除，编译器可在调用方栈帧直接构造；return std::move(obj) 反而强制移动构造、丧失 NRVO。对应 ex10。"},{"kind":"choice","q":"基类析构函数非 virtual 时，经基类指针 delete 派生对象会发生什么？","stem":"cpp struct Base { ~Base(){} }; struct Derived : Base { int p = new int[1024]; ~Derived(){ delete[] p; } }; Base b = new Derived(); delete b;","opts":[{"k":"A","t":"编译失败，因为基类析构函数不是 virtual"},{"k":"B","t":"未定义行为：只调用 Base 的析构，Derived 的析构与 p 的释放都不执行，内存泄漏"},{"k":"C","t":"运行期抛出 std::bad_cast"},{"k":"D","t":"编译器会自动补一个虚析构，行为与加了 virtual 相同"}],"ans":"B","why":"非 virtual 析构经基类指针 delete 只调静态类型（Base）的析构，Derived 部分不被析构，p 泄漏。类若会被继承并经基类指针释放，析构必须 virtual。对应 ex11。"},{"kind":"choice","q":"在 for 循环里对 vector 持续 push_back，同时持有元素指针，风险是？","stem":"std::vector<int> v; int p = &v[0]; for(...) v.push_back(x); 然后使用 p。","opts":[{"k":"A","t":"无风险，vector 保证元素地址在生命周期内稳定"},{"k":"B","t":"扩容时元素整体搬移、旧内存释放，p 悬空，解引用是未定义行为"},{"k":"C","t":"只会发生一次数据复制，p 仍指向有效副本"},{"k":"D","t":"p 会被自动更新为新地址"}],"ans":"B","why":"vector 扩容时整体搬移到新内存，旧 &v[0] 指向的内存被释放，p 悬空。这正是 ex12 演示的迭代器/引用失效。"},{"kind":"coding","q":"LRU Cache（仅存元数据与链接，不搬运题面）","stem":"设计并实现一个满足 LRU（最近最少使用）约束的缓存：get 与 put 均摊 O(1)。 （题面详见 LeetCode 原题，本项目按合规红线只存元数据与链接，不搬运题面正文。）","opts":[],"ans":"struct Node { int key, val; Node prev, next; }; class LRUCache { int cap; std::unordered_map<int, Node> m; Node head, tail; void touch(Node n){ / 摘除并移到 tail 前 /…","why":"用 list（或手写双向链表）维护使用顺序 + unordered_map 存 key->节点指针，get/put 均摊 O(1)。map 用 find 而非 [] 避免误插入。对应 ex13。"},{"kind":"coding","q":"实现一个支持优雅关闭的线程池 submit","stem":"实现一个固定 N 个工作线程的线程池：submit(F) 提交任务并返回 std::future； 提供 shutdown() 优雅关闭——先置停止标志、唤醒所有线程、再 join，保证在飞任务跑完。","opts":[],"ans":"#include <queue><thread><mutex><condition_variable><functional><future> class ThreadPool { std::queue<std::function<void()>> q; std::mutex m; std::condition_var…","why":"任务队列用 mutex+condvar 保护；cv.wait 用 while 语义（谓词）防虚假唤醒；shutdown 先置 stop 再 notify_all 再 join，在飞任务自然跑完。对应 ex06。"}],"works":[{"h":"对象切片（slicing）","d":"把派生类对象按值赋给基类对象，派生部分被切掉，多态失效。多态必须靠指针/引用传递（对应 ex11）。 13. 基类析构函数非 virtual 时，经基类指针 delete 派生对象只调基类析构，派生资源泄漏；只要类会被继承并经基类指针释放，析构必须 virtual（对应 ex11）。 14. vector::erase 使被删及之后元…"}],"asks":[{"q":"虚函数是怎么实现的？为什么对象切片会丢失多态？基类析构为什么通常要 virtual？","a":"有虚函数的类，对象头部有一个 vptr 指向虚函数表（vtable），每个类型一份；调用虚函数经 vptr 查表实现动态绑定。 对象切片把派生类按值赋给基类对象，派生部分被切掉，只剩基类子对象，vptr 也变成基类的，多态从此失效——所以多态必须经指针/引用。 基类析构非 virtual 时，经基类指针 delete 派生对象只调基类析构，派生资源泄漏；只要类会被继承并经基类指针释放，析构必须 v…","fu":["vtable 存在哪里、每个对象都有一份吗","虚函数调用为什么不能被内联"],"tag":"字节/腾讯"},{"q":"移动语义解决了什么？RVO / 复制消除是什么？为什么不要 return std::move(obj)？","a":"移动语义在拷贝成本高时转移资源所有权而非复制（右值引用 + std::move），把 O(n) 拷贝降到 O(1) 指针交换。 RVO/NRVO（返回值优化）与复制消除是编译器允许的省略拷贝：在调用方栈帧直接构造返回对象，连移动都不需要。 在会走 NRVO 的返回处写 return std::move(obj) 会强制走移动构造，反而丧失 NRVO 机会并多一次移动。正确写法就是 return o…","fu":["std::move 本身生成什么代码","什么情况下移动会失败退化成拷贝"],"tag":"阿里/美团"},{"q":"shared_ptr 的引用计数存在哪？循环引用怎么解决？weak_ptr 的 lock 为什么要判空？","a":"shared_ptr 把对象与控制块（含强/弱引用计数）分开；make_shared<T>() 一次分配两者，shared_ptr<T>(new T) 分两次分配。 循环引用使双方 use_count 永不为 0，析构永不触发 -> 内存泄漏，打破手段是用 weak_ptr 持有环上一方。 weak_ptr::lock() 取 shared_ptr，若对象已析构返回空，必须判空再解引用。 （对应…","fu":["控制块什么时候释放","enable_shared_from_this 干嘛用"],"tag":"腾讯/百度"},{"q":"什么是异常安全的三档保证？RAII 如何帮助实现它们？","a":"基本保证：异常后对象有效但未指定，无泄漏；强保证：异常后状态完全不变（事务语义，用 copy-and-swap）；不抛（noexcept）：析构/move/swap 应 noexcept。 RAII 把资源释放钉死在析构函数里，栈展开时确定性释放，从语言层面消除忘了释放，是基本保证的基石。 （对应 ex05 / ex08）","fu":["copy-and-swap 为什么能给强保证","析构抛异常为什么 terminate"],"tag":"微软/华为"}]}];

